a' \arrow[dr, "\alpha"'] & & a'_1 \arrow[dl, "\alpha_1"] & & \underline{above} & R' \arrow[dr] & & R' \arrow[dl] \\
 & a & & & & & R &

\underline{in}  $\underline{A}$  \underline{where}  $\alpha_1$  \underline{is a small prolongation.} \underline{Assume that}  $a$  \underline{is versal for small} \underline{prolongations of}  $e$  . \underline{Then there exists a map}  $a' \xrightarrow{\ \rho\ } a_1$  \underline{such that}  $\alpha = \alpha_1 \rho$ \underline{in}  $\underline{A}$  \underline{if and only if there exists a map}  $f : P(a') \rightarrow P(a_1)$  \underline{such that} $P(\alpha) = P(\alpha_1)\cdot f$  \underline{in}  $\underline{C}_{\Lambda}$  .

\underline{Proof}:  Assume that  $P(\alpha) = P(\alpha_1)\cdot f$  where  $f : P(a') \rightarrow P(a_1)$  . Replacing  $a'$ by its direct image under  $f$  , we may and shall assume that  $P(\alpha) = P(\alpha_1)$  . Set  $R' = P(a_1)$  ,  $R = P(a)$  . Since  $\underline{A}$  is semi-homogeneous, we get a commutative diagram

\begin{center}
\begin{tikzcd}[row sep=large, column sep=small]
 & a'' \arrow[dl, "\beta"'] \arrow[dr, "\beta_1"] & & & & & R'\underset{R}{\times}R' \arrow[dl] \arrow[dr] & \\
a' \arrow[dr, "\alpha"'] & & a_1 \arrow[dl, "\alpha_1"] & & \text{above} & R' \arrow[dr] & & R' \arrow[dl] \\
 & a & & & & & R &
\end{tikzcd}
\end{center}

\begin{center}
\begin{tikzcd}[column sep=small]
0 \arrow[r] & J/MJ \arrow[r] \arrow[d, "h"] & S/MJ \arrow[r] \arrow[d, "h_1"] & R \arrow[r] \arrow[d, equal] & 0 \\
0 \arrow[r] & k \arrow[r] & R_1 \arrow[r] & R \arrow[r] & 0
\end{tikzcd}
\end{center}

before:
\smallskip
\noindent\textbf{(1)} $f$ is flat and
$\dim_xX_{f(x)}=n$ for every $x\in X$;

after:
Let  $P : \underline{A} \to \underline{C}_\wedge$  be a cofibered category (in groupoids). It is then clear that we obtain a cofibered category  $\mathrm{pro}(P) : \mathrm{pro}(\underline{A}) \to \mathrm{pro}(\underline{C}_\wedge)$  (in groupoids) (pour la définition de la catégorie de pro-objets  $\mathrm{pro}(\underline{A})$  , voir A. Grothendieck, Sém. Bourbaki 195).

\begin{center}
\begin{tikzcd}
\underline{A} \arrow[r] \arrow[d, "P"'] & \mathrm{pro}(\underline{A}) \arrow[d, "\mathbf{pro}(P)"] \\
\underline{C}_\wedge \arrow[r] & \mathrm{pro}(\underline{C}_\wedge)

Now let  $\widehat{\underline{C}}_\wedge$  be the full subcategory of  pro-$\underline{C}_\wedge$  in which $\mathrm{ob}(\widehat{\underline{C}}_\wedge) = \{(R_i)_{i \in \underline{N}}$  ,  $R_i \in \mathrm{ob}(\underline{C}_\wedge) \mid \varphi_i : R_i \to R_{i-1}$  is surjective for all  $i$  and induces isomorphisms  $\underline{m}_i/\underline{m}_\wedge + \underline{m}_i^2 \to \underline{m}_{i-1}/\underline{m}_\wedge + \underline{m}_{i-1}^2$  for all sufficiently large  $i$  $\}$ where  $\underline{N}$  stands for the ordered category of natural numbers, and  $\underline{m}_i$  is the maximal ideal of  $R_i$  . We set  $\widehat{\underline{A}}$  to be the full subcategory of pro-$\underline{A}$  in which

\begin{equation*}
\mathrm{ob}(\widehat{\underline{A}}) = \{a \in \mathrm{ob}(\mathrm{pro}(\underline{A})) \mid \mathrm{pro}(P)\ (a) \in \mathrm{ob}(\widehat{\underline{C}}_\wedge)\}
\end{equation*}
We then obtain a cofibered category  $\widehat{P} : \widehat{\underline{A}} \to \widehat{\underline{C}}_\wedge$  (in groupoids) with a commutative diagram

\begin{center}
\begin{tikzcd}
\underline{A} \arrow[r, hook] \arrow[d, "P"'] & \widehat{\underline{A}} \arrow[d, "\widehat{P}"] \\
\underline{C}_\wedge \arrow[r, hook] & \widehat{\underline{C}}_\wedge
\end{tikzcd}
\end{center}










We note that the category  $\widehat{\underline{C}}_\wedge$  is canonically equivalent to the category of complete local $\wedge$-algebras of formally finite type over  $\wedge$  with the fixed residue field  $k$  . Henceforth we shall make such identification.

\underline{Definition} 1.9.   \underline{Let}  $\underline{A}$  \underline{be a cofibered groupoid over}  $\underline{C}_\wedge$  . \underline{An object}  $\xi$  \underline{in} $\widehat{\underline{A}}$  \underline{is called a quasi-initial object of}  $\widehat{\underline{A}}$  \underline{if for every object}  $a$  \underline{in}  $\widehat{\underline{A}}$  \underline{there exists a map}  $\xi \to a$  \underline{in}  $\widehat{\underline{A}}$  . \underline{A quasi-initial object}  $\xi$  \underline{of}  $\widehat{\underline{A}}$  \underline{is called minimal}

\underline{if the morphism}  $\xi : h_R \to [\hat{\underline{A}}]$  \underline{induces a bijection} $\xi(k[\epsilon])$: $\mathrm{Hom}_{\wedge\text{-alg}}(R,k[\epsilon]) \to [\underline{A}(k[\epsilon])]$ , \underline{where} $R = P(\xi)$ . \underline{An object} $\xi$ \underline{in} $\hat{\underline{A}}$ \underline{is called a versal formal object of} $\underline{A}$ \underline{if every surjective map} $\alpha : a' \to a$ \underline{in} $\underline{A}$ \underline{induces a surjective map} $\mathrm{Hom}_{\hat{\underline{A}}}(\xi,a') \to \mathrm{Hom}_{\hat{\underline{A}}}(\xi,a)$ .

\underline{A versal formal object} $\xi$ \underline{of} $\underline{A}$ \underline{is called minimal if the morphism} $\xi : h_R \to [\hat{\underline{A}}]$ \underline{induces a bijection} $\xi(k[\epsilon]) : \mathrm{Hom}_{\wedge\text{-alg}}(R,k[\epsilon]) \to [\underline{A}(k[\epsilon])]$ \underline{where} $R = P(\xi)$ .

\underline{Proposition} 1.10.  \underline{Let} $\underline{A}$ \underline{be a cofibered groupoid over} $\underline{C}_{\wedge}$ .

  (i)  \underline{every (minimally) versal formal object of} $\underline{A}$ \underline{is a quasi-initial (minimal) object of} $\hat{\underline{A}}$ .

  (ii) \underline{If} $\xi$ \underline{is an object in} $\hat{\underline{A}}$ \underline{such that} $\widetilde{\xi}(k[\epsilon])$: $\mathrm{Hom}_{\wedge\text{-alg}}(R,k[\epsilon])\to [\underline{A}(k[\epsilon])]$ \underline{is injective, where} $P(\xi) = R$ , \underline{then every endomorphism of} $\xi$ \underline{in} $\hat{\underline{A}}$ \underline{is an automorphism. In particular a quasi-initial minimal object of} $\hat{\underline{A}}$ , \underline{if it exists, is unique up to (non-canonical) isomorphism.}

\underline{Proof}: (i) let $\xi$ be a versal formal object of $\underline{A}$ . We must show that, for any object $a$ in $\hat{\underline{A}}$ , we have a map $\xi \to a$ . By the definition of $\hat{\underline{A}}$ , there exists a sequence of surjective maps in $\underline{A}$ : $--- \to a_n \xrightarrow{\ \alpha_n\ } a_{n-1} \to --- \to a_1 \overset{\alpha_1}{\relbar\joinrel\relbar} a_0$ such that $a = \varprojlim_n a_n$ . Assume that there exist maps $\varphi_i : \xi \to a_i$ such that $\alpha_i\varphi_i = \varphi_{i-1}$ for all $i < n$ . Since $\xi$ is a versal formal object of $\underline{A}$ and $\alpha_n : a_n \to a_{n-1}$ is surjective in $\underline{A}$ , we obtain a map $\xi \xrightarrow{\ \varphi_n\ } a_n$ such that $\alpha_n\varphi_n = \varphi_{n-1}$ . If we set $\varphi = \varprojlim_n \varphi_n$ , we have $\varphi : \xi \to a$ .

(ii) Let $\xi \xrightarrow{\ \alpha\ } \xi$ be a map in $\hat{A}$ . Then for every $\lambda \in \mathrm{Hom}_{\wedge\text{-alg}}(R,k[\epsilon])$ we have $\lambda_*\xi = \lambda_*\alpha\xi \simeq (\lambda\cdot P(\alpha))_*\xi$ and hence by the hypothesis on $\xi$ we have that $\lambda = \lambda\cdot P(\alpha)$ for all $\lambda \in \mathrm{Hom}_{\wedge\text{-alg}}(R,k[\epsilon])$ , and therefore $P(\alpha) : R \to R$ is surjective. However it is trivial to see that every surjective endomorphism of a noetherian ring is always an automorphism and hence $P(\alpha)$ is an automorphism of $R$ and therefore $\alpha$ is an automorphism of $\xi$ .

\underline{Theorem} 1.11. (Schlessinger) \underline{Let} $\underline{A}$ \underline{be a cofibered groupoid over} $\underline{C}_{\Lambda}$ . \underline{Then} $\underline{A}$

\underline{admits a minimally-versal formal object if and only if}

  (i)  $\underline{A}$  \underline{is semi-homogeneous}

  (ii)  $[\underline{A}(k[\epsilon])]$  \underline{is a finite-dimensional vector space over}  $k$  (cf. 1.3(c)).

\underline{Proof}; (\underline{Necessity}) Let $\xi$ in $\hat{\underline{A}}$ be a minimally-versal formal object of $\underline{A}$ , and consider a diagram

\begin{center}
\begin{tikzcd}[column sep=small, row sep=large]
 a_1 \arrow[dr] & & a_2 \arrow[dl, "\alpha"] \\
 & a &
\end{tikzcd}
\end{center}

in $\underline{A}$ where $\alpha$ is surjective. Since $\xi$ is a quasi-initial object of $\hat{\underline{A}}$ , there exists a map $\xi \to a_1$ . Since $\alpha$ is surjective, the composite map $\xi \to a_1 \to a$ can be lifted to $a_2$ i.e., we obtain a commutative diagram

\begin{center}
\begin{tikzcd}[column sep=small, row sep=large]
 & \xi \arrow[dl] \arrow[dr] & \\
 a_1 \arrow[dr] & & a_2 \arrow[dl, "\alpha"] \\
 & a &
\end{tikzcd}
\end{center}

which proves the condition 1.2(1). We now prove the condition 1.2(2). Let

\begin{center}
\begin{tikzcd}[column sep=large]
 & S \\
 S{\times}_k k[\epsilon] \arrow[ur, "\pi_1"] \arrow[dr, "\pi_2"'] & \\
 & k[\epsilon]
\end{tikzcd}
\end{center}

be the projections,

and let

\begin{center}
\begin{tikzcd}[column sep=small, row sep=large]
 a' \arrow[dr, "\alpha"'] & & b' \arrow[dl, "\beta"] \\
 & a &
\end{tikzcd}
\end{center}

be $\pi_1$-maps in $\underline{A}$ . By the definition of $\xi$ , we obtain a commutative diagram

\begin{center}
\begin{tikzcd}[column sep=small, row sep=large]
 & \xi \arrow[dl, "u"'] \arrow[dr, "v"] & \\
 a' \arrow[dr, "\alpha"'] & & b' \arrow[dl, "\beta"] \\
 & a &
\end{tikzcd}
\end{center}

and in particular we have $\pi_1\cdot P(u) = \pi_1\cdot P(v)$ . Assume now that $(\pi_2)_*a' \approx (\pi_2)_*b'$ . We then have $\pi_2\cdot P(u) = \pi_2\cdot P(v)$ because of the minimality of

$\xi$ , and hence  $P(u) = \pi_1 P(u)\times \pi_2 P(u) = \pi_1 P(v)\times \pi_2 P(v) = P(v)$  . Since  $\underline{A}$  is a cofibered groupoid, we obtain a unique isomorphism  $a' \overset{\sigma}{\to} b'$  in $\underline{A}(S\times_k k[\epsilon])$  such that  $\sigma u = v$  . Then  $\beta\sigma u = \alpha u$  entails that  $\beta\sigma= \alpha$  since  $\underline{A}$ is a cofibered category.

(\underline{Sufficiency}) Let  $c_1,c_2,\dots,c_n$  be objects in  $\underline{A}(k[\epsilon])$  which form a $k$-basis of the vector space  $[\underline{A}(k[\epsilon])]$  , and choose  $a_1$  in  $\underline{A}(k[\epsilon]\times_k\dots\times_k k[\epsilon])$ such that  $(\pi_j)_* a_1 \approx c_j$  . Then  $\tilde{a}_1(k[\epsilon]) : \mathrm{Hom}_{\Lambda\text{-alg}}(R_1,k[\epsilon]) \to [\underline{A}(k[\epsilon])]$  is bijective, where  $R_1 = P(a_1)$  . In particular  $a_1 \to e$  is versal for small prolongations of  $e$  . Choose  $a_2 \to a_1$  which is versal for small prolongations of  $a_1$ such that  $\overline{\Omega}_{a_2} \to \overline{\Omega}_{a_1}$  is bijective. We then choose  $a_3 \to a_2$  , versal for small prolongations of  $a_2$  such that  $\overline{\Omega}_{a_3} \to \overline{\Omega}_{a_2}$  is bijective etc., and set $\xi = \underset{n}{\underleftarrow{\mathrm{Lim}}}\, a_n$  . We claim that  $\xi$  is a minimally-versal formal object of  $\underline{A}$  . Indeed, since  $\overline{\Omega}_{a_n} \to \overline{\Omega}_{a_{n-1}}$  is bijective, for all  $n$  ,  $\overline{\Omega}_{\xi} \to \overline{\Omega}_{a_1}$  is bijective so that $\xi(k[\epsilon]) : \mathrm{Hom}_{\Lambda\text{-alg}}(R,k[\epsilon]) \to [\underline{A}(k[\epsilon])]$  is bijective. Now consider a diagram

\begin{center}
\begin{tikzcd}
 & a' \arrow[d, "\alpha"] \\
\xi \arrow[r, "h"] & a
\end{tikzcd}
\end{center}

where  $\alpha$  is surjective in  $\underline{A}$  . We must show that  $h$  can be lifted to  $a'$  . For this, one may assume, by induction, that  $a'$  is a small prolongation of  $a$  . Since  $P(a)$  is an artinian ring,  $h : \xi \to a$  is factored as a composite map $\xi \to a_q \longrightarrow a$  for some  $q$  . Since  $\underline{A}$  is semi-homogeneous, we get a diagram

\begin{center}
\begin{tikzcd}
 & a'' \arrow[r] \arrow[d, "\alpha'"] & a' \arrow[d, "\alpha"] \\
\xi \arrow[r] & a_q \arrow[r] & a
\end{tikzcd}
\end{center}

where  $\alpha'$  is also a small prolongation. We then obtain a commutative diagram

\begin{center}
\begin{tikzcd}
 & & a'' \arrow[d, "\alpha'"] \\
\xi \arrow[r] & a_{q+1} \arrow[r] \arrow[ur] & a_q
\end{tikzcd}
\end{center}

and therefore we are done.

\underline{Remark} 1.12.  Let

\begin{tikzcd}
\dots\dots \arrow[r] & a_n \arrow[r] & a_{n-1} \arrow[r] & \dots \arrow[r] & a_2 \arrow[r] & a_1 \arrow[r] & a_o = e
\end{tikzcd}

be an infinite sequence of arrows in  $\underline{A}$  such that

\begin{equation*}
\left\{\begin{array}{l}
a_i \ \text{ is versal for small prolongations of } \ a_{i-1} \\[2pt]
P(a_i) \longrightarrow P(a_{i-1}) \ \text{ is surjective} \\[2pt]
\overline{\Omega}_{a_i} \dashrightarrow \overline{\Omega}_{a_{i-1}} \ \text{ is bijective for } \ i >> 0
\end{array}\right.
\end{equation*}
Then the above proof shows that  $\underleftarrow{\mathrm{Lim}}\, a_i$  is a versal formal object of  $\underline{A}$  .

\underline{Remark} 1.13.  Let  $\underline{A}$  be a cofibered groupoid over  $\underline{C}_\wedge$  . If  $\underline{A}$  has the property 1.11(i) and (ii), then so does  $[\underline{A}]$  , and  $\xi \in \mathrm{ob}(\hat{\underline{A}})$  is a minimally-versal formal object of  $\underline{A}$  if and only if it is so for  $[\underline{A}]$  by 1.10(ii).

\underline{Remark} 1.14.  Let  $\underline{A}$  be a cofibered groupoid over  $\underline{C}_\wedge$  , admitting a minimally-versal formal object  $\xi$  . Then an invariant of  $R = P(\xi)$  , which is a complete local  $\wedge$-algebra of formally finite type over  $\wedge$  , is automatically an invariant of  $\underline{A}$  over  $\underline{C}_\wedge$  . Therefore, for example, we shall say that  $\underline{A}$  is (formally) smooth over  $\underline{C}_\wedge$  if  $R$  is (formally) smooth over  $\wedge$  i.e., a formal power-series algebra over  $\wedge$  , or we say that  $\underline{A}$  is irreducible over  $\underline{C}_\wedge$  if  $\mathrm{Spec}(R)$  is irreducible etc. In the next section we introduce the notion of  "smoothness"  of a functor  $\underline{A} \to \underline{B}$  over  $\underline{C}_\wedge$  , where  $\underline{A}, \underline{B}$  are cofibered categories in groupoids over  $\underline{C}_\wedge$  . It turns out (cf. 2.4) that  "$\underline{A}$  is (formally) smooth over  $\underline{C}_\wedge$"  is equivalent to  " $P : \underline{A} \to \underline{C}_\wedge$  is a smooth functor"  , and therefore no confusion arises. We also define the dimension of  $\underline{A}$  over  $\underline{C}_\wedge$  by  $\dim_{\underline{C}_\wedge} \underline{A} = \dim\, k \otimes_\wedge R$  . For this we note the following fact:  Let  $\underline{C}_k$  be the category of artinian local $k$-algebras with the same residue field  $k$  . Then  $\underline{C}_k \to \underline{C}_\wedge$  is a fully-faithful imbedding, whose (left) adjoint functor  $\underline{C}_\wedge \to \underline{C}_k$  is given by  $R \to k \otimes_\wedge R$  . Let $\underline{A}|\underline{C}_k$  be the pull-back of  $P : \underline{A} \to \underline{C}_\wedge$  under  $\underline{C}_k \to \underline{C}_\wedge$  . Then it is trivial to see that if  $\xi$  is a minimally-versal formal object for  $\underline{A}$  over  $\underline{C}_\wedge$  , then  $k \otimes_\wedge \xi$ is a minimally-versal formal object for  $\underline{A}|\underline{C}_k$  over  $\underline{C}_k$  , where  $\xi \to k \otimes_\wedge \xi$  is a cocartesian arrow above  $R \to k \otimes_\wedge R$  . It follows that  $\dim_{\underline{C}_\wedge} \underline{A} = \dim_{\underline{C}_k} (\underline{A}|\underline{C}_k)$  .




1.15.  In the remaining of this paragraph, we briefly explain how to modify the preceding theory in order to allow for residue field extensions.

Let $\Lambda$ and $K$ be complete noetherian local rings, with $K$ a $\Lambda$-algebra. We assume that

(a)  the natural map from $\Lambda$ to $K$ is a local homomorphism;

(b)  the residue field $K'$ of $K$ is an extension of finite type of the residue field $k$ of $\Lambda$ .

The most interesting case is when $K = K'$ and $K$ is a finite inseparable extension of $k$ .

We denote by $\hat{C}_{\Lambda,K}$ the category whose objects are the complete noetherian local rings $R$ , provided with a structure of $\Lambda$-algebra and with a $\Lambda$-epimorphism $s : R \longrightarrow K$ .

We denote by $C_{\Lambda,K}$ the subcategory of $\hat{C}_{\Lambda,K}$ consisting of the $(R, s)$ such that $\mathrm{Ker}(s)$ is a $R$-module of finite length. The category $\hat{C}_{\Lambda,K}$ can be identified with a full subcategory of $\mathrm{Pro}(C_{\Lambda,K})$ .

If $K$ is artinian, so is any object in $C_{\Lambda,K}$ .

For any finite dimensional vector space $V$ over $K'$ we denote by $D_V(K)$ the algebra of dual numbers over $K$ defined by $V$ ; its elements are of the form $k + v\,\varepsilon$ (with $k \in K$ , $v \in V$ and $\varepsilon^2 = 0$ : $(k + v\,\varepsilon)\,(k' + v'\,\varepsilon) = (k\,k') + (k\,v' + k'\,v)\varepsilon$  ). The map $s : D_V(K) \to K$ : $s(k + v\,\varepsilon) = k$ , turns $D_V(K)$ into an object of $C_{\Lambda,K}$ . The role played before by $k[\varepsilon]$ will be played here by $D_{K'}(K)$ .

As explained in 1.8, any cofibered groupoid $\underline{A}$ over $C_{\Lambda,K}$ extends in a natural way to a cofibered category $\hat{\underline{A}}$ over $\hat{C}_{\Lambda,K}$ . A map in $\underline{A}$ or $\hat{\underline{A}}$ will be called \underline{surjective} if the corresponding homomorphism of algebras in $C_{\Lambda,K}$ or in $\hat{C}_{\Lambda,K}$ is.



\underline{We assume that} $\underline{A}(K) = \{e\}$ .

\underline{Definition} 1.16.  \underline{A cofibered groupoïd} $\underline{A}$ \underline{over} $C_{\Lambda,K}$ \underline{is called} \underline{semi-homogeneous} \underline{if the following properties hold:}

(I)  \underline{every diagram}

\begin{center}
\begin{tikzcd}[row sep=large, column sep=large]
a'' \arrow[r, dashed] \arrow[d, dashed] & a' \arrow[d] \\
a_1 \arrow[r] & a
\end{tikzcd}
\end{center}











\underline{of solid arrows in} $\underline{A}$ , \underline{where} $a' \longrightarrow a$ \underline{is surjective, can be completed into} \underline{a commutative diagram including dotted arrows;}

(II)  \underline{For any} $R$ , \underline{the natural map}

\begin{equation*}
[\underline{A}(R \times_K D_{K'}(K))] \to [\underline{A}(R) \times \underline{A}\,(D_{K'}(K))] \simeq [\underline{A}(R)] \times [\underline{A}(D_{K'}(K))]
\end{equation*}
\underline{is bijective.}

If $\underline{A}$ is semi-homogeneous, so is $[\underline{A}]$ .

1.17.  Let us first consider the restriction of $\underline{A}$ to the full subcategory of $C_{\Lambda,K}$ whose objects are the $D_V(K)$ . Let $\Omega$ be the vector space $\Omega^1_{K/\Lambda} \otimes_K K'$ , and $d : K \to \Omega$ the derivative. A map $f : D_V(K) \to D_W(K)$ can be written:

\begin{equation*}
f(k + v\,\varepsilon) = k + (u(v) + D\,d\,k)\,\varepsilon
\end{equation*}
with $u \in \mathrm{Hom}_{K'}(V, W)$ and $D \in \mathrm{Hom}_{K'}(\Omega, W)$ . If we identify $f$ with $(u, D)$ , the composition law is

\begin{equation*}
(u, D) \circ (u', D') = (uu', D + u\,D')\ .
\end{equation*}
The condition (II) entails

(II')  the functor from $K'$-vector spaces to sets

\begin{equation*}
V \longmapsto [\underline{A}(D_V(K))]
\end{equation*}
commutes with products.

\underline{Lemma} 1.18.  \underline{Assume condition} (II') \underline{is satisfied by} $\underline{A}$ . \underline{Then}

(1)  $[\underline{A}(D_{K'}(K))]$  \underline{carries a unique vector space structure, such that}  $[\underline{A}(D_{V}(K))] \simeq V \otimes_{K'} [\underline{A}(D_{K'}(K))]$  \underline{as a functor in}  $V$ .

(2)   \underline{There is a linear map}  $\gamma : \operatorname{Hom}(\Omega,K') \rightarrow [\underline{A}(D_{K'}(K))]$  \underline{such that, for any}  $D \in \operatorname{Hom}(\Omega, K')$  ,

\begin{equation*}
[\underline{A}((1, D))] : [\underline{A}(D_{K'}(K))] \rightarrow [\underline{A}(D_{K'}(K))] \quad \text{is} \quad x \longmapsto x + \gamma(D) \quad .
\end{equation*}
(3)   \underline{For any}  $(u, D) : D_{V}(K) \longrightarrow D_{W}(K)$  , \underline{the map}

\begin{equation*}
(u, D) : [\underline{A}(D_{V}(K))] \rightarrow [\underline{A}(D_{W}(K))] \quad \text{i.e.}
\end{equation*}
\begin{equation*}
(u, D) : V \otimes [\underline{A}(D_{K'}(K))] \rightarrow W \otimes [\underline{A}(D_{K'}(K))] \quad \underline{\text{is}}
\end{equation*}
\begin{equation*}
x \longmapsto u(x) + \gamma(D) \quad .
\end{equation*}
Let us introduce the notations

\begin{equation*}
\begin{aligned}
F(V) \quad &= \quad [\underline{A}(D_{V}(K))] \\
A \quad &= \quad F(K') \\
F(u,D) : F(V) \rightarrow F(W) \quad &= \ \text{the map induced by} \ \ (u,D) : D_{V}(K) \rightarrow D_{W}(K) \\
F(D) \quad : F(V) \rightarrow F(V) \quad &: \quad F(D) = F(1, D) \quad .
\end{aligned}
\end{equation*}
By (II') and the fact that  $K'$  is a  $K'$-vector space object in the category of $K'$-vector spaces,  $F(K')$  is a  $K'$-vector space in (Ens), hence a  $K'$-vector space, and (1) is clear. Let us now identify  $F(V)$  and  $V \otimes A$  .

We deduce from the identity

\begin{equation*}
(u, D) = (1, D) \circ (u, 0) \quad \text{that}
\end{equation*}
\begin{equation*}
F(u, D) = F(D) \circ (u \otimes 1_{A}) \quad .
\end{equation*}
The functoriality of  $F$  amounts to

\begin{equation*}
\begin{aligned}
F(0) &= \mathrm{Id} \\
F(D) \circ F(D') &= F(D + D') \\
(u \otimes 1) \circ F(D) \ &= F(u\,D) \circ (u \otimes 1_{A})
\end{aligned}
\end{equation*}
For any  $D : \Omega \rightarrow V$  and any  $n \in N$  , if  $i$  and  $p$  are the maps

\begin{equation*}
i \ ; \ V \lhook\joinrel\longrightarrow V \oplus K'^{\,n} \qquad\qquad p : V \oplus K'^{\,n} \longrightarrow K'^{\,n} \quad , 
\end{equation*}



 then  $p i D = 0$  and the following diagram is commutative

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=large]
V \otimes A \arrow[r] \arrow[d, "F(D)"] & (V \oplus K'^{\,n}) \otimes A \arrow[r] \arrow[d, "{F(i\,D)}"] & K'^{\,n}\!\otimes A \arrow[d, equal] \\
V \otimes A \arrow[r] & (V \oplus K'^{\,n}) \otimes A \arrow[r] & K'^{\,n}\!\otimes A
\end{tikzcd}
\end{center}













Let  $x : K'^{\,n} \rightarrow V$  be a map,  $x_{i} = x(e_{i})$  , and let  $a_{i}$  be a family of elements of  $A$  . We have  $(1_{V} + x) \circ i \circ D = D$  . Hence, if

\begin{equation*}
F(i\,D)\ (\Sigma\ e_{i}\ a_{i}) = \Sigma\ e_{i}\ a_{i} + a \qquad (a \in V \otimes A) \quad , \ \text{then}
\end{equation*}
\begin{equation*}
F(D)\ (\Sigma\ x_{i}\ a_{i}) \ = \Sigma\ x_{i}\ a_{i} + a
\end{equation*}
and  $a$  does not depend on the  $x_{i}$  . Hence,

\begin{equation*}
\begin{aligned}
F(D)\ (y) \ &= y + G(D) &&\qquad , \ \text{with} \\
G(D + D') &= G(D) + G(D') & \\
u\ G(D) \quad &= G(u\,D) &&\qquad (\text{for any} \ \ u : V \rightarrow W) \quad .
\end{aligned}
\end{equation*}
One easily checks that any such  $G$  is defined, for some  $\gamma \in \Omega \otimes A$  , by the formula

\begin{equation*}
G(D) = D \otimes 1_{A}\ (\gamma) \quad ,
\end{equation*}
as promised in (2) (3).

\underline{Definition} 1.19.   (1) \underline{An object}  $\xi$  \underline{in}  $\widehat{\underline{A}}$  \underline{is called}   \underline{versal formal object if} \underline{every surjective map}  $\alpha : a' \longrightarrow a$  \underline{in}  $\underline{A}$  \underline{induces a surjective map}

\begin{equation*}
\operatorname{Hom}_{\widehat{\underline{A}}}(\xi, a') \longrightarrow \operatorname{Hom}_{\widehat{\underline{A}}}\ (\xi, a) \quad .
\end{equation*}
(2)   \underline{A formal versal object}  $\xi$  \underline{in}  $\widehat{A}$  , \underline{with image}  $(R, s)$  \underline{in}  $\widehat{C}_{\Lambda,K}$  , \underline{is} \underline{called  minimal  if for any two maps}  $\varphi_{1}$ , $\varphi_{2} : R \rightrightarrows D_{K'}(K)$  , \underline{if}  $\varphi_{1}(\xi)$  \underline{is iso-} \underline{morphic to}  $\varphi_{2}(\xi)$  , \underline{then there exists a derivation}  $D$  \underline{of}  $K$  \underline{into}  $K'$  \underline{such that}  $(1, D)\ (\varphi_{1}) = \varphi_{2}$  , i.e.  $\varphi_{2}\text{-}\varphi_{1} = D\,s$  .

\underline{Theorem} 1.20.   \underline{If}  $\underline{A}$  \underline{is semi-homogeneous and if}  ,

\begin{equation*}
\dim_{K'}\ ([A(D_{K'}(K))]) < \infty \quad ,
\end{equation*}
\underline{then}  $\underline{A}$  \underline{admits a minimally versal formal object, and any two of them are}

\underline{isomorphic}.

With the notations of 1.18, let  $H^*$  be a subspace of  $[\underline{A}(D_{K'}(K))]$ , supplementary to the image of  $\gamma$ , and let  $H$  be the dual of  $H^*$ . We define $R_o = D_H(K)$ . Let  $\xi_o$  be an object in  $\underline{A}(R_o)$ , whose image in $[\underline{A}(R_o)] \simeq H \otimes [\underline{A}(D_{K'}(K))] \simeq \operatorname{Hom}(H^*,[\underline{A}(D_{K'}(K))])$  is the inclusion of  $H^*$  in $[\underline{A}(D_{K'}(K))]$ . Then

(1)  The maps  $\operatorname{Hom}_{C_{\wedge,K}}(D_H(K),\ D_V(K)) \longrightarrow [\underline{A}(D_V(K))]$  are surjective .

(2)  The minimality condition 1.19(2)  is valid for  $(R_o,\ \xi_o)$  .

Choose now some  $S \in \hat{C}_{\wedge,K}$ , formally smooth over  $\wedge$ , and an epimorphism $t : S \longrightarrow R_o$  such that

\begin{equation*}
\Omega_{R_o/\wedge} \otimes K' \overset{\sim}{\longrightarrow} \Omega_{S/\wedge} \otimes K' \quad .
\end{equation*}
If  $M$  is the maximal ideal of  $S$ , we inductively define, for  $n \geq 1$ , $R_n = S/I_n$  and  $\xi_n \in \operatorname{Ob}(\underline{A}(R_n))$  by the properties that

(a)  $I_{n+1}$  is the intersection of the ideals  $I : I_n M \subset I \subset I_n$ , such that  $\xi_n$ extends to an object  $\xi$  in  $\underline{A}(S/I)$  .

(b)  $\xi_{n+1}$  is an extension of  $\xi_n$  .

If  $R = \varprojlim R_n$  and  $\xi = \varprojlim \xi_n$ , then one checks that  $(R,\ \xi)$  is a minimally-versal formal object, and the only one up to isomorphism.


2. \underline{Prorepresentable cofibered groupoids.}

Let  $\underline{A}$  be a cofibered groupoid over  $\underline{C}_\wedge$ , admitting a minimally-versal formal object  $\xi$ . In general we can not recover  $\underline{A}$  (up to  $\underline{C}_\wedge$-equivalence) out of  $\xi$  alone. One has to know when two maps  $R \overset{f}{\underset{g}{\rightrightarrows}} S$  yield a  $\underline{C}_\wedge$-isomorphism $\xi(f) \longrightarrow \xi(g)$ , where  $R = P(\xi)$ . As an application of 1.11  and 1.12 we now consider the question of  "recovering  $\underline{A}$ "  up to  $\underline{C}_\wedge$-equivalence. Indeed, we

shall have a quite satisfactory answer applicable to a wide class of cofibered groupoids.

A number of cofibered groupoids which usually occur in practice enjoy a slightly stronger property than those of semi-homogeneous ones, as it will be defined explicitly in 2.5. To investigate them it is convenient to rephrase what we have done so far in terms of  "smooth functors" . All the notations and terminologies in the previous section remain in force throughout in this section.

\underline{Definition} 2.1.  \underline{Let}  $\varphi$ : $\underline{A} \longrightarrow \underline{B}$  \underline{be a functor of cofibered groupoids over}  $\underline{C}_\wedge$ . \underline{We say that}  $\varphi$  \underline{is smooth if every surjective map}  $\beta : b' \longrightarrow \varphi(a)$  \underline{in}  $\underline{B}$  \underline{can be completed to a commutative diagram}

\begin{equation}\tag{*}
\begin{tikzcd}[row sep=large, column sep=huge]
\varphi(a') \arrow[r] \arrow[dr, "\varphi(\alpha)"'] & b' \arrow[d, "\beta"] \\
 & \varphi(a)
\end{tikzcd}
\end{equation}










\underline{for some}  $\alpha : a' \longrightarrow a$  \underline{in}  $\underline{A}$ . \underline{We say that}  $\varphi$  \underline{is minimally smooth if it is smooth and}  $\varphi(k[\epsilon]) : [\underline{A}(k[\epsilon])] \longrightarrow [\underline{B}(k[\epsilon])]$  \underline{is bijective}.

\underline{Remark} 2.2(a)  Let  $\varphi$ : $\underline{A} \longrightarrow \underline{B}$  be a functor of cofibered groupoids over  $\underline{C}_\wedge$ . We note that  " $\varphi$  is smooth" $\Leftrightarrow$ "every surjective map  $\beta : b' \longrightarrow \varphi(a)$  in  $\underline{B}$ can be completed into a commutative diagram (*) such that  $\varphi(a') \longrightarrow b'$  is a $\underline{C}_\wedge$-isomorphism"  $\Leftrightarrow$  "every small prolongation  $\beta : b' \longrightarrow \varphi(a)$  in  $\underline{B}$  can be completed into a commutative diagram (*) ".

\underline{Remark} 2.2(b)  For any cofibered groupoid  $\underline{A}$  over  $\underline{C}_\wedge$ , the natural functor $\underline{A} \longrightarrow [\underline{A}]$  is minimally smooth.

\underline{Remark} 2.2(c)  For each object  $R$  in  $\hat{\underline{C}}_\wedge$ , we set  $h_R : \underline{C}_\wedge \longrightarrow$ (Ens)  to be the functor defined by  $h_R(S) = \operatorname{Hom}_{\wedge\text{-alg}}(R,\ S)$  for all  $S$  in  $\underline{C}_\wedge$ . It associates a cofibered discrete groupoid  $\underline{h}_R$  over  $\underline{C}_\wedge$ , and a map  $R \longrightarrow S$  in  $\underline{C}_\wedge$

induces a functor  $\underline{h}_S \longrightarrow \underline{h}_R$  of cofibered groupoids. The functor  $\underline{h}_S \longrightarrow \underline{h}_R$  induced by a map  $R \longrightarrow S$  in  $\underline{C}_\wedge$  is smooth if and only if  $S$  is a formal power-series ring over  $R$ .

\underline{Remark} 2.2(d)  Given an object  $R$  in  $\widehat{\underline{C}}_\wedge$ , let us denote by  $(R,\ \underline{C}_\wedge)$  the category of arrows in  $\widehat{\underline{C}}_\wedge$  with the source  $R$  and a target in  $\underline{C}_\wedge$ . Let  $\underline{A}$  be a cofibered groupoid over  $\underline{C}_\wedge$ . Given  $\xi \in \mathrm{ob}\ \widehat{\underline{A}}$  with  $P(\xi) = R$ , let  $\underline{A}' \longrightarrow (R,\ \underline{C}_\wedge)$  be the pull-back of  $\underline{A} \longrightarrow \underline{C}_\wedge$  under the canonical functor  $(R,\ \underline{C}_\wedge) \longrightarrow \underline{C}_\wedge$  and choose a section  $\xi^{\#}$  such that  $\xi^{\#}(1_R) = \xi$ . (This simply means that we choose, for each map  $R \xrightarrow{\ f\ } S$ , a $f$-map  $\xi \longrightarrow \xi(f)$ ). We then obtain a functor  $\xi^{\#} : \underline{h}_R \longrightarrow \underline{A}$  over  $\underline{C}_\wedge$  by setting  $(R \xrightarrow{\ f\ } S) \longmapsto \xi(f)$ . Of course this functor does not depend on the choice of  $\xi^{\#}$  up to natural equivalence of functors. Now  " $\xi^{\#} : \underline{h}_R \longrightarrow \underline{A}$  is (minimally) smooth"  means that every surjective map  $a' \xrightarrow{\ \alpha\ } \xi(f)$  in  $\underline{A}$  can be completed into a commutative diagram

\begin{center}
\begin{tikzcd}[row sep=large, column sep=huge]
\xi(f') \arrow[r] \arrow[dr, "\xi(\ \ )"'] & a' \arrow[d, "\alpha"] \\
 & \xi(f)
\end{tikzcd}
\end{center}











(and  $\underline{h}_R(k[\epsilon]) \longrightarrow \underline{A}(k[\epsilon])$   is bijective), which means precisely that  $\xi$  is a (minimally) versal formal object of  $\underline{A}$  over  $\underline{C}_\wedge$ . Thus we conclude that the existence of a (minimally) versal formal object of  $\underline{A}$  is equivalent to the existence of a (minimally) smooth functor  $\underline{h}_R \longrightarrow \underline{A}$  over  $\underline{C}_\wedge$  for some  $R \in \mathrm{ob}(\widehat{\underline{C}}_\wedge)$ .

The following general properties on smoothness are trivial to verify.

\underline{Proposition} 2.3.  \underline{Let}  $\underline{A} \xrightarrow{\ \varphi\ } \underline{B} \xrightarrow{\ \psi\ } \underline{C}$  \underline{be functors of cofibered groupoids over}  $\underline{C}_\wedge$ .

(a)  \underline{If}  $\varphi, \psi$  \underline{are both smooth, then so is}  $\psi.\varphi$ .

(b)  \underline{If}  $\psi.\varphi$  \underline{is smooth and}  $\varphi$  \underline{is surjective on isomorphism classes of objects,}

\underline{then}  $\psi$  \underline{is smooth.}

\underline{Remark} 2.4.  Let  $\underline{A}$  be a cofibered groupoid over  $\underline{C}_\wedge$ , admitting a versal formal object  $\xi$ . This means, by 2.2(d), that  $\tilde{\xi} : \underline{h}_R \to \underline{A}$  is smooth, where  $R = P(\xi)$ . Therefore we have,  " $\underline{A}$  is (formally) smooth over  $\underline{C}_\wedge$  (c.f. 1.14) i.e.,  $R$  is a formal power-series algebra over  $\wedge$ "  $\Leftrightarrow$  "the composite functor  $\underline{h}_R \xrightarrow{\ \tilde{\xi}\ } \underline{A} \xrightarrow{\ P\ } \underline{C}_\wedge$   $(= \underline{h}_\wedge)$   is smooth"  $\Leftrightarrow$  " $\underline{A} \xrightarrow{\ P\ } \underline{C}_\wedge$  is a smooth functor"  by 2.3(b).

We now consider a stronger property than being semi-homogeneous.

\underline{Definition} 2.5.  \underline{Let}  $\underline{A}$  \underline{be a cofibered groupoid over}  $\underline{C}_\wedge$ . \underline{It is called homogeneous if every diagram}

\begin{center}
\begin{tikzcd}[row sep=large, column sep=huge]
 & a' \arrow[d] \\
b' \arrow[r] & a
\end{tikzcd}
\end{center}

\underline{where}  $a' \to a$  \underline{is surjective admits a fibre-product}  $a' \underset{a}{\times} b'$  \underline{in}  $\underline{A}$  \underline{such that}

\begin{equation*}
P(a' \times b') = P(a') \underset{P(a)}{\times} P(b') \ .
\end{equation*}
\underline{Remark} 2.6(a)  Let  $\underline{A}$  be a cofibered groupoid over  $\underline{C}_\wedge$ , and consider a diagram

(*) \qquad
\begin{tikzcd}[row sep=small, column sep=small]
 & a' \arrow[dl] \arrow[dr] & \\
a_1 \arrow[dr] & & a_2 \arrow[dl] \\
 & a &
\end{tikzcd}
\qquad \text{in } $\underline{A}$ \text{ above the diagram} \qquad
\begin{tikzcd}[row sep=small, column sep=small]
 & R_1 \underset{R}{\times} R_2 \arrow[dl, "\pi_1"'] \arrow[dr, "\pi_2"] & \\
R_1 \arrow[dr] & & R_2 \arrow[dl] \\
 & R &
\end{tikzcd}
















in  $\underline{C}_\wedge$  where  $\pi_i$  are the projections. If a fibre-product  $a_1 \underset{a}{\times} a_2$  exists in  $\underline{A}$ , we obtain a unique map  $\varphi : a' \to a_1 \underset{a}{\times} a_2$  compatible with the projections. If  $P(a_1 \underset{a}{\times} a_2) = R_1 \underset{R}{\times} R_2$ , then  $P(\varphi)$  is the identity map on  $R_1 \underset{R}{\times} R_2$  and therefore  $\varphi$  is a  $\underline{C}_\wedge$-isomorphism i.e.,  $a' = a_1 \underset{a}{\times} a_2$ . In other words, if  $\underline{A}$  is a homogeneous cofibered groupoid over  $\underline{C}_\wedge$ , every  diagram (*) defines a fibre-product  $a_1 \underset{a}{\times} a_2$  provided  $R_1 \to R$  is surjective in  $\underline{C}_\wedge$ . This fact entails immediately

that a homogeneous cofibered groupoid is, a fortiori, semi-homogeneous.


\underline{Remark} 2.6(b)   Consider a diagram

\begin{center}
\begin{tikzcd}[row sep=large, column sep=large]
X \arrow[dr, "\varphi"'] & & Y \arrow[dl, "\psi"] \\
 & Z &
\end{tikzcd}
\end{center}

of categories and functors. The ordinary fibre-product  $X \times_Z Y$  is a category in which an object is a pair  $(x,y)$  such that  $\varphi(x) = \psi(y)$ , and a map $(x,y) \to (x', y')$  consists of a pair  $\alpha : x \to x'$ , $\beta : y \to y'$  such that $\varphi(\alpha) = \psi(\beta)$ . The fibre-product  $X \times^2_Z Y$  in the sense of  2-categories is a category in which an object is a triple  $(x,y; \gamma)$ , where  $\varphi(x) \xrightarrow{\gamma} \psi(y)$  is an isomorphism, and a map  $(x,y; \gamma) \to (x',y'; \gamma')$  consists of a pair  $x \xrightarrow{\alpha} x'$   $y \xrightarrow{\beta} y'$  with a commutative diagram

\begin{center}
\begin{tikzcd}[row sep=huge, column sep=huge]
\varphi(x) \arrow[r, "\varphi(\alpha)"] \arrow[d, "\gamma"'] & \varphi(x') \arrow[d, "\gamma'"] \\
\psi(y) \arrow[r, "\psi(\beta)"'] & \psi(y')
\end{tikzcd}
\end{center}









One can rephrase the notions of (semi)homogeneous cofibered groupoid or smooth functor in terms of fibre-product of categories (in the sense of 2-category). Now let  $P : \underline{A} \to \underline{C}_\wedge$  be a cofibered category, and consider an object $R_1 \times_R R_2$  in  $\underline{C}_\wedge$ . If we choose a direct image functor  $(\pi_i)_*: \underline{A}(R_1 \times_R R_2) \to \underline{A}(R_i)$ , where  $\pi_i : R_1 \times_R R_2 \to R_i$  is the projection for  $i = 1,2$,  we obtain a functor $\underline{A}(R_1 \times_R R_2) \to \underline{A}(R_1) \times^2_{\underline{A}(R)} \underline{A}(R_2)$ . It is clear from the definition of cofibered category that this functor, up to canonical natural equivalence, does not depend on the choice of direct image functors. It is now clear from the definition that a cofibered groupoid  $\underline{A}$  over  $\underline{C}_\wedge$  is homogeneous over  $\underline{C}_\wedge$  if and only if $\underline{A}(R_1 \times_R R_2) \to \underline{A}(R_1) \times^2_{\underline{A}(R)} \underline{A}(R_2)$  is an equivalence of categories whenever  $R_1 \to R$  is surjective in  $\underline{C}_\wedge$ , and  $\underline{A}$  is semi-homogeneous if and only if

\begin{equation*}
[\underline{A}(R_1 \times_R R_2)] \longrightarrow [\underline{A}(R_1) \times^2_{\underline{A}(R)} \underline{A}(R_2)] 
\end{equation*}



 is surjective whenever  $R_1 \longrightarrow R$  is surjective in  $\underline{C}_\wedge$ , and is bijective whenever  $R = k$  and  $R_1 = k[\epsilon]$ . Now let  $\varphi : \underline{A} \to \underline{B}$  be a functor of cofibered groupoids over  $\underline{C}_\wedge$ . For each map  $R' \to R$  in  $\underline{C}$  , $\varphi$  induces a functor $\underline{A}(R') \to \underline{A}(R) \times^2_{\underline{B}(R)} \underline{B}(R')$  uniquely determined up to a (canonical) natural equivalence. It is again trivial to see that  $\varphi$  is smooth if and only if the functor $A(R') \to \underline{A}(R) \times^2_{\underline{B}(R)} \underline{B}(R')$  is surjective on isomorphism classes of objects, whenever $R' \to R$  is surjective.


\underline{Remark} 2.6(c). If  $\underline{A}$  is a homogeneous cofibered groupoid over  $\underline{C}_\wedge$ , the functor $A(k[V \times W]) \to \underline{A}(k[V])\times \underline{A}(k[W])$         is an equivalence of categories for any finite-dimensional vector spaces  $V, W$  over  $k$  (We recall our convention $\underline{A}(k) = \{e\}$  ). In particular, we have

\begin{equation*}
\mathrm{Aut}_{\underline{A}(k[V\times W])}(1_{V\times W}) \xrightarrow{\ \sim\ } \mathrm{Aut}_{\underline{A}(k[V])}(1_V)\times\mathrm{Aut}_{\underline{A}(k[W])}(1_W)
\end{equation*}
where  $1_V$  is the direct image of  $e$  under the unique map  $k \to k[V]$  in  $\underline{C}_\wedge$  . It follows that if  $\underline{A}$  is homogeneous over  $\underline{C}_\wedge$ , $\mathrm{Aut}(1_\epsilon)$  as well as  $[\underline{A}(k[\epsilon])]$ are canonically provided with vector space structures over  $k$  .


\underline{Remark} 2.6(d). For any object  $R$  in  $\hat{\underline{C}}_\wedge$ , the cofibered (discrete) groupoid $\underline{h}_R$  over  $\underline{C}_\wedge$  is homogeneous.

If  $\underline{A}$  is semi-homogeneous, then so is  $[\underline{A}]$ . However, the homogeneity of  $\underline{A}$  does not imply in general the homogeneity of  $[\underline{A}]$ . Indeed we have


\underline{Proposition} 2.7.  \underline{Let}  $\underline{A}$  \underline{be a homogeneous cofibered groupoid over}  $\underline{C}_\wedge$ . \underline{The following statements are equivalent.}

(i)  $[\underline{A}]$  \underline{is homogeneous i.e.}  $[\underline{A}(R' \times_R S)] \longrightarrow [\underline{A}(R')] \times_{[\underline{A}(R)]} [\underline{A}(S)]$  \underline{is bijective} \underline{for every small extension}  $R' \to R$  .

(ii) \underline{For every small prolongation}  $a' \to a$  \underline{in}  $\underline{A}$ , \underline{the map}

\begin{equation*}
\mathrm{Aut}_{\underline{A}(R')}(a') \longrightarrow \mathrm{Aut}_{\underline{A}(R)}(a) 
\end{equation*}



 \underline{is surjective, where}  $R' = P(a')$  ,  $R = P(a)$  .

\underline{Proof}.  (i) $\Rightarrow$ (ii)  Let  $R' \xrightarrow{\ f\ } R$  be a small extension in  $\underline{C}_{\wedge}$  and let  $a' \to a$  be a f-map in  $\underline{A}$ . Given  $\tau \in \mathrm{Aut}_{\underline{A}(R)}(a)$  , we consider  $a' \times_{a} a'$  and  $a' \times_{a} a'_{\tau}$  where  $a'_{\tau} \longrightarrow a$  denotes the composite map  $a' \longrightarrow a \xrightarrow{\ \tau\ } a$  . Since  $[A(R' \times_{R} R')] \longrightarrow [\underline{A}(R')] \times_{[\underline{A}(R)]} [\underline{A}(R')]$  is bijective, we conclude the existence of an isomorphism  $a' \times_{a} a' \xrightarrow{\ u\ } a' \times_{a} a'_{\tau}$  , and  $u$  induces, via the projection on the second factor, an isomorphism  $a' \xrightarrow{\ \tau'\ } a'$  which is a lifting of  $\tau$  .

(ii) $\Rightarrow$ (i)  Let  $a''_{i}$  ($i=1,2$)  be objects in  $\underline{A}(R' \times_{R} S)$  which have the same image under  $[\underline{A}(R' \times_{R} S)] \to [\underline{A}(R')] \times_{[\underline{A}(R)]} [\underline{A}(S)]$  . We then obtain a diagram of solid arrows

\begin{center}
\begin{tikzcd}[column sep=small, row sep=small]
&& a''_{2} \arrow[ddll] \arrow[ddrr] && \\
&& a''_{1} \arrow[u, dashed] \arrow[dl] \arrow[dr] && \\
a'_{2} \arrow[ddrr] & a'_{1} \arrow[l, "\sim"] \arrow[dr] && b_{1} \arrow[r, "\tau"] \arrow[dl] & b_{2} \arrow[ddll] \\
&& a_{1} \arrow[d, "\bar{\tau}"] && \\
&& a_{2} &&
\end{tikzcd}
\qquad \text{above} \qquad
\begin{tikzcd}[column sep=small, row sep=small]
& R' \times_{R} S \arrow[dl] \arrow[dr] & \\
R' \arrow[dr] && S \arrow[dl] \\
& R &
\end{tikzcd}
\end{center}



































where  $\bar{\tau}$ ; $a_{1} \to a_{2}$  is the induced isomorphism from  $\tau$  so that the square box on the lower right corner is commutative. If the condition (ii) is verified, one can always replace the given isomorphism  $a'_{1} \overset{\sim}{\to} a'_{2}$  so that the square box on the left corner is also commutative. Since  $a''_{i} = a'_{i} \times_{a_{i}} b_{i}$  for  $i = 1, 2$  by  2.6(a), we obtain the isomorphism  $a''_{1} \overset{\sim}{\to} a''_{2}$  . This proves that  $[\underline{A}(R' \times_{R} S)] \longrightarrow [\underline{A}(R')] \times_{[\underline{A}(R)]} [\underline{A}(S)]$  is injective, and hence is bijective since  $\underline{A}$  is homogeneous by hypothesis.

Now let  $\underline{A}$  be a homogeneous cofibered groupoid over  $\underline{C}_{\Lambda}$  , and let  $R' \xrightarrow{\ f\ } R$  be a small extension in  $\underline{C}_{\Lambda}$  . We have a canonical map

$\tilde{f} : R' \times_{R} R' \longrightarrow k[\mathrm{Ker}\ f]$  given by  $(r'_{1}\ ,\ r'_{2}) \longrightarrow r'_{1}(0) + (r'_{1} - r'_{2})$  , and  $1 \times \tilde{f} : R' \times_{R} R' \longrightarrow R' \times_{k} k[\mathrm{Ker}\ f]$  is an isomorphism. Given any two f-maps  $a_{i} \to a$  ($i=1,2$) in  $\underline{A}$  ,  $a_{1} \times_{a} a_{2}$  is an object over  $R' \times_{R} R'$  and in turn we may consider  $\tau(a_{1},\ a_{2}) = (\tilde{f})_{*}(a_{1} \times_{a} a_{2})$  which is an object in  $\underline{A}(k[\mathrm{Ker}\ f])$  . Since  $1 \times \tilde{f} : R' \times_{R} R' \longrightarrow R' \times_{k} k[\mathrm{Ker}\ f]$  is an isomorphism, we have the isomorphism  $a_{1} \times_{a} a_{2} \simeq a_{1} \times \tau(a_{1},\ a_{2})$  compatible with the projections on the first factor. The statement 1.5(2) takes a more definite form for a homogeneous groupoid.

\underline{Lemma} 2.8.  \underline{Let}  $\underline{A}$  \underline{be a homogeneous cofibered groupoid over}  $\underline{C}_{\Lambda}$  , \underline{and}  $a_{i} \xrightarrow{\ \alpha_{i}\ } a$  ($i = 1, 2$)  f-\underline{maps in}  $\underline{A}$  . \underline{Then}

(1)  \underline{There exists}  $\rho$  : $a_{1} \to a_{2}$  \underline{in}  $\underline{A}$  \underline{with}  $\alpha_{2} \cdot \rho = \alpha_{1}$  \underline{if and only if} \underline{there exists an arrow}  $a_{1} \to \tau(a_{1},\ a_{2})$  \underline{in}  $\underline{A}$  .

(2)  \underline{There exists}  $\rho : a_{1} \to a_{2}$  \underline{with}  $\alpha_{2} \cdot \rho = \alpha_{1}$  \underline{such that}  $P(\rho) = \mathrm{id}_{R'}$ \underline{if and only if}  $\tau(a_{1},\ a_{2}) = 0$  \underline{in}  $[\underline{A}(k[\mathrm{Ker}\ f])]$  .

\underline{Proof}:  We prove both at the same time. There exists  $\rho : a_{1} \to a_{2}$  in  $\underline{A}$  with  $\alpha_{2} \cdot \rho = \alpha_{1}$  (such that  $P(\rho) = \mathrm{id}_{R'}$ )  $\Leftrightarrow$  there exists  $h : a_{1} \to a_{1} \times_{a} a_{2}$  in  $\underline{A}$  with  $\mathrm{pr}_{1} \circ h = \mathrm{id}_{a_{1}}$  (such that  $P(h)$ = diagonal map)  $\Leftrightarrow$ there exists  $g : a_{1} \to a_{1} \times \tau(a_{1},\ a_{2})$  in  $\underline{A}$  with  $\mathrm{pr}_{1} \circ g = \mathrm{id}_{a_{1}}$  (such that  $P(g) : R' \to R' \times_{k} k[\mathrm{Ker}\ f]$  is given by  $r' \to (r',\ r'(0)))$  $\Leftrightarrow$ there exists an arrow  $\gamma : a_{1} \to \tau(a_{1},\ a_{2})$  in  $\underline{A}$  (such that  $P(\gamma) : R' \to k[\mathrm{Ker}\ f]$  is given by  $r' \to r'(0))$  . However, there exists an arrow  $\gamma : a_{1} \to \tau(a_{1},\ a_{2})$  in  $\underline{A}$  such that  $P(\gamma) : R' \to k[\mathrm{Ker}\ f]$  is factored through  $R' \to k \to k[\mathrm{Ker}\ f]$  if and only if  $\tau(a_{1},\ a_{2}) = 0$  .

\underline{Proposition} 2.9.  (a)  \underline{Let}  $\underline{A} \xrightarrow{\ \varphi\ } \underline{B} \xrightarrow{\ \psi\ } \underline{C}$  \underline{be functors of cofibered groupoids} \underline{over}  $\underline{C}_{\Lambda}$  . \underline{Assume that}

(i)  $\underline{B}$  \underline{is semi-homogeneous and}  $\underline{C}$  \underline{is homogeneous}

(ii)  $\psi(k[\epsilon]) : [\underline{B}(k[\epsilon])] \longrightarrow [\underline{C}(k[\epsilon])]$  \underline{is injective.}

\underline{Then the composite functor}  $\psi \circ \varphi$  \underline{is smooth if and only if}  $\varphi$  \underline{and}  $\psi$  \underline{are both}

\underline{smooth.}

(b)  \underline{Let} $\varphi : \underline{A} \longrightarrow \underline{B}$ \underline{be a smooth functor of cofibered groupoids over} $\underline{C}_{\Lambda}$ . \underline{If} $\underline{A}$ \underline{is semi-homogeneous and} $\underline{B}$ \underline{is homogeneous, then} $\widehat{\varphi} : \widehat{\underline{A}} \to \widehat{\underline{B}}$ \underline{is} \underline{smooth} (i.e., \underline{for any surjective map} $b' \xrightarrow{\ \beta\ } \widehat{\varphi}(a)$ \underline{in} $\widehat{\underline{B}}$ , \underline{there exists} $\alpha : a' \to a$ \underline{in} $\widehat{\underline{A}}$ \underline{and a} $\widehat{\underline{C}}_{\Lambda}$\underline{-isomorphism} $\rho : \widehat{\varphi}(a') \xrightarrow{\ \sim\ } b'$ \underline{such that} $\beta \cdot \rho = \varphi(\alpha))$.

\underline{Proof}: (a)  Assume that the composite functor $\psi \circ \varphi$ is smooth. If $\varphi$ is smooth, then so is $\psi$ by 2.3(b), and therefore it suffices to show that $\varphi$ is smooth. Let a small prolongation $b' \xrightarrow{\ \beta\ } \varphi(a)$ in $\underline{B}$ be given. Since the composite functor $\psi \circ \varphi$ is smooth, there exists an arrow $a' \xrightarrow{\ \alpha\ } a$ in $\underline{A}$ and a $\underline{C}_{\Lambda}$-isomorphism $\rho : \psi(b') \longrightarrow \psi\ \varphi(a')$ with a commutative diagram

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=huge]
\psi(b') \ar[rr, "\rho"] \ar[dr, "\psi(\beta)"'] & & \psi\ \varphi(a') \ar[dl, "\psi\ \varphi(\alpha)"] \\
 & \psi\ \varphi(a) &
\end{tikzcd}
\end{center}

Since $\underline{B}$ is semi-homogeneous, we can choose a commutative diagram

\begin{center}
\begin{tikzcd}[column sep=small, row sep=small]
 & b'' \ar[dl] \ar[dr] & & & & R' \underset{R}{\times} R' \ar[dl] \ar[dr] & \\
b' \ar[dr, "\beta"'] & & \varphi(a') \ar[dl, "\varphi(\alpha)"] & \text{above} & R' \ar[dr] & & R' \ar[dl] \\
 & \varphi(a) & & & & R &
\end{tikzcd}
\end{center}













where  $R = P(a)$ , $R' = P(b') = P(a')$ . Since $\underline{C}$ is homogeneous, $\psi(b'') = \psi(b') \underset{\psi\ \varphi(a)}{\times} \psi\varphi(a')$ by 2.6(a), and it follows from 2.8(2) that $0 = \tau(\psi\ \varphi(a'), \psi(b')) = (\widetilde{f})_{*}\psi(b'')$ , and hence $(\widetilde{f})_{*}(b'') = 0$ by the hypothesis (ii). It follows from 1.5(2) that there exists a map $\gamma : b' \longrightarrow \varphi(a')$ such that $\beta = \varphi(\alpha)\cdot\gamma$ .

(b)  Let a surjective map $\beta : b' \to \varphi(a)$ in $\widehat{\underline{B}}$ be given. This means that we are given a sequence of commutative diagrams

\begin{tikzcd}[column sep=large]
{} \ar[r, dashed] & b_3' \ar[r, "\beta_2'"] \ar[d, "\beta_3"] & b_2' \ar[r, "\beta_1'"] \ar[d, "\beta_2"] & b_1' \ar[d, "\beta_1"] \\
{} \ar[r, dashed] & \varphi(a_3) \ar[r, "\varphi(\alpha_2)"'] & \varphi(a_2) \ar[r, "\varphi(\alpha_1)"'] & \varphi(a_1)
\end{tikzcd}















in $\underline{B}$ , where $\alpha_{v}$ , $\beta_{v}$ , $\beta_{v}'$ are surjective for all $v$ , such that $\beta = \varprojlim_{v} \beta_{v}$ . To show that $\widehat{\varphi}$ is smooth, it suffices to prove that a commutative diagram below of solid arrows in which $\alpha_{n}$ , $\beta_{n}$ , $\beta_{n+1}$ , $\beta_{n}'$ are surjective can be completed into a commutative diagram including dotted arrows.

\begin{center}
\begin{tikzcd}[column sep=large, row sep=large]
\varphi(a_{n+1}') \ar[rrrr, dashed, "\varphi(\ \ )"] \ar[dr, dashed, leftrightarrow] \ar[ddr, dashed, "\varphi(\ \ )"'] & & & & \varphi(a_n') \ar[dl, leftrightarrow] \ar[ddl, "\varphi(\alpha_n')"] \\
 & b_{n+1}' \ar[rr, "\beta_n'"] \ar[d, "\beta_{n+1}"] & & b_n' \ar[d, "\beta_n"'] & \\
 & \varphi(a_{n+1}) \ar[rr, "\varphi(\alpha_n)"'] & & \varphi(a_n) &
\end{tikzcd}
\end{center}


















Now $\underline{A}$ is, by hypotheses, semi-homogeneous and $\alpha'_{n} : a_{n}' \to a_{n}$ is surjective, and therefore there exists a commutative diagram

\begin{center}
\begin{tikzcd}[column sep=small, row sep=small]
 & a' \ar[dl, "\gamma"'] \ar[dr, "\gamma'"] & & & & R_{n+1} \underset{R_n}{\times} R_n' \ar[dl] \ar[dr] & & \\
a_{n+1} \ar[dr, "\alpha_n"'] & & a_n' \ar[dl, "\alpha_n'"] & \text{in } \underline{A} \text{ over} & R_{n+1} \ar[dr] & & R_n' \ar[dl] & \text{in } \underline{C}_{\Lambda} . \\
 & a_n & & & & R_n & &
\end{tikzcd}
\end{center}













The hypothesis that $\underline{B}$ is homogeneous entails that

\begin{tikzcd}[column sep=huge, row sep=huge]
 & \varphi(a') \ar[dl, "\varphi(\gamma)"'] \ar[dr, "\varphi(\gamma')"] & \\
\varphi(a_{n+1}) \ar[dr, "\varphi(\alpha_n)"'] & & \varphi(a_n') \ar[dl, "\varphi(\alpha_n')"] \\
 & \varphi(a_n) &
\end{tikzcd}










is a diagram of a fibre-product in $\underline{B}$ , and therefore we obtain a unique map $\delta : b'_{n+1} \to \varphi(a')$ in $\underline{B}$ with an appropriate commutativity. Since $\beta_{n+1}$ , $\beta'_n$ are both surjective, so is $\delta$ and therefore, since $\varphi$ is smooth, there exists $a'_{n+1} \xrightarrow{\ \alpha'\ } a'$ in $\underline{A}$ and a $\underline{C}_{\Lambda}$-isomorphism $\varphi(a'_{n+1}) \xrightarrow[\sim]{\rho} b'_{n+1}$ such that $\delta \cdot \rho = \varphi(\alpha')$ . We then obtain the commutative diagram

\begin{center}
\begin{tikzcd}[row sep=huge, column sep=huge]
\varphi(a'_{n+1})
  \arrow[rrr, "\varphi(\gamma'\cdot\alpha')"]
  \arrow[dr, "\rho"]
  \arrow[ddr, "\varphi(\gamma\cdot\alpha')"']
& & & \varphi(a'_n)
  \arrow[dl, "\sim"]
  \arrow[ddl, "\varphi(\alpha'_n)"] \\
& b'_{n+1} \arrow[r] \arrow[d] & b'_n \arrow[d] & \\
& \varphi(a_{n+1}) \arrow[r] & \varphi(a_n) &
\end{tikzcd}
\end{center}


















\underline{Corollary} 2.10.  (a) \underline{Let} $\varphi : \underline{A} \to \underline{B}$ \underline{be a smooth functor of cofibered groupoids over} $\underline{C}_{\Lambda}$ . \underline{Let} $\xi$ \underline{be a versal formal object of} $\underline{A}$ , \underline{and} $\eta$ \underline{a minimally-versal formal object of} $\underline{B}$ . \underline{If} $\underline{B}$ \underline{is homogeneous, then for any map} $\beta : \eta \to \varphi(\xi)$ \underline{in} $\underline{\hat{B}}$ , $P(\xi)$ \underline{is a formal power-series ring over} $P(\eta)$ \underline{through} $P(\beta) : P(\eta) \to P(\varphi(\xi)) = P(\xi)$ .

(b)  \underline{Let} $\underline{A}$ \underline{be a homogeneous cofibered groupoid over} $\underline{C}_{\Lambda}$ , \underline{and let} $\xi$ , $\eta$ \underline{be versal formal objects of} $\underline{A}$ . \underline{If} $\eta$ \underline{is minimal, then for any map} $\alpha : \eta \to \xi$ \underline{in} $\hat{A}$ , $P(\xi)$ \underline{is a formal power-series ring over} $P(\eta)$ \underline{through} $P(\alpha) : P(\eta) \to P(\xi)$ .

\underline{Proof}:  (a)  A map $\beta : \eta \to \varphi(\xi)$ induces a commutative diagram

\begin{center}
\begin{tikzcd}[row sep=huge, column sep=huge]
\underline{h}_{P(\xi)} \arrow[r, "\widetilde{\beta}"] \arrow[d, "\widetilde{\xi}"'] & \underline{h}_{P(\eta)} \arrow[d, "\widetilde{\eta}"] \\
\underline{A} \arrow[r, "\varphi"'] & \underline{B}
\end{tikzcd}
\end{center}









Since $\widetilde{\xi}$ , $\varphi$ are smooth, $\widetilde{\eta}\cdot\widetilde{\beta} = \varphi\cdot\widetilde{\xi}$ is smooth. On the other hand,

$\widetilde{\eta}(k[\epsilon]) : \underline{h}_{P(\eta)}(k[\epsilon]) \to [\underline{B}(k[\epsilon])]$ is an isomorphism and therefore $\widetilde{\beta}$ is smooth by 2.9(a), which means that $P(\xi)$ is a formal power-series ring over $P(\eta)$ .

(b)  follows from (a) by setting $\underline{A} = \underline{B}$ .

Finally we consider the question of  "representability"  of a cofibered groupoid. Let $\underline{C}$ be a fixed category. Each object $R$ in $\underline{C}$ defines a functor $h_R : \underline{C} \to$ (Ens)  given by  $h_R(S) = \mathrm{Hom}_{\underline{C}}(R,S)$ , and in turn we obtain a functor $h : \underline{C}^0 \to \underline{\mathrm{Hom}}(\underline{C},(\mathrm{Ens}))$ which is fully-faithful. A  "cocategory in $\underline{C}$ "  is a diagram

\begin{tikzcd}[column sep=huge]
h_{R_1} \times_{h_{R_0}} h_{R_1} \arrow[r] & h_{R_1} \arrow[r, shift left=3, "s_1"] \arrow[r, shift right=3, "s_2"'] & h_{R_0} \arrow[l, "\epsilon" description]
\end{tikzcd}
$\qquad\text{with } s_i \cdot \epsilon = \text{identity for } i = 1,2$










\begin{equation*}
(\text{where } \ h_{R_1} \times_{h_{R_0}} h_{R_1} \ = \ (h_{R_1})_{s_1} \times_{h_{R_0}} {}_{s_2}(h_{R_1})) \ \text{ such that}
\end{equation*}
(i)  $c$  is associative and is compatible with  $s_i$  for  $i = 1,2$

\begin{multline*}
(\mathrm{ii}) \quad h_{R_1} \xrightarrow{\ \sim\ } h_{R_0} \times_{h_{R_0}} h_{R_1} \xrightarrow{\ \epsilon \times 1\ } h_{R_1} \times_{h_{R_0}} h_{R_1} \xrightarrow{\ c\ } h_{R_1}
\\[2ex]
\phantom{(\mathrm{ii})} \quad h_{R_1} \xrightarrow{\ \sim\ } h_{R_1} \times_{h_{R_0}} h_{R_0} \xrightarrow{\ 1 \times \epsilon\ } h_{R_1} \times_{h_{R_0}} h_{R_1} \xrightarrow{\ c\ } h_{R_1}
\\[1ex]
\text{are both identities.}
\end{multline*}
If  $(R_0, R_1, s_1, s_2, \epsilon, c)$  is a cocategory in $\underline{C}$ , then for an object $S$ in $\underline{C}$ , we can define a category  $h_{(R_0,\ R_1,\ \ldots)}(S)$  by setting  $\mathrm{ob}\ h_{(R_0,\ R_1,\ldots)}(S) = \mathrm{Hom}_{\underline{C}}(R_0,\ S)$ , and  $\mathrm{Fl}\ h_{(R_0,\ R_1,\ldots)}(S) = \mathrm{Hom}_{\underline{C}}(R_1,S)$  in which the composition rule of arrows is given by  $c : h_{R_1} \times_{h_{R_0}} h_{R_1} \to h_{R_1}$ . Then $h_{(R_0,\ R_1,\ldots)} : \underline{C} \to$ (categories)  is a functor and in turn defines a cofibered category $\underline{h}_{(R_0,\ R_1,\ldots)}$ over $\underline{C}$ . For instance, any object $R$ in $\underline{C}$ defines a discrete cocategory $\underline{h}_R = \underline{h}_{(R,\ R,\ s_1,\ s_2,\ \epsilon,\ c)}$ by setting $s_1$, $s_2$, $\epsilon$, $c$ to be all equal to the identity map. A homomorphism  $(R_0,\ R_1,\ldots) \to (R_0{}',\ R_1{}',\ldots)$

of cocategories in $\underline{C}$ is a pair of maps $h_{R_0} \to h_{R'_0}$ , $h_{R_1} \to h_{R'_1}$ in $\underline{C}$ such that the induced map

\begin{equation*}
h_{(R_0,\ R_1,\ldots)}(S) \to h_{(R_0',\ R_1',\ldots)}(S)
\end{equation*}
is a functor for every object $S$ in $\underline{C}$ . For instance, each cocategory $(R_0,\ R_1,\ldots)$ is provided with a homomorphism $\epsilon : \underline{h}_{R_0} \to \underline{h}_{(R_0,\ R_1,\ldots)}$ of cocategories. A cogroupoid in $\underline{C}$ is by definition a cocategory $(R_0,\ R_1,\ldots)$ in $\underline{C}$ such that $h_{(R_0,\ R_1,\ldots)}(S)$ is a groupoid for every object $S$ in $\underline{C}$ . In other words, a cogroupoid in $\underline{C}$ is a cocategory $(R_0,\ R_1,\ldots)$ in $\underline{C}$ such that $\underline{h}_{(R_0,\ R_1,\ldots)}$ is a cofibered category in groupoids over $\underline{C}$ .

In practice, a cocategory or cogroupoid occur in a following fashion: Let $P : \underline{F} \to \underline{C}$ be a cofibered category, and let $\xi$ be a fixed object in $\underline{F}$ . Set $R_0 = P(\xi)$ and let $(R_0,\ \underline{C})$ be the category of arrows in $\underline{C}$ with the source $R_0$ . Let $P : \underline{F}' \to (R_0,\ \underline{C})$ be the pull-back of $\underline{F}$ under the canonical functor $(R_0,\ \underline{C}) \to \underline{C}$ , and choose a cocartesian section $\xi^{\#}$ of $\underline{F}'$ over $(R_0,\ \underline{C})$ such that $\xi^{\#}(\mathrm{id}_{R_0}) = \xi$ . (This simply means that we choose, for each arrow $R_0 \xrightarrow{f} S$ in $\underline{C}$ , a cocartesian $f$-map $\xi \to \xi^{\#}(f)$ ). Define the functor

\begin{equation*}
\mathrm{Hom}_{\xi^{\#}} : (R_0 \amalg R_0,\ \underline{C}) \to (\mathrm{Ens}) \qquad \text{given by}
\end{equation*}
\begin{equation*}
X = (f_1,\ f_2) \longmapsto \mathrm{Hom}_{\underline{F}(S)}(\xi^{\#}(f_1),\ \xi^{\#}(f_2)) \qquad \text{where}
\end{equation*}
$S$ $=$ the target of $f_1$ ( $=$ the target of $f_2$ ). We note that this functor does not depend on the choice of $\xi^{\#}$ up to (canonical) natural equivalence. Henceforth, by abuse of notation, we shall simply write $\xi$ for $\xi^{\#}$ . If this functor is representable by an object $X_0 = (R_0 \ \overset{s_1}{\underset{s_2}{\rightrightarrows}}\ R_1)$ in $(R_0 \amalg R_0,\ \underline{C})$ i.e. if there exists $R_0$-map $\varphi : \xi(s_1) \to \xi(s_2)$ in $\underline{F}$ such that the induced map $\widetilde{\varphi} : \mathrm{Hom}_{(R_0 \amalg R_0,\ \underline{C})}(X_0,\ X) \to \mathrm{Hom}_{\xi}(X)$ is bijective for all $X$ in $(R_0 \amalg R_0,\ \underline{C})$ , then the object $X_0$ defines a cocategory $(R_0,\ R_1,\ldots)$ in $\underline{C}$ in a natural way. Indeed, a triple of arrows

\begin{tikzcd}[column sep=huge]
R_0 \arrow[r, shift left=2.5, "u"] \arrow[r, "v"] \arrow[r, shift right=2.5, "w"'] & S
\end{tikzcd}

in $\underline{C}$ defines a composition

\begin{equation*}
\mathrm{Hom}_{\underline{F}(S)}(\xi(v),\ \xi(w)) \times \mathrm{Hom}_{\underline{F}(S)}(\xi(u),\ \xi(v)) \to \mathrm{Hom}_{\underline{F}(S)}(\xi(u),\ \xi(w))
\end{equation*}
and in turn yields the composition rule

\begin{equation*}
h_{R_1}(S) \underset{h_{R_0}(S)}{\times} h_{R_1}(S) \to h_{R_1}(S)
\end{equation*}
depending functorially on $S$ . Consequently the functor $\mathrm{Hom}_{\xi}$ defines the cocategory $(R_0,\ R_1,\ldots)$ in $\underline{C}$ and in turn defines a cofibered category $\underline{h}_{(R_0,\ R_1,\ldots)}$ in $\underline{C}$ . By definition, ob $\underline{h}_{(R_0,\ R_1,\ldots)} = \coprod_{S} \mathrm{Hom}_{\underline{C}}(R_0,\ S)$ (disjoint union for $S \in \mathrm{ob}(\underline{C})$ ), and an arrow $(R_0 \xrightarrow{f} S) \to (R_0 \xrightarrow{f'} S')$ is a pair $S \xrightarrow{h} S'$ and $R_1 \xrightarrow{u} S'$ in $\underline{C}$ such that $u \cdot s_1 = h \cdot f$ and $u \cdot s_2 = f'$ , and the structural functor $P : \underline{h}_{(R_0,\ R_1,\ldots)} \to \underline{C}$ is given by $(R_0 \xrightarrow{f} S) \longmapsto S$ . Now the pair $(\xi,\ \varphi)$ defines the functor

\begin{equation*}
(\xi,\ \varphi) : \underline{h}_{(R_0,\ R_1,\ldots)} \to \underline{F} \quad \text{over} \quad \underline{C} \quad \text{by}
\end{equation*}
\begin{equation*}
(R_0 \xrightarrow{f} S) \ \longmapsto\ \xi(f)
\end{equation*}
\begin{equation*}
[(R_0 \xrightarrow{f} S) \xrightarrow{\ (h,u)\ } (R_0 \to S')] \longmapsto \ \text{the composite map}\ \ \xi(f) \xrightarrow{\ h_{*}\ } \xi(hf) \xrightarrow{\ u(\varphi)\ } \xi(f') \ .
\end{equation*}
We note that, for each object $S$ in $\underline{C}$ , the functor $(\xi,\varphi)(S) :$   $\underline{h}_{(R_0,R_1,\ldots)}(S) \to \underline{F}(S)$ is fully-faithful by virtue of the definition of $(R_0 \rightrightarrows R_1)$ coming from the representability of the functor $\mathrm{Hom}_{\xi}$ . Consequently the functor $(\xi,\varphi) : \underline{h}_{(R_0,R_1,\ldots)} \to \underline{F}$ is a $\underline{C}$-equivalence if and only if $\xi$ is a quasi-initial object of $\underline{F}$ over $\underline{C}$ i.e., for every object $a$ in $\underline{F}$ there exists a cocartesian arrow $\xi \to a$ . Instead of this functor $\mathrm{Hom}_{\xi}$ one may also consider the functor

\begin{equation*}
\mathrm{Isom}_{\xi} : (R_0 \amalg R_0,\ \underline{C}) \to (\mathrm{Ens}) 
\end{equation*}



 given by  $X = (f_1,f_2) \longmapsto \mathrm{Isom}_{\underline{F}(S)}(\xi(f_1),\xi(f_2))$  where  $S$  is the target of  $f_1$ ( $=$ the target of  $f_2$ ). If this functor is representable by an object  $(R_0 \rightrightarrows R_1)$ in  $(R_0 \amalg R_0, \underline{C})$  , then it defines  a cogroupoid  $(R_0,R_1,\ldots)$  in  $\underline{C}$  together with the functor  $(\xi,\varphi) : \underline{h}_{(R_0,R_1,\ldots)} \to \underline{F}$ , which is, when  $\underline{F}$  is a cofibered groupoid, a  $\underline{C}$-equivalence if and only if  $\xi$  is a quasi-initial object of  $\underline{F}$  over  $\underline{C}$ .


\underline{Definition and proposition} 2.11.  \underline{A cogroupoid}  $(R_0,R_1,\ldots)$  \underline{in}  $\hat{\underline{C}}_\Lambda$  \underline{is called smooth if any one of the following equivalent conditions holds:}

 (i)  $R_1$  \underline{is a formal power-series ring over}  $R_0$  \underline{via} $s_1$  (\underline{and}  $s_2$ )

 (ii)  $\epsilon : \underline{h}_{R_0} \longrightarrow \underline{h}_{(R_0,R_1,\ldots)}$  \underline{is smooth over}  $\underline{C}_\Lambda$ .

\underline{A minimally smooth cogroupoid or a normalized smooth cogroupoid in}  $\hat{\underline{C}}_\Lambda$  \underline{is a smooth cogroupoid}  $(R_0,R_1,\ldots)$  \underline{in}  $\hat{\underline{C}}_\Lambda$  \underline{such that}  $\underline{h}_{(R_0,R_1,\ldots)}(k[\epsilon])$  \underline{is totally disconnected} i.e.,  $s_1(k[\epsilon]) = s_2(k[\epsilon])$  .

\underline{Proof}:  $\epsilon : \underline{h}_{R_0} \to \underline{h}_{(R_0,R_1,\ldots)}$  is smooth over  $\underline{C}_\Lambda \Leftrightarrow$ given any surjective map  $(S',f') \xrightarrow{\ (h,u)\ } (S,\ f)$  in  $\underline{h}_{(R_0,R_1,\ldots)}$  , there exists a lifting  $f''$  of  $f$ to  $S'$  together with an isomorphism  $(S',f'') \xrightarrow{\ (1,u')\ } (S',f') \Leftrightarrow$ given  $u \in h_{R_1}(S)$ and a lifting  $f'$  of  $s_1(u)$  to  $S'$  , there exists a lifting  $u'$  of  $u$  to  $S'$ such that  $s_1(u') = f'$  , where  $S' \to S$  is an arbitrary surjective map in $\underline{C}_\Lambda \Leftrightarrow s_1 : \underline{h}_{R_1} \to \underline{h}_{R_0}$  is smooth over  $\underline{C}_\Lambda$ .


\underline{Proposition} 2.12.  \underline{Let}  $(R_0,R_1,\ldots)$  \underline{be a cogroupoid in}  $\hat{\underline{C}}_\Lambda$ .

(a)  \underline{If}  $(R_0,R_1,\ldots)$  \underline{is smooth, then}  $\underline{h}_{(R_0,R_1,\ldots)}$  \underline{is homogeneous.}

(b)  \underline{If}  $s_1(k[\epsilon]) = s_2(k[\epsilon])$  , \underline{then the following statements are equivalent}

          (i)  $(R_0,R_1,\ldots)$  \underline{is smooth}

         (ii)  $\underline{h}_{(R_0,R_1,\ldots)}$  \underline{is homogeneous}

        (iii)  $\underline{h}_{(R_0,R_1,\ldots)}$  \underline{is semi-homogeneous}




(c)  \underline{If}  $\underline{h}_{(R_0,R_1,\ldots)}$  \underline{is semi-homogeneous, then it is equivalent to}  $\underline{h}_{(S_0,S_1,\ldots)}$  \underline{for some minimally smooth cogroupoid}  $S_*$  .

\underline{Proof}:   (a)  Consider a diagram

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=large]
(S_1,f_1) \arrow[dr, "{(h_1,u_1)}"'] & & (S_2,f_2) \arrow[dl, "{(h_2,u_2)}"] \\
& (S,f) &
\end{tikzcd}
\end{center}

in  $\underline{h}_{(R_0,R_1,\ldots)}$  where  $h_2 : S_2 \longrightarrow S$  is surjective in  $\underline{C}_\Lambda$ . Since $s_1 : \underline{h}_{R_1} \longrightarrow \underline{h}_{R_0}$  is smooth by hypothesis,  $u_1^{-1}\, u_2$  can be lifted to some $v \in h_{R_1}(S_2)$  such that  $s_1(v) = f_2$ . Since  $h_2 \cdot s_2(v) = h_1 \cdot f_1$ , $f_1 \times s_2(v) \in h_{R_0}(S_1 \underset{S}{\times} S_2)$  is defined and we obtain the commutative diagram

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=large]
& (S_1 \underset{S}{\times} S_2,\ f_1 \times s_2(v)) \arrow[dl, "\pi_1"'] \arrow[dr, "{(\pi_2,v^{-1})}"] & \\
(S_1,f_1) \arrow[dr, "{(h_1,u_1)}"'] & & (S_2,f_2) \arrow[dl, "{(h_2,u_2)}"] \\
& (S,f) &
\end{tikzcd}
\end{center}










We claim that the above diagram defines a fibre-product  $(S_1,f_1) \underset{(S,f)}{\times} (S_2,f_2)$  in $\underline{h}_{(R_0,R_1,\ldots)}$ . Indeed, for any object  $(T,\ g)$  in  $\underline{h}_{(R_0,R_1,\ldots)}$  we have

{\small \begin{multline*}
\mathrm{Hom}((T,g),(S_1\underset{S}{\times}S_2,f_1\times s_2(v)))=\{(h_1'\times h_2',w_1\times w_2)\in h_T(S_1\underset{S}{\times}S_2)\times h_{R_1}(S_1\underset{S}{\times}S_2)\,|\,s_1(w_1\times w_2)=(h_1'\times h_2')\ g\ ,\\
s_2(w_1\times w_2)=f_1\times s_2(v)\} = \{(h_1'\times h_2',w_1,w_2) \in h_T(S_1\underset{S}{\times}S_2)\ \times h_{R_1}(S_1)\times h_{R_1}(S_2)\,|\,h_1w_1 = h_2w_2,\\
s_1(w_1) = h_1'\ g,\ s_1(w_2) = h_2'\ g,\ s_2(w_1) = f_1,\ s_2(w_2) = s_2(v)\} =\\
\{(h_1'\times h_2',w_1,w_2) \in h_T(S_1\underset{S}{\times}S_2)\times h_{R_1}(S_1)\times h_{R_1}(S_2)\,|\ u_1^{-1}\ u_2\ h_2(v^{-1}w_2)=h_1\ w_1\ ,\ s_1(w_1) = h_1'\ \ g, 
\end{multline*}}



{\footnotesize \begin{multline*}s_2(w_1)=f_1, \quad s_1(v^{-1}w_2)=h_2'g, \quad s_2(v^{-1}w_2)=f_2\} \;\overset{\sim}{\longrightarrow}\; \{(h_1'\times h_2', w_1, w_2') \in h_T(S_1\times_S S_2)\times h_{R_1}(S_1)\times h_{R_1}(S_2)\;\big| \\ u_2\, h_2\, w_2' \;=\; u_1\, h_1\, w_1, \quad s_1(w_1) \;=\; h_1'g, \quad s_2(w_1)=\; f_1, \quad s_1(w_2') \;=\; h_2'g, \quad s_2(w_2') \;=\; f_2\} \;= \\ \mathrm{Hom}((T,\ g),\ (S_1,\ f_1)) \;\times_{\mathrm{Hom}((T,g),\ (S,f))}\; \mathrm{Hom}((T,\ g),\ (S_2,\ f_2))\ .\end{multline*}}
(b)  It suffices to show (iii) $\Rightarrow$ (i) . Since $\underline{h}_{(R_0,R_1,\ldots)}$ is semi-homogeneous and $\dim[\underline{h}_{(R_0,R_1,\ldots)}(k[\epsilon])] = \dim h_{R_0}(k[\epsilon]) < \infty$ , $\underline{h}_{(R_0,R_1,\ldots)}$ admits a minimally versal formal object. On the other hand, $(R_0,\ 1_{R_0})$ is a quasi-initial minimal object of $\widehat{\underline{h}}_{(R_0,R_1,\ldots)}$ since $\underline{h}_{R_0}(k[\epsilon]) \to [\underline{h}_{(R_0,R_1,\ldots)}(k[\epsilon])]$ is bijective, and therefore $(R_0,\ 1_{R_0})$ is a minimally versal formal object of $\underline{h}_{(R_0,R_1,\ldots)}$ by 1.10(ii), which means that $\epsilon : \underline{h}_{R_0} \longrightarrow \underline{h}_{(R_0,R_1,\ldots)}$ is minimally smooth.

(c)  Let $(S_0,\ \xi_0)$ be a minimally versal formal object for $\underline{h}_{(R_0,R_1,\ldots)}$ (1.11). For any object $\xi : R_0 \to T$ in $\underline{h}_{(R_0,\ R_1,\ldots)}(T)$ , the functor $\mathrm{Isom}(\xi,\xi)$ from $\underline{C}_\Lambda/T \hat{\otimes}_\Lambda T$ to (sets) which to any $R$ associates the set of isomorphisms between the two images of $\xi$ on $R : R_0 \overset{\xi}{\longrightarrow} T \rightrightarrows T \hat{\otimes}_\Lambda T \longrightarrow R$ , is represented by $R_1 \otimes_{R_0 \hat{\otimes}_\Lambda R_0} (T \otimes_\Lambda T)$ . By a passage to limit, one gets that $\mathrm{Isom}(\xi_0,\ \xi_0)$ is pro-represented by some $S_1$ , and $\underline{h}_{(R_0,R_1,\ldots)}$ is equivalent to $\underline{h}_{(S_0,S_1,\ldots)}$ . By (b), $S_*$ is minimally smooth.

\underline{Definition} 2.13.  \underline{A cofibered groupoid} $\underline{A}$ \underline{over} $\underline{C}_\Lambda$ \underline{is called (minimally) pro-representable if it is} $\underline{C}_\Lambda$\underline{-equivalent to} $\underline{h}_{(R_0,R_1,\ldots)}$ \underline{for some (normalized) cogroupoid} $(R_0,R_1,\ldots)$ \underline{in} $\widehat{\underline{C}}_\Lambda$ .

\underline{Proposition} 2.14.  \underline{If} $(R_0,\ R_1,\ldots)$ \underline{is a normalized cogroupoid in} $\widehat{\underline{C}}_\Lambda$ , \underline{then} \underline{every homomorphism} $(\alpha_0,\alpha_1) : (R_0,R_1,\ldots) \to (R_0,R_1,\ldots)$ \underline{which induces} $\underline{C}_\Lambda$\underline{-equivalence} $\underline{h}_{(\alpha_0,\alpha_1)} : \underline{h}_{(R_0,R_1,\ldots)} \longrightarrow \underline{h}_{(R_0,\ R_1,\ldots)}$ \underline{is an isomorphism. In}

\underline{particular, for any cofibered groupoid} $\underline{A}$ \underline{over} $\underline{C}_\Lambda$ , \underline{a normalized prorepresentation, if it exists, is unique up to an isomorphism.}

\underline{Proof}:  Consider the commutative diagram

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=huge]
\underline{h}_{(R_0,R_1,\ldots)} \arrow[r, "{\underline{h}_{(\alpha_0,\alpha_1)}}"] & \underline{h}_{(R_0,R_1,\ldots)} \\
\underline{h}_{R_0} \arrow[u, "\epsilon"] \arrow[r, "\underline{h}_{\alpha_0}"'] & \underline{h}_{R_0} \arrow[u, "\epsilon"']
\end{tikzcd}
\end{center}













where $\underline{h}_{(\alpha_0,\alpha_1)}$ is a $\underline{C}_\Lambda$-equivalence. Since $\underline{h}_{(R_0,R_1,\ldots)}(k[\epsilon])$ is totally disconnected, $[\underline{h}_{(\alpha_0,\alpha_1)}(k[\epsilon])]$ and $[\epsilon(k[\epsilon])]$ are both bijections, and hence so is $\underline{h}_{\alpha_0}(k[\epsilon])$ .

Consequently, $\alpha_0 : R_0 \to R_0$ is a surjective endomorphism and hence is an automorphism. It then follows that $\alpha_1$ is also an automorphism of $R_1$ .

\underline{Lemma} 2.15.  \underline{Let} $A,\ B$ \underline{be discrete groupoids over} $\underline{C}_\wedge$ \underline{and} $\varphi : A \to B$ \underline{a minimally smooth functor}. \underline{If} $A,\ B$ \underline{are homogeneous}, \underline{then} $\varphi$ \underline{is a} $\underline{C}_\wedge$\underline{-equivalence.}

\underline{Proof}:  We must show that $\varphi(S) : A(S) \longrightarrow B(S)$ is bijective for all $S \in \mathrm{ob}(\underline{C}_\wedge)$ . We note that $\varphi(S)$ is surjective for all $S \in \mathrm{ob}(\underline{C}_\wedge)$ and bijective for $S = k[\epsilon]$ . We argue by induction on the length of $S$ . Let $S' \overset{f}{\longrightarrow} S$ be a small extension in $\underline{C}_\wedge$ . Since $A,\ B$ are homogeneous discrete groupoids, the canonical isomorphism $1 \times \tilde{f} : S' \times_S S' \longrightarrow S' \times_k k[\mathrm{Ker}\ f]$ induces the commutative diagram

\begin{tikzcd}[column sep=huge, row sep=huge]
A(S') \underset{A(S)}{\times} A(S') \arrow[r, "\sim"] \arrow[d] & A(S') \times A(k[\mathrm{Ker}\ f]) \arrow[d] \\
B(S') \underset{B(S)}{\times} B(S') \arrow[r, "\sim"] & B(S') \times B(k[\mathrm{Ker}\ f])
\end{tikzcd}













Therefore  $A(S')$ , $B(S')$  are principal homogeneous sets over  $A(S)$ , $B(S)$  with the structural group  $A(k[\mathrm{Ker}\ f]) \xrightarrow{\ \sim\ } B(k[\mathrm{Ker}\ f])$  . Consequently if  $\varphi(S)$  is bijective, then  $\varphi(S')$  is injective and hence is bijective.

\underline{Corollary} 2.16.  \underline{Let}  $\underline{A}$  \underline{be a homogeneous groupoid over}  $\underline{C}_{\wedge}$  \underline{such that} $\mathrm{Aut}_{\underline{A}(k[\epsilon])}(1_{\epsilon})$  \underline{is finite-dimensional. Then for any}  $\xi \in \mathrm{ob}(\hat{\underline{A}})$  , \underline{the functor} $\mathrm{Isom}_{\xi} : \underline{C}_{R \hat{\otimes}_{\wedge} R} \longrightarrow (\mathrm{Ens})$  \underline{is prorepresentable, where}  $R = P(\xi)$  .

\underline{Proof}:  Assume that  $\mathrm{Isom}_{\xi}$  is homogeneous. We then have, by 1.11, a minimally smooth functor  $\Phi : \underline{h}_{R_{1}} \to \underline{\mathrm{Isom}}_{\xi}$  , which is a  $\underline{C}_{R \hat{\otimes}_{\wedge} R}$-equivalence by 2.15 i.e., $\mathrm{Isom}_{\xi}$  is prorepresentable. Therefore it suffices to show that  $\mathrm{Isom}_{\xi}$  is homogeneous. Consider a diagram

\begin{center}
\begin{tikzcd}[column sep=large, row sep=large]
T_1 \arrow[dr] & & T_2 \arrow[dl] \\
 & T &
\end{tikzcd}
\end{center}

in  $\underline{C}_{R \hat{\otimes}_{\wedge} R}$  where  $T_{2} \longrightarrow T$  is surjective. Since  $\underline{A}$  is homogeneous, $\xi_{i}(T_{1}) \underset{\xi_{i}(T)}{\times} \xi_{i}(T_{2})$  exists in  $\underline{A}$  , and we have a canonical isomorphism

$\xi_{i}(T_{1} \underset{T}{\times} T_{2}) \simeq \xi_{i}(T_{1}) \underset{\xi_{i}(T)}{\times} \xi_{i}(T_{2})$  for  $i = 1,2$  (cf. 2.6(a)). It follows that

$\mathrm{Isom}_{\xi}(T_{1} \underset{T}{\times} T_{2}) \longrightarrow \mathrm{Isom}_{\xi}(T_{1}) \underset{\mathrm{Isom}_{\xi}(T)}{\times} \mathrm{Isom}_{\xi}(T_{2})$  is an isomorphism.

\underline{Theorem} 2.17.  \underline{Let}  $\underline{A}$  \underline{be a cofibered groupoid over}  $\underline{C}_{\wedge}$  . \underline{Then it is prorepresentable by a (normalized) smooth cogroupoid if and only if}

(1)  $\underline{A}$  \underline{is homogeneous}

(2)  $[A(k[\epsilon])]$  \underline{and}  $[\mathrm{Aut}(1_{\epsilon})]$  \underline{are both finite-dimensional vector spaces over}  $k$  .

\underline{Proof}:  Assume that  $\underline{A}$  is prorepresentable by a smooth cogroupoid i.e.,  $\underline{A}$  is  $\underline{C}_{\wedge}$-equivalent to  $\underline{h} = \underline{h}_{(R_{0},R_{1},\ldots)}$  for some smooth cogroupoid  $(R_{0},R_{1},\ldots)$  in  $\hat{\underline{C}}_{\wedge}$  . Since  $\underline{h}$  is homogeneous by 2.12(a), and

\begin{equation*}
\begin{aligned}
[\underline{h}(k[\epsilon])] &= \mathrm{Coker}\ (\mathrm{Hom}_{\wedge\text{-alg}}(R_{1},k[\epsilon]) \ \underset{s_{2}}{\overset{s_{1}}{\rightrightarrows}}\ \mathrm{Hom}_{\wedge\text{-alg}}(R_{0},k[\epsilon])) \qquad \text{as well as} \\[2ex]
\mathrm{Aut}_{\underline{h}}(1_{\epsilon}) &= \mathrm{Ker}(\mathrm{Hom}_{\wedge\text{-alg}}(R_{1},k[\epsilon]) \xrightarrow{\ s_{1}\ } \mathrm{Hom}_{\wedge\text{-alg}}(R_{0},k[\epsilon])) \\[2ex]
&= \mathrm{Ker}(\mathrm{Hom}_{\wedge\text{-alg}}(R_{1},k[\epsilon]) \xrightarrow{\ s_{2}\ } \mathrm{Hom}_{\wedge\text{-alg}}(R_{0},k[\epsilon])) \qquad \text{are both finite-dimensional}
\end{aligned}
\end{equation*}
vector spaces over  $k$  , we must have the same properties on  $\underline{A}$  . Conversely assume (1) and (2) on  $\underline{A}$  . We claim that  $\underline{A}$  is prorepresentable by a normalized smooth cogroupoid. Since  $\underline{A}$  is homogeneous and  $[\underline{A}(k[\epsilon])]$  is a finite-dimensional vector space over  $k$  ,  $\underline{A}$  admits a minimally versal formal object  $\xi$  . Set  $P(\xi) = R_{0}$  and consider the functor  $\mathrm{Isom}_{\xi} : \underline{C}_{R_{0} \hat{\otimes}_{\wedge} R_{0}} \to (\mathrm{Ens})$  given by

\begin{equation*}
T \longmapsto \mathrm{Isom}_{\underline{A}(T)}(\xi_{1}(T),\xi_{2}(T))
\end{equation*}
where  $\xi_{i}(T) = \xi(f_{i})$  and  $f_{i} : R_{0} \to T$  denotes the composite maps

\begin{center}
\begin{tikzcd}[column sep=large]
R_0 \arrow[r, shift left=1.2ex, "s_1"] \arrow[r, shift right=1.2ex, "s_2"'] & R_0 \otimes_{\wedge} R_0 \arrow[r] & T \ .
\end{tikzcd}
\end{center}









This functor is pro-representable by 2.16, i.e. there exists  $R_{1} \in \mathrm{ob}(\hat{\underline{C}}_{R_{0} \hat{\otimes}_{\wedge} R_{0}})$  and an isomorphism  $\xi_{1}(R_{1}) \xrightarrow{\ \varphi\ } \xi_{2}(R_{1})$  such that  $\Phi : h_{R_{1}} \to \mathrm{Isom}_{\xi}$  is an isomorphism over  $\underline{C}_{R_{0} \hat{\otimes}_{\wedge} R_{0}}$  . Then  $(R_{0},R_{1},\ldots)$  defines a cogroupoid in  $\hat{\underline{C}}_{\wedge}$  and the functor $(\xi,\varphi) : \underline{h}_{(R_{0},R_{1},\ldots)} \to \underline{A}$  is a  $\underline{C}_{\wedge}$-equivalence. Since  $\xi$  is a minimally versal formal object of  $\underline{A}$  , the composite functor  $\underline{h}_{(R_{0},R_{0},\ldots)} \xrightarrow{\ \epsilon\ } \underline{h}_{(R_{0},R_{1},\ldots)} \xrightarrow{\ (\xi,\varphi)\ } \underline{A}$ is, by definition, minimally smooth and therefore so is  $\epsilon$  since  $(\xi,\varphi)$  is a $\underline{C}_{\wedge}$-equivalence i.e.,  $(R_{0},R_{1},\ldots)$  is a normalized smooth cogroupoid in  $\hat{\underline{C}}_{\wedge}$  .




\underline{Corollary} 2.18.  \underline{A functor}  $F : \underline{C}_\Lambda \longrightarrow$ (Ens)  \underline{is pro-representable if and only if it is homogeneous and}  $\dim F(k[\epsilon]) < \infty$  .

\underline{Corollary} 2.19.  \underline{Every smooth cogroupoid in}  $\hat{\underline{C}}_\Lambda$  \underline{can be normalized up to isomorphism.}

Given a cogroupoid  $(R_0,R_1,\dots)$  in  $\hat{\underline{C}}_\Lambda$ , we set  $\bar{R}_1 = R_1/J$  where  $J$  is the ideal in  $R_1$  generated by  $\{s_1(r) - s_2(r) \mid r \in R_0\}$ . Then  $(R_0,\bar{R}_1,\dots)$  defines a formal group scheme over  $R_0$  with respect to the induced composition rule. Now let  $\underline{A}$  be a cofibered groupoid over  $\underline{C}_\Lambda$  prorepresented by a normalized smooth cogroupoid  $(R_0,R_1,\dots)$  via  $(\xi,\varphi)$ . Let  $\underline{C}_k \hookrightarrow \underline{C}_{R_0} \hookrightarrow \underline{C}_{R_0 \hat{\otimes}_\Lambda R_0}$  be the embeddings corresponding to the surjective maps  $R_0 \hat{\otimes}_\Lambda R_0 \longrightarrow R_0 \longrightarrow k$ , and let  $\mathrm{Aut}_\xi$ , $\mathrm{Aut}^o$  be the restriction functors of  $\mathrm{Isom}_\xi$  on  $\underline{C}_{R_0}$ , $\underline{C}_k$  respectively. In other words,  $\mathrm{Aut}_\xi(S)$ $=$ the automorphism group of  $\xi(S)$  for every  $S \in \mathrm{ob}(\underline{C}_{R_0})$ , and  $\mathrm{Aut}^o(S)$ $=$ the automorphism group of  $1_S$  for every  $S \in \mathrm{ob}(\underline{C}_k)$ , where  $1_S$ $=$ the direct image of  $1 \in \underline{A}(k)$  under the map  $k \to S$ . Since  $R_1$  prorepresents the functor  $\mathrm{Isom}_\xi$  on  $\underline{C}_{R_0 \hat{\otimes}_\Lambda R_0}$ , it follows that  $\bar{R}_1$  prorepresents the functor  $\mathrm{Aut}_\xi$  on  $\underline{C}_{R_0}$ , and  $k \otimes_{R_0} \bar{R}_1$  prorepresents  $\mathrm{Aut}^o$  on  $\underline{C}_k$ . Though  $\underline{A}$  is prorepresented by a smooth cogroupoid  $(R_0,R_1,\dots)$  , neither  $(R_0,\bar{R}_1,\dots)$  nor  $(k,\ k \otimes_{R_0} \bar{R}_1,\dots)$  are in general smooth. Indeed we have

\underline{Corollary} 2.20.  \underline{Let}  $\underline{A}$  \underline{be a homogeneous cofibered groupoid over}  $\underline{C}_\Lambda$  \underline{prorepresented by a normalized smooth cogroupoid}  $(R_0,R_1,\dots)$  \underline{via}  $(\xi,\varphi)$  .

(a)  $(R_0,\bar{R}_1,\dots)$  \underline{and}  $(k,\ k \otimes_{R_0} \bar{R}_1,\dots)$  \underline{prorepresent the functors}  $\mathrm{Aut}_\xi$  \underline{and}  $\mathrm{Aut}^o$  \underline{respectively.}

(b)  \underline{The following statements are equivalent}

(i)   \underline{the formal group scheme}  $\underline{h}_{(R_0,\bar{R}_1,\dots)}$  \underline{is formally smooth over}  $R_0$  ;

(ii)  \underline{for every surjective arrow}  $a' \to a$  \underline{in}  $\underline{A}$  ,
$\mathrm{Aut}_{P(a')}(a') \longrightarrow \mathrm{Aut}_{P(a)}(a)$  \underline{is surjective},

(iii)  $R_0$  \underline{prorepresents the functor}  $[\underline{A}]$  \underline{over}  $\underline{C}_\Lambda$  .




\underline{Proof}:  We have already noted (a). As for (b),  (i) $\Leftrightarrow$ (ii)  is clear whereas (ii) $\Leftrightarrow$ (iii)  follows from 2.7 and 2.15, since  $\tilde{\xi} : h_{R_0} \longrightarrow [\underline{A}]$  is minimally smooth.

\underline{Remark} 2.21.  Let  $\underline{A}$  be a cofibered groupoid over  $\underline{C}_\Lambda$  , and let  $\underline{A}|\underline{C}_k$  be the pull-back of  $p : \underline{A} \longrightarrow \underline{C}_\Lambda$  under  $\underline{C}_k \hookrightarrow \underline{C}_\Lambda$ . Then it is trivial to see that if  $\underline{A}$  is prorepresented by  $(R_0,R_1,\dots)$  via  $(\xi,\varphi)$  , then  $\underline{A}|\underline{C}_k$  is prorepresented by  $(k \otimes_\Lambda R_0\ ,\ k \otimes_\Lambda R_1,\dots)$  via  $(k \otimes_\Lambda \xi\ ,\ k \otimes_\Lambda \varphi)$  where  $k \otimes_\Lambda \xi$ $=$ the direct image of  $\xi$  under the map  $R_0 \longrightarrow k \otimes_\Lambda R_0$ ,  $k \otimes_\Lambda \varphi$ $=$ the image of  $\varphi$  under  $\mathrm{Isom}_{\underline{A}(R_1)}(\xi(s_1),\ \xi(s_2)) \longrightarrow \mathrm{Isom}_{\underline{A}(k \otimes_\Lambda R_1)}(k \otimes_\Lambda \xi(s_1),\ k \otimes_\Lambda \xi(s_2))$ . If  $(R_0,R_1,\dots)$  is normalized, then so is  $(k \otimes_\Lambda R_0,\ k \otimes_\Lambda R_1,\dots)$  , and the relative dimension of  $R_1$  over  $R_0$  is equal to the relative dimension of  $k \otimes_\Lambda R_1$  over  $k \otimes_\Lambda R_0$  since  $R_1$  is smooth over  $R_0$  .

\underline{Remark} 2.22.  Let  $\underline{A}$  be prorepresented by smooth cogroupoids  $(R_0,R_1,\dots)$  and  $(R'_0,\ R'_1,\dots)$  where we assume that  $(R_0,R_1,\dots)$  is normalized. We then obtain a homomorphism  $(i_0,i_1) : (R_0,R_1,\dots) \longrightarrow (R'_0,\ R'_1,\dots)$  . Now  $R'_0$  is a formal power-series ring over  $R_0$  by 2.10(b), and the homomorphism  $(i_0,i_1)$  induces an isomorphism  $R'_0 \otimes_{R_0} (R_0,R_1,\dots) \overset{\sim}{\longrightarrow} (R'_0,\ R'_1,\dots)$  .


3.  \underline{The coherent sheaves}  $\underline{D}^i_X$

One of the nice functors which is usually not pro-representable but nevertheless admits a formal versal object is the deformation functor. To this end we recall a few basic facts on commutative ring extensions and its obstruction theory. This section contains nothing new (possibly except in its systematic approach via Grothendieck cohomology on site). A purpose of this section is to make this expose as much self-contained. (Indeed we prove here more than we need later). The basic facts are stated in theorem 3.12. Throughout rings are meant to be commutative rings with unit.




Given a ring  $R$  we denote by  $\underline{C}_R$  the category of $R$-algebras. For each object  $A$  in  $\underline{C}_R$  we set

Cov($A$) $=$ the set of all surjective arrows  $\varphi : A' \to A$  in  $\underline{C}_R$  with target  $A$ .

It clearly defines a pretopology and in turn we obtain a site  $\underline{C}_R$ . For each object  $A$  in  $\underline{C}_R$ , we shall denote by  $\underline{C}_{A|R}$  the category of arrows in  $\underline{C}_R$  with target  $A$ . We may and shall provide the category  $\underline{C}_{A|R}$  with the topology induced from the forgetful functor  $j_A : \underline{C}_{A|R} \to \underline{C}_R$ . We note that the category  $\underline{C}_{A|R}$  has a final object  $(1_A : A \to A)$  and an initial object  $(i_A : R \to A)$ , and admits a fibre-product as well as coproduct. Henceforth we shall denote the object  $(B \to A)$  in  $\underline{C}_{A|R}$ , by abuse of notation, simply by  $B$  in case when there is no possible confusion. Given an abelian category  $\underline{C}$ , a  $\underline{C}$-valued sheaf on  $\underline{C}_{A|R}$  is, by definition, a functor  $F : \underline{C}^{O}_{A|R} \to \underline{C}$  such that, for any surjective arrow  $B' \to B$  in  $\underline{C}_{A|R}$ ,

\begin{equation*}
0 \to F(B) \to F(B') \rightrightarrows F(B' \underset{B}{\times} B')
\end{equation*}
is exact. The  \underline{additive}  presheaves are those which preserve coproduct i.e.,  $F(B_1 \underset{R}{\otimes} B_2) = F(B_1) \oplus F(B_2)$ . For example, an $A$-module  $M$  defines the functor

\begin{equation*}
\mathrm{Der}_R(-,M): \underline{C}^{O}_{A|R} \to (A\text{-mod})
\end{equation*}
given by  $B \to \mathrm{Der}_R(B,M) =$ $R$-linear derivations of  $B$  with values in  $M$  regarded as $B$-module via the structural map  $B \to A$ , and it is clearly an additive sheaf on  $\underline{C}^{O}_{A|R}$ , where ($A$-mod) denotes the category of $A$-modules. A presheaf  $F$  on  $\underline{C}_{A|R}$  with values in  ($A$-mod)  is called "finite type" if  $F(B)$  is an $A$-module of finite type whenever  $B$  is an $R$-algebra of finite type. For example, if  $A$  is noetherian and  $M$  is an $A$-module of finite type, then  $\mathrm{Der}_R(-,M)$  is an additive sheaf of finite type on the site  $\underline{C}_{A|R}$ .

A few more words on notations and basic facts in homological algebra:

3.1(a)  Throughout the rest of this section, we shall denote by  $\widetilde{\underline{C}}_{A|R}$  (or  $\overset{\vee}{\underline{C}}_{A|R}$ )  the category of sheaves (or presheaves) with values in ($A$-mod). We have the (left exact) injection functor  $i_{A|R}: \widetilde{\underline{C}}_{A|R} \to \overset{\vee}{\underline{C}}_{A|R}$ , and the associated-sheaf (exact)

functor  $G_{A|R}: \overset{\vee}{\underline{C}}_{A|R} \to \widetilde{\underline{C}}_{A|R}$  which is adjoint to the functor  $i_{A|R}$ . An object  $B \in ob(\underline{C}_{A|R})$  induces a continuous functor  $j : \underline{C}_{B|R} \to \underline{C}_{A|R}$  and in turn a commutative diagram

\begin{equation}\tag{*}
\begin{tikzcd}[column sep=huge, row sep=huge]
\widetilde{\underline{C}}_{A|R} \arrow[r, "\widetilde{j}"] \arrow[d, "i_{A|R}"'] & \widetilde{\underline{C}}_{B|R} \arrow[d] \\
\overset{\vee}{\underline{C}}_{A|R} \arrow[r, "j^{\vee}"'] & \overset{\vee}{\underline{C}}_{B|R}
\end{tikzcd}
\end{equation}
















where the restriction functor  $\widetilde{j}$  (as well as  $j^{\vee}$ )  is an exact functor, since the site  $\underline{C}_{B|R}$  is nothing but the category of arrows in  $\underline{C}_{A|R}$  having target  $B$ , with the induced topology. A ring homomorphism  $S \to R$  induces a continuous functor  $\beta : \underline{C}_{A|R} \to \underline{C}_{A|S}$ , and in turn a commutative diagram

\begin{equation}\tag{**}
\begin{tikzcd}[column sep=huge, row sep=huge]
\widetilde{\underline{C}}_{A|S} \arrow[r, "\widetilde{\beta}"] \arrow[d, "i_{A|S}"'] & \widetilde{\underline{C}}_{A|R} \arrow[d] \\
\overset{\vee}{\underline{C}}_{A|S} \arrow[r, "\beta^{\vee}"'] & \overset{\vee}{\underline{C}}_{A|R}
\end{tikzcd}
\end{equation}















Note that  $\widetilde{\beta}$  is not necessarily an exact functor.

3.1(b)  The right derived functor of the injection functor  $i_{A|R}: \widetilde{\underline{C}}_{A|R} \to \overset{\vee}{\underline{C}}_{A|R}$  will be denoted by  $\underline{H}^{\circ}_{A|R}$ . For each sheaf  $F$  on  $\underline{C}_{A|R}$ , we set

\begin{equation*}
H^{\circ}(A|R,F) = [H^{\circ}_{A|R}(F)](A)
\end{equation*}
For any  $B' \to B$  in  Cov($B$) , let us define the functor  $H^{0}((B' \to B),-) : \overset{\vee}{\underline{C}}_{A|R} \to (A\text{-mod})$  by  $H^{0}((B'\to B),F) = Ker(F(B') \rightrightarrows F(B'\underset{B}{\times} B'))$ . The right derived functors of  $H^{0}((B' \to B),-)$  will be denoted by  $H^{\circ}((B'\to B),-)$ . One knows that the  $H^{\circ}((B' \to B),F)$  are the cohomology groups of the (Čech)

semi-simplicial module

\begin{center}
\begin{tikzcd}[column sep=large]
F(B') \arrow[r, shift left=2] \arrow[r, shift right=2] & F(B'\times_B B') \arrow[r, shift left=3] \arrow[r] \arrow[r, shift right=3] & F(B'\ \times_B B'\ \times_B B') \arrow[r, shift left=4.5] \arrow[r, shift left=1.5] \arrow[r, shift right=1.5] \arrow[r, shift right=4.5] & \cdots
\end{tikzcd}
\end{center}








The right derived functor of  $\check{\underline{H}}^{0}_{A|R} : \overset{\vee}{\underline{C}}_{A|R} \to \overset{\vee}{\underline{C}}_{A|R}$  will be denoted by  $\check{\underline{H}}^{\bullet}_{A|R}$ ,

where

\begin{equation*}
[\check{\underline{H}}^{0}_{A|R}(F)](B) \;=\; \lim_{\{B' \to B\}\, \in\, \mathrm{Cov}(B)} H^{0}(\{B' \to B\},F) \ .
\end{equation*}
For each presheaf  $F$  on  $\underline{C}_{A|R}$  , we set

\begin{equation*}
\check{H}^{\bullet}(A|R,F) \;=\; [\check{H}^{\bullet}_{A|R}(F)](A) \;=\; \lim_{\{A' \to A\}\, \in\, \mathrm{Cov}(A)} H^{\bullet}(\{A' \to A\},F)
\end{equation*}
for any sheaf  $F$  on  $\underline{C}_{A|R}$  , we have the usual spectral sequence

\begin{equation*}
\check{H}^{p}(A|R,\underline{H}^{q}_{A|R}(F)) \;\Rightarrow\; H^{p+q}(A|R,F)
\end{equation*}
where we note that  $\check{H}^{0}(A|R,\underline{H}^{q}(F)) = 0$  for all  $q > 0$ .

In particular

\begin{equation*}
\left\{
\begin{array}{l}
\check{H}^{1}(A|R,F) \;=\; H^{1}(A|R,F) \\[2ex]
0 \to \check{H}^{2}(A|R,F) \to H^{2}(A|R,F) \to \check{H}^{1}(A|R,\underline{H}^{1}_{A|R}(F)) \to \check{H}^{3}(A|R,F) \quad \text{is exact.}
\end{array}
\right.
\end{equation*}
3.1(c)   If  $B$  is an object in  $\underline{C}_{A|R}$  , the commutative diagram (*) in 3.1(a)

together with the fact that  $\tilde{j}$  as well as  $j^{\vee}$  are exact functors yields the

canonical isomorphism

\begin{equation*}
H^{\bullet}(B|R,\tilde{j}F) \;=\; [\underline{H}^{\bullet}_{A|R}(F)](B)
\end{equation*}
On the other hand, a ring homomorphism  $S → R$  induces the commutative diagram (**)

in 3.1(a). Now  $\tilde{\beta}$  is not necessarily an exact functor. However,  $β$  preserves a

fibre-product, and thus we obtain a spectral sequence

\begin{equation*}
\underline{H}^{p}_{A|R}(R^{q}\tilde{\beta}F) \;\Rightarrow\; \check{\beta}\underline{H}^{p+q}_{A|S}(F) \qquad \text{i.e.,} \qquad H^{p}(A|R,R^{q}\tilde{\beta}F) \;\Rightarrow\; H^{p+q}(A|S,F)
\end{equation*}
Since we have the canonical isomorphism  $\tilde{\beta} = G_{A|R}\circ\check{\beta}\circ i_{A|S}$  and  $\beta^{\#} = G_{A|R}\circ\check{\beta}$  is an

exact functor, we have  $R^{\bullet}\tilde{\beta}F = \beta^{\#}\underline{H}^{\bullet}_{A|S}(F)$  . Thus the spectral sequence above can

now be written as

\begin{equation*}
H^{p}(A|R,\beta^{\#}\underline{H}^{q}_{A|S}(F)) \;\Rightarrow\; H^{p+q}(A|S,F) \ .
\end{equation*}
\underline{Lemma} 3.2.  \underline{Given}  $B \in ob(\underline{C}_{A|R})$  , \underline{choose a surjective arrow}  $P → B$  in  $\underline{C}_{B|R}$  ,

\underline{where}  $P$  \underline{is a polynomial algebra over}  $R$  . \underline{Then for any}  $F \in ob(\check{\underline{C}}_{A|R})$  , \underline{the}

\underline{natural map}  $H^{\bullet}(\{P \to B\},F) \to \check{\underline{H}}^{\bullet}(F)\ (B)$  \underline{is an isomorphism.}

\underline{Proof}:  It suffices to see that the natural map

\begin{equation*}
H^{0}(\{P \to B\},F) \to \check{\underline{H}}^{0}(F)\ (B) \;=\; \varinjlim_{\{B' \to B\}\, \in\, \mathrm{Cov}(B)} H^{0}(\{B' \to B\},F)
\end{equation*}
is an isomorphism, which is clear since, for any  $\{B' \to B\} \in \mathrm{Cov}(B)$  , there exists

an arrow  $\{P \to B\} \to \{B' \to B\}$  .


\underline{Corollary} 3.3.

(a)  \underline{Assume that}  $A$  \underline{is noetherian}. \underline{If}  $F \in ob(\widetilde{\underline{C}}_{A|R})$  \underline{is of finite type,}

\underline{then}  $\underline{H}^{n}(F)$  \underline{is of finite type for all}  $n$  .

(b)  \underline{For any polynomial algebra}  $P$  \underline{over}  $R$  , \underline{we have}  $H^{n}(P|R,F) = 0$

\underline{for all}  $n > 0$  \underline{and for all}  $F \in ob(\widetilde{\underline{C}}_{P|R})$  .

(c)  \underline{A diagram}  $0 \to F' \to F \to F'' \to 0$  \underline{in}  $\widetilde{\underline{C}}_{A|R}$  \underline{is exact if and only if}

$0 \to F'(P) \to F(P) \to F''(P) \to 0$  \underline{is exact for every}  $P \in ob(\underline{C}_{A|R})$  \underline{which is a polynomial algebra over}  $R$  .

\underline{Proof}:

(a)  In view of the spectral sequence

\begin{equation*}
\check{H}^{p}(B|R,\underline{H}^{q}(F)) \;\Rightarrow\; H^{p+q}(B|R,F)
\end{equation*}
together with the fact that  $\check{H}^{0}(\underline{H}^{q}(F)) = 0$  for all  $q > 0$  , it suffices to

show that  $\underline{H}^{n}(G)$  is of finite type for all  $n$  and for all presheaves  $G$  of finite

type. However  $\check{H}^{\bullet}(B|R,G) = H^{\bullet}(\{P \to B\},G)$  , where  $P$  is a polynomial algebra over

$R$  and  $\{P \to B\} \in \mathrm{Cov}(B)$  , and furthermore  $H^{\bullet}(\{P \to B\},G)$  is simply the

cohomology gotten from the complex

\begin{multline*}
\dots\dots\dots\dots\dots G(P \underset{B}{\times} P \underset{B}{\times} P) \;\substack{\longleftarrow\\ \longleftarrow\\ \longleftarrow}\; G(P \underset{B}{\times} P) \substack{\longleftarrow\\ \longleftarrow}\; G(P) \ .
\end{multline*}
If  $B$  is an R-algebra of finite type, then we may take  $P$  to be of finite type over  $R$  so that  $P\underset{B}{\times}\ ....\ \underset{B}{\times}P$  are all R-algebras of finite type. If  $G$  is of finite type, then  $G(P\underset{B}{\times}\ ....\ \underset{B}{\times}P)$  are all A-modules of finite type, so that  $H^{\bullet}(\{P \to B\},G)$  is an A-module of finite type since  $A$  is noetherian.

(b)  Let  $P$  be a polynomial algebra over  $R$ . If  $B \to P$  is any surjective R-algebra map, then it admits a section and hence  $H^{i}(\{B \to P\},G) = 0$  for all  $i > 0$ , so that  $\check{H}^{i}(P|R,\ G) = 0$  for all  $i > 0$  and for all presheaves  $G$  on  $\underline{C}_{P|R}$ . It follows that the spectral sequence  $\check{H}^{p}(P|R,\ \underline{H}^{q}_{P|R}(F)) \Rightarrow H^{p+q}(P|R,\ F)$  degenerates and hence  $\check{H}^{0}(P|R,\ \underline{H}^{n}(F)) \simeq H^{n}(P|R,\ F)$  for all  $n$ . However  $\check{H}^{0}(P|R,\ \underline{H}^{n}(F)) = 0$  for all  $n > 0$  whenever  $F$  is a sheaf, and hence  $H^{n}(P|R,\ F) = 0$  for all  $n > 0$  and for all  $F \in ob(\widetilde{\underline{C}}_{P|R})$ .

(c)  If  $0 \to F' \to F \to F'' \to 0$  is an exact sequence in  $\widetilde{\underline{C}}_{A|R}$ , then

\begin{equation*}
0 \to F'(B) \to F(B) \to F''(B) \to H^{1}(B|R,\ F') \to H^{1}(B|R,\ F) \to \ ....
\end{equation*}
is exact. If  $P \in ob(\underline{C}_{A|R})$  is a polynomial algebra over  $R$ , then  $H^{1}(P|R,\ F') = 0$  by 3.3(b) and hence

\begin{equation*}
0 \to F'(P) \to F(P) \to F''(P) \to 0
\end{equation*}
is exact. As for the other direction, let  $\underline{P}_{A|R}$  be the full subcategory of  $\underline{C}_{A|R}$  in which

\begin{equation*}
ob(\underline{P}_{A|R}) = \{P \in ob(\underline{C}_{A|R})|\ \ P \text{ is a polynomial algebra over } R\} \ ,
\end{equation*}
provided with the induced topology, and let  $p : \underline{P}_{A|R} \to \underline{C}_{A|R}$  be the inclusion functor. Since every object in  $\underline{C}_{A|R}$  can be covered by an object in  $\underline{P}_{A|R}$ , it follows from a comparison lemma (          ) that  $\widetilde{p} : \widetilde{\underline{C}}_{A|R} \to \widetilde{\underline{P}}_{A|R}$  is an equivalence of categories. Consequently, if  $0 \to F'(P) \to F(P) \to F''(P) \to 0$  is exact for every  $P \in ob(\underline{P}_{A|R})$ , then  $0 \to \widetilde{p}F' \to \widetilde{p}F \to \widetilde{p}F'' \to 0$  is exact in  $\widetilde{\underline{P}}_{A|R}$  and hence  $0 \to F' \to F \to F'' \to 0$  is exact in  $\widetilde{\underline{C}}_{A|R}$  .




\underline{Remark} 3.4.  Every surjective arrow in  $\underline{P}_{A|R}$  admits a section. It follows immediately that every presheaf on  $\underline{P}_{A|R}$  is actually a sheaf i.e.,  $\widetilde{\underline{P}}_{A|R} = \check{\underline{P}}_{A|R}$ . Consequently we find that the restriction functor  $\widetilde{\underline{C}}_{A|R} \to \check{\underline{P}}_{A|R}$  is an equivalence of categories.

\underline{Lemma} 3.5.  \underline{Consider a diagram of R-algebras}

\begin{center}
\begin{tikzcd}
 & C \arrow[d] \\
B' \arrow[r, "\text{surjective}"'] & B
\end{tikzcd}
\end{center}

\underline{and let}  $S$  \underline{be an R-algebra.}

(i)  \underline{If}  $\mathrm{Tor}^{R}_{1}(B,S) = 0$  , \underline{then the canonical map}

\begin{equation*}
(B'\underset{B}{\times} C) \underset{R}{\otimes} S \to (B'\underset{R}{\otimes} S) \underset{(B \underset{R}{\otimes} S)}{\times} (C \underset{R}{\otimes} S)
\end{equation*}
\underline{is an isomorphism.}

(ii)  \underline{Assume that}  $B'$  \underline{is R-flat.} \underline{If}  $\mathrm{Tor}^{R}_{i}(C,S) = 0$  \underline{for all}  $0 < i < n$  \underline{and}  $\mathrm{Tor}^{R}_{i}(B,S) = 0$  \underline{for all}  $0 < i \leq n$  , \underline{then}  $\mathrm{Tor}^{R}_{i}(B'\underset{B}{\times}C,\ S) = 0$  \underline{for all}  $0 < i < n$  .

\underline{Proof}:  Let  $0 \to J \to B' \to B \to 0$  be exact.

(i)  If  $\mathrm{Tor}^{R}_{1}(B,\ S) = 0$  , then

\begin{equation*}
0 \to J\underset{R}{\otimes}S \to B'\underset{R}{\otimes}S \to B\underset{R}{\otimes}S \to 0
\end{equation*}
is exact so that

\begin{equation*}
0 \to J\underset{R}{\otimes}S \to (B'\underset{R}{\otimes}S) \underset{(B\underset{R}{\otimes}S)}{\times} (C\underset{R}{\otimes}S) \to C\underset{R}{\otimes}S \to 0
\end{equation*}
is exact. We thus obtain an exact commutative diagram

\begin{tikzcd}
 & J \underset{R}{\otimes} S \arrow[r] \arrow[d, equal] & (B'\underset{B}{\times}C)\underset{R}{\otimes}S \arrow[r] \arrow[d] & C \underset{R}{\otimes} S \arrow[r] \arrow[d, equal] & 0 \\
0 \arrow[r] & J \underset{R}{\otimes} S \arrow[r] & (B'\underset{R}{\otimes}S) \underset{(B\underset{R}{\otimes}S)}{\times} (C \underset{R}{\otimes}S) \arrow[r] & C \underset{R}{\otimes} S \arrow[r] & 0
\end{tikzcd}
















and therefore $(B'\times_B C)\otimes_R S \to (B'\otimes_R S)\ \times_{(B\otimes_R S)}\ (C \otimes_R S)$  is an isomorphism.

(ii)  Since  $B'$  is R-flat and  $\mathrm{Tor}^R_i(B,\ S) = 0$  for all  $0 < i \leq n$   by hypothesis, we have  $\mathrm{Tor}^R_i(J,\ S) = 0$  for all  $0 < i < n$  . Then the exact sequence  $0 \to J \to B'\times_B C \to C \to 0$  together with the hypothesis that  $\mathrm{Tor}^R_i(C,\ S) = 0$  for all  $0 < i < n$  entails that  $\mathrm{Tor}^R_i(B'\times_B C,\ S) = 0$  for all  $0 < i < n$  .


\underline{Corollary} 3.6.

(a)  \underline{Let}  $A, S$  \underline{be} R-\underline{algebras. If}  $\mathrm{Tor}^R_1(A,\ S) = 0$  , \underline{then the canonical map}  $\check{H}^{\cdot}(A\otimes_R S|S,\ G) \to \check{H}^{\cdot}(A|R,\ \check{S}G)$  \underline{is an isomorphism for any}  $G \in \mathrm{ob}(\check{\underline{C}}_{A\otimes_R S|S})$  \underline{where the functor}  $S : \underline{C}_{A|R} \to \underline{C}_{A\otimes_R S|S}$  \underline{is given by}  $X \longmapsto X\otimes_R S$  . \underline{In particular if}  $S$  \underline{is} R-\underline{flat, then the canonical map}  $\check{S}\underline{\check{H}}^{\cdot}(G) \to \underline{\check{H}}^{\cdot}(\check{S}G)$  \underline{is an isomorphism for every}  $G \in \mathrm{ob}(\check{\underline{C}}_{A\otimes_R S|S})$  .

(b)  \underline{Let}  $P \to B$  \underline{be a surjective} R-\underline{algebra map, where}  $P$  \underline{is a polynomial algebra over}  $R$  . \underline{If}  $\mathrm{Tor}^R_i(B,\ S) = 0$  \underline{for all}  $0 < i \leq n$  , \underline{then} $\mathrm{Tor}^R_i(P\times_B P\times_B \ldots \times_B P,\ S) = 0$  \underline{for all}  $0 < i < n$  .


\underline{Proof}:

(a)  Given  $B \in \mathrm{ob}(\underline{C}_{A|R})$  , choose  $\{P \to B\} \in \mathrm{Cov}(B)$  where  $P$  is a polynomial algebra over  $R$  . If  $\mathrm{Tor}^R_1(B,\ S) = 0$  , the natural map

\begin{equation*}
(\overbrace{P\times_B \ \ldots\ \times_B P}^{\,n\,})\otimes_R S \to (P\otimes_R S)\times_{(B\otimes_R S)} \ldots \times_{(B\otimes_R S)} (P\otimes_R S)
\end{equation*}
is an isomorphism for all  $n$  by 3.5(i), and hence  $\check{H}^{\cdot}(B|R,\ \check{S}G) = H^{\cdot}(\{P \to B\},\ \check{S}G) = H^{\cdot}(\{P\otimes_R S \to B\otimes_R S\},\ G) = \check{H}^{\cdot}(B\otimes_R S|S,\ G)$  . If  $S$  is R-flat, then  $\mathrm{Tor}^R_1(X,\ S) = 0$  for every  $X \in \mathrm{ob}(\underline{C}_{A|R})$  and hence $\check{H}^{\cdot}(X\otimes_R S|S,\ G) \to \check{H}^{\cdot}(X|R,\ \check{S}G)$  is an isomorphism for every  $X \in \mathrm{ob}(\underline{C}_{A|R})$  i.e. $\check{S}\underline{\check{H}}^{\cdot}(G) \to \underline{\check{H}}^{\cdot}(\check{S}G)$  is an isomorphism.

(b)  Set  $P^{(m)} = \overbrace{P\times_B \ \ldots\ \times_B P}^{\,m+1\,}$  . If  $m = 0$  there is nothing to prove since  $P$  is R-flat. Assume that  $\mathrm{Tor}^R_i(P^{(m-1)},\ S) = 0$  for all  $0 < i < n$  . Since  $P \to B$  is surjective and  $P^{(m)} = P\times_B P^{(m-1)}$  , it follows from 3.5(ii) that $\mathrm{Tor}^R_i(P^{(m)},\ S) = 0$  for all  $0 < i < n$  .





\underline{Proposition} 3.7.

(a)  \underline{Let}  $A, S$  \underline{be} R-\underline{algebras. If}  $\mathrm{Tor}^R_i(A,\ S) = 0$  \underline{for all}  $0 < i \leq n$  , \underline{then for any sheaf}  $F$  \underline{on}  $\underline{C}_{A\otimes_R S|S}$  , \underline{the canonical map}  $H^i(A\otimes_R S|S,\ F) \to H^i(A|R,\ \widetilde{S}F)$ \underline{is an isomorphism for all}  $i \leq n$  , \underline{where}  $S : \underline{C}_{A|R} \to \underline{C}_{A\otimes_R S|S}$  \underline{is given by} $X \longmapsto X\otimes_R S$  .

(b)  \underline{Let}  $P$  \underline{be a polynomial algebra over}  $R$  . \underline{Then for any additive sheaf}  $F$  \underline{on}  $\underline{C}_{P\otimes_R A|R}$  , \underline{the canonical map}  $H^n(P\otimes_R A|R,\ F) \to H^n(A|R,\ F)$  \underline{is an isomorphism for all}  $n > 0$  .

(c)  \underline{Let}  $S \to R \to A$  \underline{be ring homomorphisms. Then for any additive sheaf}  $F$  \underline{on}  $\underline{C}_{A|S}$  , \underline{we have an exact sequence}

{\small \begin{multline*}
0 \to H^0(A|R,\ F_R) \to H^0(A|S,\ F) \to H^0(R|S,\ F) \to H^1(A|R,\ F_R) \to H^1(A|S,\ F) \to H^1(R|S,\ F) \to \\ \ldots\ldots\ldots \to H^n(A|R,\ F_R) \to H^n(A|S,\ F) \to H^n(R|S,\ F) \to H^{n+1}(A|R,\ F_R) \to \ldots.
\end{multline*}}
\underline{where}  $F_R$  \underline{is a sheaf on}  $\underline{C}_{A|R}$ \underline{defined by}

\begin{equation*}
F_R(X) = \mathrm{Ker}(F(X) \to F(R))
\end{equation*}
\underline{for all}  $X \in \mathrm{ob}(\underline{C}_{A|R})$  \underline{via the forgetful functor}  $\underline{C}_{A|R} \to \underline{C}_{A|S}$  .


\underline{Proof}:

(a)  Consider the continuous functor

\begin{equation*}
S : \underline{C}_{A|R} \to \underline{C}_{A\otimes_R S|S}
\end{equation*}
where  $S(X) = X\otimes_R S$  . Since the functor  $S$  sends polynomial algebras over  $R$  to polynomial algebras over  $S$  ,  $\widetilde{S} : \widetilde{\underline{C}}_{A\otimes_R S|S} \to \widetilde{\underline{C}}_{A|R}$  is an exact functor by 3.3(c) and in turn we obtain the canonical map  $\check{S}\underline{H}^{\cdot}_{A\otimes_R S|S}(F) \to \underline{H}^{\cdot}_{A|R}(\widetilde{S}F)$  , and in turn we obtain the commutative diagram of spectral sequences:

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=large]
E^{p,q}_S(S(X)) = \check{H}^p(X\otimes_R S|S,\ \underline{H}^q_{A\otimes_R S|S}(F)) \arrow[r, Rightarrow] \arrow[d] & H^{p+q}(X\otimes_R S|S,\ F) \arrow[dd] \\
\check{H}^p(X|R,\ \check{S}\underline{H}^q_{A\otimes_R S|S}(F)) \arrow[d] & \\
E^{p,q}_R(X) =\ \ \check{H}^p\ (X|R,\ \underline{H}^q_{A|R}(\widetilde{S}F)) \arrow[r, Rightarrow] & H^{p+q}(X|R,\ \widetilde{S}F)
\end{tikzcd}
\end{center}






















We note that  $E^{p,q}_{S}(S(X)) \to \check{H}^{p}(X|R,\ \check{S}\underline{H}^{q}_{A\underset{R}{\otimes}S|S}(F))$  is an isomorphism whenever $\operatorname{Tor}^{R}_{1}(X,\ S) = 0$  by 3.6(a). Assume now that $[\check{S}\underline{H}^{q}_{A\underset{R}{\otimes}S|S}(F)](X) \to [\underline{H}^{q}_{A|R}(\widetilde{S}F)](X)$  is an isomorphism for all  $q < n$  and for all $X \in \mathrm{ob}(\underline{C}_{A|R})$  such that  $\operatorname{Tor}^{R}_{i}(X,\ S) = 0$  for all  $0 < i < n$ . It follows immediately from 3.6(b) that  $E^{p,q}_{S}(S(X)) \to E^{p,q}_{R}(X)$  is an isomorphism for all  $q < n$ and for all  $p$ , provided  $\operatorname{Tor}^{R}_{i}(X,\ S) = 0$  for all  $0 < i \leq n$ . Since $E^{0,n}_{S}(S(X)) \to E^{0,n}_{R}(X)$  is an isomorphism (since both sides are zero), we get that $H^{n}(X\underset{R}{\otimes}S|S,\ F) \to H^{n}(X|R,\ \widetilde{S}F)$  is an isomorphism whenever  $\operatorname{Tor}^{R}_{i}(X,\ S) = 0$  for all $0 < i \leq n$  i.e.,  $[\check{S}\underline{H}^{i}_{A\underset{R}{\otimes}S|S}(F)](X) \to [\underline{H}^{i}_{A|R}(\widetilde{S}F)](X)$  is an isomorphism for all $i \leq n$  whenever  $\operatorname{Tor}^{R}_{i}(X,\ S) = 0$  for all  $0 < i \leq n$ .

(b)  Let  $P$  be a polynomial algebra over  $R$  and  let $f : \underline{C}_{A|R} \to \underline{C}_{A\underset{R}{\otimes}P|R}$  be the continuous functor given by  $f(X) = X\underset{R}{\otimes}P$ . Let  $P' \to X$ be a surjective arrow in  $\underline{C}_{A|R}$  where  $P'$  is a polynomial algebra over  $R$ . Then $P'\underset{R}{\otimes}P \to X\underset{R}{\otimes}P$  is a surjective arrow in  $\underline{C}_{A\underset{R}{\otimes}P|R}$ , and  $P'\underset{R}{\otimes}P$  is again a polynomial algebra over  $R$ . Since  $P$  is flat over  $R$ , it follows from 3.5(i) that $\check{H}^{\cdot}(X|R,\ \check{f}G) = H^{\cdot}(\{P' \to X\},\ \check{f}G) = H^{\cdot}\ (\{P'\underset{R}{\otimes}P \to X\underset{R}{\otimes}P\},\ G) = \check{H}^{\cdot}(X\underset{R}{\otimes}P|R,\ G)$ for every  $G \in \mathrm{ob}(\underline{\check{C}}_{A\underset{R}{\otimes}P|R})$ . It follows that  $\widetilde{f} : \underline{\widetilde{C}}_{A\underset{R}{\otimes}P|R} \to \underline{\widetilde{C}}_{A|R}$  sends acyclic ones to acyclic ones. On the other hand,  $f$  sends polynomial algebras over  $R$  to polynomial algebras over  $R$ , and hence  $\widetilde{f} : \underline{\widetilde{C}}_{A\underset{R}{\otimes}P|R} \to\!\underline{\widetilde{C}}_{A|R}$  is an exact functor by 3.3(c). It follows that  $H^{\cdot}(A\underset{R}{\otimes}P|R,\ F) \to H^{\cdot}(A|R,\ \widetilde{f}F)$  is an isomorphism for every $F \in \mathrm{ob}(\underline{\widetilde{C}}_{A\underset{R}{\otimes}P|R})$ . Now for each  $X \in \mathrm{ob}(\underline{C}_{A|R})$ , we have canonical maps

\begin{equation*}
(\widetilde{f}F)\ (X) = F(X\underset{R}{\otimes}P) \to F(X)\oplus F(P)\ \ ,
\end{equation*}
and hence a canonical map  $\widetilde{f}F \to F\oplus F(P)$  where  $F(P)$  denotes a constant sheaf (and  $F$  on the right hand side denotes, strictly speaking, the restriction of  $F$ on  $\underline{C}_{A|R}$ ) . If  $F$  is an additive sheaf, then  $(\widetilde{f}F)\ (X) = F(X\underset{R}{\otimes}P) \overset{\sim}{\to} F(X)\oplus F(P)$ is an isomorphism for every  $X \in \mathrm{ob}(\underline{C}_{A|R})$  and hence  $\widetilde{f}F \overset{\sim}{\to} F\oplus F(P)$  is an isomorphism. Therefore 




\begin{equation*}
 H^{n}(A|R,\ \widetilde{f}F) \overset{\sim}{\to} H^{n}(A|R,\ F\oplus F(P)) = H^{n}(A|R,\ F)
\end{equation*}
for all  $n > 0$  since  $F(P)$ , being a constant sheaf, is flask. It follows that $H^{n}(A\underset{R}{\otimes}P|R,\ F) \to H^{n}(A|R,\ F)$  is an isomorphism for all  $n > 0$ , provided  $F$  is an additive sheaf on  $\underline{C}_{A\underset{R}{\otimes}P|R}$ .

(c)  (communicated from Rinehart) Consider the forgetful functor $\beta : \underline{C}_{A|R} \to \underline{C}_{A|S}$ . We have a spectral sequence

\begin{equation*}
E^{p,q} = H^{p}(A|R,\ \beta^{\#}\underline{H}^{q}_{A|S}(F))\ \Longrightarrow\ H^{p+q}(A|S,\ F)
\end{equation*}
where  $\beta^{\#} = G_{A|R}\circ\check{\beta}$ ,  $G_{A|R} : \underline{\check{C}}_{A|R} \to \underline{\widetilde{C}}_{A|R}$  is the "associated-sheaf"  functor. Now let  $F$  be an additive sheaf. We claim that  $\beta^{\#}\underline{H}^{q}_{A|S}(F)$  is a constant sheaf for all  $q > 0$ . Indeed, if  $P$  is a polynomial algebra over  $R$ , then  $P = R\underset{S}{\otimes}P'$ for a polynomial algebra  $P'$  over  $S$  and hence

\begin{equation*}
[\beta^{\#}\underline{H}^{q}_{A|S}(F)](P) = H^{q}(P|S,\ F) = H^{q}(R\underset{S}{\otimes}P'|S,\ F) \to H^{q}(R|S,\ F)
\end{equation*}
is an isomorphism for all  $q > 0$  by 3.7(b), and surjective for  $q = 0$ . It follows from 3.3(c) that the canonical map  $\beta^{\#}\underline{H}^{q}_{A|S}(F) \to H^{q}(R|S,\ F) =$ constant sheaf is an isomorphism for all  $q > 0$ , and is surjective for  $q = 0$ . It follows that $E^{p,q} = H^{p}(A|R,\ \beta^{\#}\underline{H}^{q}_{A|S}(F)) = 0$  for all  $p,\ q > 0$ , and hence the above spectral sequence yields the exact sequence

\begin{equation*}
(*)\quad 0 \to E^{1,0} \to H^{1} \to E^{0,1}\!\to\ E^{2,0} \to H^{2} \to E^{0,2} \to E^{3,0}\!\to\ H^{3} \to\ ....
\end{equation*}
where we note that  $E^{0,q} = [\beta^{\#}\underline{H}^{q}_{A|S}(F)](A) \overset{\sim}{\to} H^{q}(R|S,\ F)$  for all  $q > 0$  and $E^{p,0} = H^{p}(A|R,\ \widetilde{\beta}F)$ . On the other hand, the exact sequence  $0 \to F_{R} \to \widetilde{\beta}F \to F(R) \to 0$ gives us the exact sequence

{\footnotesize (**)\quad\begin{tikzcd}[column sep=tiny, row sep=large]
0 \arrow[r] & H^{0}(A|R,F_{R}) \arrow[r] & H^{0}(A|R,\widetilde{\beta}F) \arrow[r] \arrow[d, equal] & H^{0}(A|R,F(R)) \arrow[r] \arrow[d, equal] & H^{1}(A|R,F_{R}) \arrow[r] & H^{1}(A|R,\widetilde{\beta}F) \arrow[r] & 0 \\
 & & H^{0}(A|S,F) & H^{0}(R|S,F) & & &
\end{tikzcd}}










The exact sequences (*) and (**) combined give the desired exact sequence.




\underline{Corollary} 3.8.

(a)  \underline{If}  $A, B$  \underline{are} $R$-\underline{algebras such that}  $\mathrm{Tor}^{R}_{i}(A, B) = 0$  \underline{for all} $0 < i \leq n$  , \underline{then for any additive sheaf}  $F \in \mathrm{ob}(\widetilde{\underline{C}}_{A\underset{R}{\otimes}B|R})$  , \underline{the canonical map}

\begin{equation*}
H^{i}(A\underset{R}{\otimes}B|R,\ F) \rightarrow H^{i}(A|R,\ F) \oplus H^{i}(B|R,\ F)
\end{equation*}
\underline{is an isomorphism for all}  $i \leq n$  .

(b)  \underline{Let}  $A$  \underline{be an} $R$-\underline{algebra such that}  $\mathrm{Tor}^{R}_{i}(A, A) = 0$  \underline{for all}  $i > 0$  . \underline{If}  $A\underset{R}{\otimes}A \rightarrow A$  \underline{is an isomorphism, then for any additive sheaf}  $F \in \mathrm{ob}(\widetilde{\underline{C}}_{A|R})$  , \underline{we have}  $H^{i}(A|R,\ F) = 0$  \underline{for all}  $i$  .


\underline{Proof:}

(a)  Let  $F \in \mathrm{ob}(\widetilde{\underline{C}}_{A\underset{R}{\otimes}B|R})$  be additive. By 3.7(c), the ring homomorphisms $R \rightarrow A \rightarrow A\underset{R}{\otimes}B$  give us the exact sequence

\begin{equation}\tag{*}
... \rightarrow H^{i}(A\underset{R}{\otimes}B|A,\ F_{A}) \rightarrow H^{i}(A\underset{R}{\otimes}B|R,\ F) \rightarrow H^{i}(A|R,\ F) \rightarrow ....
\end{equation}
consider now the commutative diagram

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=huge]
H^{i}(A\underset{R}{\otimes}B|A,\ F_{A}) \arrow[r] \arrow[d] & H^{i}(A\underset{R}{\otimes}B|R,\ F) \arrow[d] \\
H^{i}(B|R,\ \widetilde{A}F_{A}) \arrow[r, "\approx"] & H^{i}(B|R,\ F)
\end{tikzcd}
\end{center}









where the functor  $A : \underline{C}_{B|R} \rightarrow \underline{C}_{A\underset{R}{\otimes}B|A}$  is given by  $X \longmapsto A\underset{R}{\otimes}X$  , and the map $H^{i}(B|R,\ \widetilde{A}F_{A}) \rightarrow H^{i}(B|R,\ F)$  is induced from the map  $\widetilde{A}F_{A} \rightarrow F$  , which is an isomorphism since  $F$  is additive.  Note that the commutativity of the above diagram, because of its functorial nature, is reduced to the case  $i = 0$  .

If  $\mathrm{Tor}^{R}_{i}(A, B) = 0$  for all  $0 < i \leq n$  , then  $H^{i}(A\underset{R}{\otimes}B|A,\ F_{A}) \rightarrow H^{i}(B|R,\ \widetilde{A}F_{A})$  is an isomorphism for all  $i \leq n$  by 3.7(a), and hence the composite map

\begin{equation*}
H^{i}(A\underset{R}{\otimes}B|A,\ F_{A}) \rightarrow H^{i}(A\underset{R}{\otimes}B|R,\ F) \rightarrow H^{i}(B|R,\ F)
\end{equation*}
and (because of the symmetry) 




\begin{equation*}
 H^{i}(A\underset{R}{\otimes}B|B,\ F_{B}) \rightarrow H^{i}(A\underset{R}{\otimes}B|R,\ F) \rightarrow H^{i}(A|R,\ F)
\end{equation*}
are isomorphisms for all  $i \leq n$  . This implies that the exact sequence (*) breaks up to short split-exact sequences

\begin{equation*}
0 \rightarrow H^{i}(A\underset{R}{\otimes}B|A,\ F_{A}) \rightarrow H^{i}(A\underset{R}{\otimes}B|R,\ F) \rightarrow H^{i}(A|R,\ F) \rightarrow 0
\end{equation*}
for all  $i \leq n$  , and that

\begin{equation*}
H^{i}(A\underset{R}{\otimes}B|R,\ F) \rightarrow H^{i}(A|R,\ F) \oplus H^{i}(B|R,\ F)
\end{equation*}
is an isomorphism for all  $i \leq n$  .

(b)  Since  $\mathrm{Tor}^{R}_{i}(A,A) = 0$  for all  $i > 0$  , it follows from 3.8(a) that

\begin{equation*}
H^{i}(A\underset{R}{\otimes}A|R,\ F) \rightarrow H^{i}(A|R,\ F) \oplus H^{i}(A|R,\ F)
\end{equation*}
is an isomorphism for all  $i$  . On the other hand,  $A\underset{R}{\otimes}A \rightarrow A$  is an isomorphism by hypothesis and hence  $H^{i}(A|R,\ F) \rightarrow H^{i}(A\underset{R}{\otimes}A|R,\ F)$  is an isomorphism for all  $i$  . This means that the diagonal map  $H^{i}(A|R,\ F) \rightarrow H^{i}(A|R,\ F) \oplus H^{i}(A|R,\ F)$  is an isomorphism for all  $i$  i.e.,  $H^{i}(A|R,\ F) = 0$  for all  $i$  .

\underline{Corollary} 3.9:  Let  $S$  be a multiplicative subset of an $R$-algebra  $A$  . If  $F \in \mathrm{ob}\!\left(\widetilde{\underline{C}}_{S^{-1}A|R}\right)$  is additive such that  $F_{A}$  is also additive, then the canonical map

\begin{equation*}
H^{i}(S^{-1}A|R,\ F) \rightarrow H^{i}(A|R,\ F)
\end{equation*}
is an isomorphism for all  $i$  , where  $F_{A} \in \mathrm{ob}\!\left(\widetilde{\underline{C}}_{S^{-1}A|A}\right)$  is defined by $F_{A}(X) = \mathrm{Ker}(F(X) \rightarrow F(A))$  for all  $X \in \mathrm{ob}\!\left(\underline{C}_{S^{-1}A|A}\right)$  .

\underline{Proof}:  Since  $F$  is additive, the ring homomorphisms  $R \rightarrow A \rightarrow S^{-1}A$  give us the exact sequence

\begin{equation*}
.... \rightarrow H^{n}(S^{-1}A|A,\ F_{A}) \rightarrow H^{n}(S^{-1}A|R,\ F) \rightarrow H^{n}(A|R,\ F) \rightarrow ....
\end{equation*}
On the other hand, since  $S^{-1}A\underset{A}{\otimes}S^{-1}A \rightarrow S^{-1}A$  is an isomorphism and  $F_{A}$  is additive by hypothesis, it follows from 3.8(b) that  $H^{n}(S^{-1}A|A,\ F_{A}) = 0$  for all  $n$  , and hence  $H^{n}(S^{-1}A|R,\ F) \rightarrow H^{n}(A|R,\ F)$  is an isomorphism for all  $n$  .




Now let  $A$  be an $R$-algebra. An $A$-module  $M$  defines an additive sheaf $\mathrm{Der}_R(-,\ M) \in \mathrm{ob}(\widetilde{\underline{C}}_{A|R})$  by  $X \to \mathrm{Der}_R(X,\ M)$  . We now make the following definition:


\underline{Definition} 3.10:  \underline{Let}  $A$  \underline{be an} $R$-\underline{algebra. For each} $A$-\underline{module}  $M$  \underline{we set}

\begin{equation*}
D^i(A|R,\ M) = H^i(A|R,\ \mathrm{Der}_R(-,\ M)) \ \ .
\end{equation*}
We want to make an explicit computation of low-dimensional ones i.e., $D^i(A|R,\ M)$  for  $i = 1,\ 2$  : Choose a surjective arrow  $P \to A$  in  $\underline{C}_{A|R}$  where  $P$  is a polynomial algebra over  $R$  , and let  $0 \to I \to P \to A \to 0$  be exact. Then


\underline{Lemma} 3.10:

\begin{equation*}
\begin{aligned}
D^1(A|R,\ M) &= \mathrm{Coker}(\mathrm{Der}_R(P,\ M) \to \mathrm{Hom}_P(I,\ M)) \\
D^2(A|R,\ M) &= H^1(A|R,\ \underline{H}^1_{A|R}(\mathrm{Der}_R(-,\ M)))
\end{aligned}
\end{equation*}
\underline{Proof}:  Consider the simplicial algebra

\begin{multline}\tag{*}
........\ \ P_A^{(2)} \ \mathrel{\substack{\to\\ \to\\ \to}} \ P_A^{(1)} \ \mathrel{\substack{\to\\ \to}} \ P_A^{(0)}
\end{multline}
where  $P_A^{(n)} = \overbrace{P\times_A \ldots \times_A P}^{\,n+1}$  . For each  $n$  we have the exact sequence

\begin{equation*}
0 \to I^{(n)} \to P_A^{(n)} \to A \to 0
\end{equation*}
where  $I^{(n)} = \overbrace{I\times I\times \ldots \times I}^{\,n+1}$  , and it is easy to see that

(a):

\begin{equation*}
0 \to \mathrm{Hom}_A(\overline{I}^{(n)}/\Delta(\overline{I}),\ M) \to \mathrm{Der}_R(P_A^{(n)},\ M) \xrightarrow{\ \mathrm{Der}(\Delta,\ M)\ } \mathrm{Der}_R(P,\ M) \to 0
\end{equation*}
is exact for all  $n$  , where  $\overline{I} = I/I^2$  and  $\Delta$  stands for the diagonal map. We also note the exact sequence

(b):

\begin{equation*}
0 \to \mathrm{Hom}_A(\overline{I}^{(n)}/\Delta(\overline{I}),\ M) \to \mathrm{Hom}_A(\overline{I}^{(n)},\ M) \xrightarrow{\ \mathrm{Hom}(\Delta,\ M)\ } \mathrm{Hom}_A(\overline{I},\ M) \to 0
\end{equation*}
The exact sequences (a) and (b) yield the respective exact sequences of simplicial $A$-modules. Since  $\{I \to 0\}$ , $\{I \to I\}$  admit sections, we have

\begin{equation*}
H^i(\{I \to 0\},\ \mathrm{Hom}_A(-,\ M)) = H^i(\{I \to I\},\ \mathrm{Hom}_A(-,\ M)) = 0 
\end{equation*}



 for all  $i > 0$  , and it follows readily that

\begin{equation*}
\left\{\begin{array}{l}
0 \to \mathrm{Der}_R(A,\ M) \to \mathrm{Der}_R(P,\ M) \to \mathrm{Hom}_A(\overline{I},\ M) \to H^1(\{P \to A\},\ \mathrm{Der}_R(-,\ M)) \to 0 \\[4pt]
\hspace{9cm}\text{is exact} \\[4pt]
H^i(\{P \to A\},\ \mathrm{Der}_R(-,\ M)) = 0 \ \ \text{for all} \ \ i > 1
\end{array}\right.
\end{equation*}
It follows from 3.1(b) that

\begin{equation*}
\begin{aligned}
D^1(A|R,\ M) &= \check{H}^1(A|R,\ \mathrm{Der}_R(-,\ M)) = H^1(\{P \to A\},\ \mathrm{Der}_R(-,\ M)) \\
&= \mathrm{Coker}(\mathrm{Der}_R(P,\ M) \to \mathrm{Hom}_A(\overline{I},\ M)) \\
&= \mathrm{Coker}(\mathrm{Der}_R(P,\ M) \to \mathrm{Hom}_P(I,\ M)) \ \ , \\
D^2(A|R,\ M) &= H^1(A|R,\ \underline{H}^1_{A|R}(\mathrm{Der}_R(-,\ M))) \ \ .
\end{aligned}
\end{equation*}
Now choose a free $P$-module  $F$  and a $P$-linear map  $F \xrightarrow{\ \gamma\ } P$  such that  $\gamma(F) = I$  . Associated to $P$-linear map  $\gamma : F \to P$  , there is a Koszul complex, which is simply denoted, by abuse of notation, by  $K_I$  .


\underline{Lemma} 3.11:   $D^2(A|R,\ M) \simeq \mathrm{Coker}(H^1(K_I,\ M) \to \mathrm{Hom}_A(H_1(K_I),\ M))$ .

\underline{Proof}:  We have

\begin{equation*}
\begin{aligned}
D^2(A|R,\ M) &= H^1(A|R,\ H^1_{A|R}(\mathrm{Der}_R(-,\ M))) \\
&= \mathrm{Ker}(H^1(P_A^{(1)}|R,\ M) \ \mathrel{\substack{\to\\ \to\\ \to}} \ H^1(P_A^{(2)}|R,\ M))
\end{aligned}
\end{equation*}
since  $[\underline{H}^1_{A|R}(\mathrm{Der}_R(-,\ M))](P_A^0) = [\underline{H}^1_{A|R}(\mathrm{Der}_R(-,\ M))](P) = 0$  .

Let  $0 \to K \to F \xrightarrow{\ \gamma\ } I \to 0$  be exact. If we set  $P[F]$  to be the symmetric algebra over  $P$  generated by  $F$  , then  $P[F]$  and  $P[F]\otimes P[F]$  are polynomial algebras over  $R$  and we obtain the surjective arrows

\begin{equation*}
\begin{aligned}
P[F] \to P_A^{(1)} &= P\times_A P &&\text{given by} && X \to (0,\ \gamma(X)) \\
P[F]\otimes_P P[F] \to P_A^{(2)} &= P\times_A P\times_A P && && X\otimes 1 \to (0,\ \gamma(X),\ 0),\ 1\otimes X \to (0,\ 0,\ \gamma(X))
\end{aligned}
\end{equation*}
where  $X \in F$  . If we set  $J = \mathrm{Ker}(P[F] \to P_A^{(1)})$ and
$J' = \mathrm{Ker}(P[F]\otimes_P P[F] \to P_A^{(2)})$  , then 





\begin{align*}
J &= (F) \cap (F_\gamma) = (K) + (F\cdot F_\gamma)\\
J' &= (F\otimes 1 + 1\otimes F) \cap (F_\gamma\otimes 1 + 1\otimes F) \cap (F\otimes 1 + 1\otimes F_\gamma)\\
&= (K\otimes 1 + 1\otimes K) + (F\cdot F_\gamma\otimes 1 + 1\otimes F\cdot F_\gamma) + (F\otimes F)
\end{align*}

where  $F_\gamma$ $=$ the ideal generated by  $\{X - \gamma(X)|X \in F\}$  . Now  $\pi_i : P_A^{(2)} \to P_A^{(1)}$  $i = 0, 1, 2$  can be lifted to  $\hat{\pi}_i : P[F]\underset{P}{\otimes}P[F] \to P[F]$  where, for each  $X \in F$  ,

$$\pi_0 = \begin{cases} X\otimes 1 \to \gamma(X) - X\\[3ex] 1\otimes X \to X\end{cases}\qquad\qquad \pi_1 = \begin{cases} X\otimes 1 \to 0\\[3ex] 1\otimes X \to X\end{cases}\qquad\qquad \pi_2 = \begin{cases} X\otimes 1 \to X\\[3ex] 1\otimes X \to 0\end{cases}\qquad .$$
A trivial computation shows that  $\pi_0 - \pi_1 + \pi_2$  sends  $K\otimes 1 + 1\otimes K + 1\otimes F\cdot F_\gamma$  to zero, whereas it sends  $(F\cdot F_\gamma\otimes 1 + F\otimes F)$  onto  $(F\cdot F_\gamma)$  . Now for any $D \in \mathrm{Der}_R(P[F]\underset{P}{\otimes}P[F], M)$  ,  $D(F\cdot F_\gamma\otimes 1 + F\otimes F) = 0$  since  $I\cdot M = 0$  , and consequently

\begin{align*}
D^2(A|R, M) &= \mathrm{Ker}(D^1(P_A^{(1)}|R, M) \mathrel{\substack{\to\\ \to\\ \to}} D^1(P_A^{(2)}|R, M))\\
&= \{[f] \in D^1(P_A^{(1)}|R, M)|f(F\cdot F_\gamma) = 0\}\\
&= \mathrm{Coker}(\mathrm{Der}_R(P[F], M) \to \mathrm{Hom}_{P[F]}((F) \cap (F_\gamma)/(F\cdot F_\gamma), M))\\
&= \mathrm{Coker}(\mathrm{Der}_P(P[F], M) \to \mathrm{Hom}_{P[F]}((F) \cap (F_\gamma)/(F)\cdot(F_\gamma), M))\quad .
\end{align*}

Now
$$\begin{aligned}
0 \to (F) \to P[F] &\xrightarrow{\;\;P[0]\;\;} P \to 0\\
0 \to (F_\gamma) \to P[F] &\xrightarrow{\;\;P[\gamma]\;\;} P \to 0 \quad .
\end{aligned}$$
are exact and hence  $(F) \cap (F_\gamma)/(F)\cdot(F_\gamma) = \mathrm{Tor}_1^{P[F]}(P, P_\gamma) = H_1(K_I)$  where  $K_I$  is the Koszul complex associated  to the $P$-linear map  $F \xrightarrow{\gamma} I(\subset P)$  . We thus have

\begin{align*}
D^2(A|R, M) &= \mathrm{Coker}(\mathrm{Hom}_P(F, M) \to \mathrm{Hom}_P(H_1(K_I), M))\\
&= \mathrm{Coker}(H^1(K_I, M) \to \mathrm{Hom}_A(H_1(K_I), M))\quad .
\end{align*}

We can now state all the basic facts needed for our purpose, summarizing the various results we have already established.





\underline{Theorem} 3.12.

(1)  \underline{If}  $0 \to M' \to M \to M'' \to 0$  \underline{is an exact sequence of} $A$-\underline{modules, then}

\begin{gather*}
0 \to D^0(A|R, M') \to D^0(A|R, M) \to D^0(A|R, M'') \to D^1(A|R, M') \to\\
D^1(A|R, M)\to\;\; D^1(A|R, M'') \to\; ........ \;\to D^n(A|R, M') \to\\
D^n(A|R, M) \to D^n(A|R, M'') \to \;...
\end{gather*}

\underline{is exact}.

(2)  \underline{Let}  $S \to R \to A$  \underline{be ring homomorphisms. Then for any $A$-module}  $M$  \underline{we have the exact sequence}

\begin{gather*}
0 \to D^0(A|R, M) \to D^0(A|S, M) \to D^0(R|S, M) \to D^1(A|R, M) \to\\
D^1(A|S, M) \to D^1(R|S, M) \to\; ........ \;\to D^n(A|R, M) \to\\
D^n(A|S, M) \to D^n(R|S, M) \to \;....
\end{gather*}

(3)  \underline{Let}  $A, S$  \underline{be $R$-algebras such that}  $\mathrm{Tor}_i^R(A, S) = 0$  \underline{for all}  $i > 0$  . \underline{Then for any}  $A\underset{R}{\otimes}S$-\underline{module}  $M$  , \underline{the canonical map}  $D^i(A\underset{R}{\otimes}S|S, M) \to D^i(A|R, M)$  \underline{is an} \underline{isomorphism for all}  $i$  . \underline{In particular, if}  $A$  \underline{is} $R$-\underline{flat we have}

$$D^i(A\otimes S|S, M) \xrightarrow{\sim} D^i(A|R, M)$$
\underline{for all}  $i$  \underline{and for all} $R$-\underline{algebras}  $S$  .

(4)  \underline{Let}  $S$  \underline{be a multiplicative subset of}  $A$  . \underline{Then for any}  $S^{-1}A$-\underline{module} $N$  , \underline{the canonical map}

$$D^i(S^{-1}A|R, N) \to D^i(A|R, N)$$
\underline{is an isomorphism for all}  $i$  . \underline{Consequently, for any} $A$-\underline{module}  $M$  \underline{we have the} \underline{canonical isomorphism}

$$D^i(S^{-1}A|R, S^{-1}M) \xrightarrow{\sim} S^{-1}D^i(A|R, M)$$
\underline{for all}  $i$  .

(5)  \underline{If}  $A, B$  \underline{are} $R$-\underline{algebras such that}  $\mathrm{Tor}_i^R(A, B) = 0$  \underline{for all} $0 < i \leq n$  , \underline{then for any}  $A\underset{R}{\otimes}B$-\underline{module}  $M$  , \underline{the canonical map}

$$D^i(A\underset{R}{\otimes}B|R, M) \to D^i(A|R, M) \oplus D^i(B|R, M)$$
\underline{is an isomorphism for all}  $i \leq n$  . \underline{In particular, if}  $\mathrm{Tor}_i^R(A, A) = 0$  \underline{for all}

$i > 0$  \underline{and}

\begin{equation*}
\Delta \ : \ \mathrm{Spec}(A) \ \to \ \mathrm{Spec}(A) \underset{\mathrm{Spec}(R)}{\times} \mathrm{Spec}(A)
\end{equation*}
\underline{is an open immersion} (\underline{for instance}  $A/R$  \underline{etale}), \underline{then}  $D^i(A|R, M) = 0$  \underline{for all} $i > 0$  \underline{and for all} $A$-\underline{modules}  $M$ .

(6) \underline{Let}  $A$  \underline{be an} $R$-\underline{algebra of essentially finite type over}  $R$ , \underline{where} $R$  \underline{is noetherian, and let}  $E$  \underline{be a flat} $A$-\underline{module. Then we have a canonical isomorphism}

\begin{equation*}
E \underset{A}{\otimes} D^i(A|R, \ M) \ \overset{\sim}{\longrightarrow} \ D^i(A|R, \ E \underset{A}{\otimes} M)
\end{equation*}
\underline{for all}  $i \geq 0$  \underline{and for all} $A$-\underline{modules}  $M$ .

(7) \underline{If}  $R$  \underline{is noetherian and}  $A$  \underline{is an} $R$-\underline{algebra of essentially finite} \underline{type, then}  $D^i(A|R, M)$  \underline{is an} $A$-\underline{module of finite type for all}  $i$ , \underline{provided}  $M$  \underline{is} \underline{an} $A$-\underline{module of finite type}.

(8) \underline{Let}  $P$  \underline{be a polynomial algebra over}  $R$  \underline{and let}  $0 \to I \to P \to A \to 0$ \underline{be exact. Then}  $D^0(A|R, M) = \mathrm{Der}_R(A, M)$  ,

\begin{equation*}
\begin{aligned}
D^1(A|R, \ M) \ &= \ \mathrm{Coker}(\mathrm{Der}_R(P, \ M) \ \to \ \mathrm{Hom}_A(I/I^2, \ M))\\
&= \ \underline{\text{the set of isomorphism classes of}}\\
&\qquad\ \ \text{R-}\underline{\text{algebra extensions of}} \ \ A \ \ \underline{\text{by}} \ \ M \ ,\\
D^2(A|R, \ M) \ &= \ \mathrm{Coker}(H^1(K_I, \ M) \ \to \ \mathrm{Hom}_A(H_1(K_I), \ M)) \ .
\end{aligned}
\end{equation*}

\underline{Proof}:

(1) If  $0 \to M' \to M \to M'' \to 0$  is an exact sequence of $A$-modules, then for any polynomial algebra  $P$  over  $R$  ,  $0 \to \mathrm{Der}_R(P, M') \to \mathrm{Der}_R(P, M) \to \mathrm{Der}_R(P, M'') \to 0$ is exact and hence  $0 \to \mathrm{Der}_R(-, M') \to \mathrm{Der}_R(-, M) \to \mathrm{Der}_R(-, M'') \to 0$  is an exact sequence of sheaves by 3.3(c).

(2) $\mathrm{Der}_S(-, M)$  is an additive sheaf on  $\underline{C}_{A|S}$  , and $\mathrm{Der}_R(B, M) = \mathrm{Ker}(\mathrm{Der}_S(B, M) \to \mathrm{Der}_S(R, M))$  for every  $B \in \mathrm{ob}(\underline{C}_{A|R})$  . Therefore our assertion follows from 3.7(c).

(3) Let  $S : \underline{C}_{A|R} \to \underline{C}_{A \underset{R}{\otimes} S|S}$  be the functor given by  $X \longmapsto X \underset{R}{\otimes} S$  . Then $\widetilde{S}\mathrm{Der}_S(-, M) = \mathrm{Der}_R(-, M)$  and hence our assertion follows from 3.7(a).



(4)  Follows from 3.9. Indeed,  $F = \mathrm{Der}_R(-, N)$  is an additive sheaf on $\underline{C}_{S^{-1}A|R}$  , and  $F_A \in \mathrm{ob}\left(\underline{C}^{\sim}_{S^{-1}A|A}\right)$  is also additive since $F_A(X) = \mathrm{Ker}(F(X) \to F(A)) = \mathrm{Ker}(\mathrm{Der}_R(X, N) \to \mathrm{Der}_R(A, N)) = \mathrm{Der}_A(X, N)$  i.e., $F_A = \mathrm{Der}_A(-, N)$  .

(5)  The first assertion follows from 3.8(a). Now assume that $\mathrm{Tor}^R_i(A, A) = 0$  for all  $i > 0$  and that

\begin{equation*}
\Delta \ : \ \mathrm{Spec}(A) \ \to \ \mathrm{Spec}(A) \underset{\mathrm{Spec}(R)}{\times} \mathrm{Spec}(A)
\end{equation*}
is an open immersion i.e.,  $(A \underset{R}{\otimes} A)_{\varphi^{-1}(\underline{m})}$  $\to A_{\underline{m}}$  is an isomorphism for all maximal ideals  $\underline{m}$  of  $A$  , where  $\varphi : A \underset{R}{\otimes} A \to A$  is the multiplication map. Then the first assertion combined with 3.12(4) entails that the diagonal map

\begin{equation*}
\Delta_{\underline{m}} \ : \ D^i(A|R, \ M)_{\underline{m}} \ \to \ D^i(A|R, \ M)_{\underline{m}} \ \oplus \ D^i(A|R, \ M)_{\underline{m}}
\end{equation*}
is an isomorphism for every maximal ideal  $\underline{m}$  of  $A$  and hence

\begin{equation*}
\Delta \ : \ D^i(A|R, \ M) \ \to \ D^i(A|R, \ M) \ \oplus \ D^i(A|R, \ M)
\end{equation*}
is an isomorphism, which entails that  $D^i(A|R, M) = 0$  for all  $i$  .

(6)  In view of 3.12(4), we may assume that  $A$  is an R-algebra of finite type. Now consider the map

\begin{equation*}
E \underset{A}{\otimes} \mathrm{Der}_R(-, \ M) \ \to \ \mathrm{Der}_R(-, \ E \underset{A}{\otimes} M)
\end{equation*}
in  $\underline{C}^{\sim}_{A|R}$  . Since  $E$  is A-flat, we have an isomorphism

\begin{equation*}
E \underset{A}{\otimes} \mathrm{Der}_R(B, \ M) \ \overset{\sim}{\longrightarrow} \ \mathrm{Der}_R(B, \ E \underset{A}{\otimes} M)
\end{equation*}
whenever  $B \in \mathrm{ob}(\underline{C}_{A|R})$  is of finite type over  $R$  . It follows from 3.3(b) that

\begin{equation*}
D^i(A|R, \ E \underset{A}{\otimes} \mathrm{Der}_R(-, \ M)) \ \to \ D^i(A|R, \ E \underset{A}{\otimes} M)
\end{equation*}
is an isomorphism. On the other hand, the functor  $E \underset{A}{\otimes} -$  :  $(A\text{-mod}) \to (A\text{-mod})$  is exact, and therefore we have

\begin{equation*}
E \underset{A}{\otimes} D^i(A|R, \ M) \ = \ D^i(A|R, \ E \underset{A}{\otimes} \mathrm{Der}_R(-, \ M)) \ \ ,
\end{equation*}
and hence our assertion.

(7)  follows from 3.3(a).




(8)  In view of 3.10 and 3.11, it suffices to show that $\mathrm{Coker}(\mathrm{Der}_R(P, M) \to \mathrm{Hom}_A(I/I^2, M)) = \mathrm{Exalcomm}(A|R, M)$ , where  $\mathrm{Exalcomm}(A|R, M)$ denotes the set of isomorphism classes of R-algebra extensions of  $A$  by  $M$ . Let $0 \to M \to A' \to A \to 0$   be an R-algebra extension of  $A$  by  $M$ . Since  $P$  is a polynomial algebra over  $R$ , we obtain a commutative diagram

\begin{center}
\begin{tikzcd}[column sep=large]
0 \arrow[r] & I \arrow[r] \arrow[d] & P \arrow[r] \arrow[d] & A \arrow[r] \arrow[d, equal] & 0 \\
0 \arrow[r] & M \arrow[r] & A' \arrow[r] & A \arrow[r] & 0
\end{tikzcd}
\end{center}











where  $I \to M$  is uniquely determined by the extension  $A'$  up to  $\mathrm{Der}_R(P, M)$  . We thus obtain a map

\begin{equation*}
\Phi \ : \ \mathrm{Exalcomm}(A|R, M) \to \mathrm{Coker}(\mathrm{Der}_R(P, M) \to \mathrm{Hom}_A(I/I^2, M))  \ .
\end{equation*}
Conversely a P-linear map  $I \to M$  yields an extension by push-out

\begin{center}
\begin{tikzcd}[column sep=large]
0 \arrow[r] & I \arrow[r] \arrow[d] & P \arrow[r] \arrow[d] & A \arrow[r] \arrow[d, equal] & 0 \\
0 \arrow[r] & M \arrow[r] & A' \arrow[r] & A \arrow[r] & 0
\end{tikzcd}
\end{center}










Two P-linear maps  $I \rightrightarrows M$  which differ by  $\mathrm{Der}_R(P, M)$  are trivially seen to yield isomorphic extensions and therefore we obtain a map

\begin{equation*}
\Psi \ : \ \mathrm{Coker}(\mathrm{Der}_R(P, M) \to \mathrm{Hom}_A(I/I^2, M)) \to \mathrm{Exalcomm}(A|R, M)  \ .
\end{equation*}
It is straightforward to verify that  $\Phi$, $\Psi$  are inverse processes to each other.

\underline{Corollary} 3.13.  (a)  The R-\underline{algebra}  $A$  \underline{is formally smooth over}  $R$  \underline{if and only if} $D^1(A|R, M) = 0$  \underline{for every} A-\underline{module}  $M$  .

(b)  \underline{Let}  $R$  \underline{be noetherian and}  $A$  \underline{an} R-\underline{algebra of finite type.} \underline{Then}  $A$ \underline{is a relative complete-intersection over}  $R$  \underline{if and only if}  $D^2(A|R, M) = 0$  \underline{for every} A-\underline{module}  $M$  .

(c)  \underline{Let}  $R$  \underline{be noetherian and}  $A$  \underline{an} R-\underline{algebra of finite type.} \underline{Then for} \underline{any multiplicative subset}  $S$  \underline{in}  $A$  , \underline{we have a canonical isomorphism}

\begin{equation*}
D^i(S^{-1}A|R, \ S^{-1}M) \xrightarrow{\ \sim\ } S^{-1}D^i(A|R, M)  \ \underline{\text{for all}} \ \ i \geq 0  \ .
\end{equation*}



(d)  \underline{Let}  $R$  \underline{be noetherian and}  $A$  \underline{a local} R-\underline{algebra of essentially finite} \underline{type. We denote by}  $\hat{A}$  \underline{the} \underline{m}-\underline{adic completion of}  $A$  \underline{where}  $\underline{m}$ = \underline{the maximal ideal of} $A$  .  \underline{Then for any} A-\underline{module}  $E$  \underline{of finite type we have a canonical isomorphism}

\begin{equation*}
D^1(\hat{A}|R, \ \hat{A} \underset{A}{\otimes} E) \xrightarrow{\ \sim\ } \hat{A} \underset{A}{\otimes} D^1(A|R, E)  \ .
\end{equation*}
\underline{Proof}:  (a)  follows immediately from  $D^1(A|R, M) = \mathrm{Exalcomm}(A|R, M)$ .

(b)  Let  $P$  be a polynomial algebra over  $R$  in a finite number of variables and let  $0 \to I \to P \to A \to 0$  be exact. Localizing if necessary, we may assume that  $I$  is generated by a P-regular sequence which would imply that  $H_1(K_I) = 0$ and therefore  $D^2(A|R, M) = \mathrm{Coker}(H^1(K_I, M) \to \mathrm{Hom}_A(H_1(K_I), M)) = 0$  . Conversely assume that  $D^2(A|R, M) = 0$  for every A-module  $M$  .

Let  $0 \to I \to P \to A \to 0$  be exact where  $P$  is a polynomial algebra over $R$  in a finite number of variables. We have

\begin{equation*}
0 = D^2(A|R, M) = \mathrm{Coker}(H^1(K_I, M) \to \mathrm{Hom}_A(H_1(K_I), M))
\end{equation*}
i.e.,  $H^1(K_I, M) \to \mathrm{Hom}_A(H_1(K_I), M)$  is surjective for every A-module  $M$  . Choose an exact sequence  $0 \to K \to F \to I \to 0$  where  $F$  is a free P-module of finite type. We note that  $H_1(K_I) = K/K_0$  where  $K_0 = \mathrm{Im}(\overset{2}{\wedge} F \to \overset{1}{\wedge} F)$  . The fact that $D^2(A|R, H_1(K_I)) = 0$  i.e.,

\begin{equation*}
H^1(K_I, \ H_1(K_I)) \to \mathrm{Hom}_A(H_1(K_I), \ H_1(K_I))  \ \text{ is surjective}
\end{equation*}
entails that  $0 \to K/K_0 \to F/IF \to I/I^2 \to 0$  is exact and splits as A-modules and in particular  $I/I^2$  is projective as an A-module. Therefore, localizing  $A$  if necessary, we may assume that  $I/I^2$  is  A-free, and that  $F/IF \to I/I^2$  is an isomorphism. Then the fact that  $0 \to K/K_0 \to F/IF \to I/I^2 \to 0$  is exact and splits as A-modules entails that  $H_1(K_I) = K/K_0 = 0$  . This means that  $I$  is generated by a P-regular sequence i.e.,  $A$  is a relative complete intersection over  $R$  .

(c)  follows immediately from 3.12(4) and (6).

(d)  Firstly it follows from 3.12(6) that

\begin{equation*}
D^i(A|R, \ \hat{A}\underset{A}{\otimes}E) \xrightarrow{\ \sim\ } \hat{A}\underset{A}{\otimes}D^i(A|R, E)
\end{equation*}
is an isomorphism for all  $i$  , and therefore it suffices to show that

$D^1(\hat{A}|R,\ \hat{A}\otimes_A E) \to D^1(A|R,\ \hat{A}\otimes_A E)$  is an isomorphism. Our proof is based on the description of  $D^1$  in terms of algebra extensions. Let  $0 \to \hat{A}\otimes_A E \to A' \xrightarrow{\ \varphi\ } \hat{A} \to 0$  be an R-algebra extension whose restriction to $A$ splits. The fact that  $\hat{A}\otimes_A E$  is an $\hat{A}$-module of finite type entails readily that  $A'$  is a local R-algebra, complete with respect to $\underline{m}'$-adic topology where  $\underline{m}'$ = the maximal ideal of  $A'$ . Therefore if there is an R-algebra map  $\psi : A \to A'$  lifting the canonical map $A \to \hat{A}$ , then  $\psi$  extends uniquely to  $\hat{\psi} : \hat{A} \to A'$  such that  $\varphi \circ \hat{\psi} = \mathrm{id}_{\hat{A}}$ . This proves that

\begin{equation*}
D^1(\hat{A}|R,\ \hat{A}\otimes_A E) \to D^1(A|R,\ \hat{A}\otimes_A E)
\end{equation*}
is injective. Now let  $0 \to \hat{A}\otimes_A E \to B \xrightarrow{\ \varphi\ } A \to 0$  be an R-algebra extension. Firstly we claim that the topology on  $\hat{E} = \hat{A}\otimes_A E$  induced from  $\underline{m}_B$-adic topology on  $B$  coincides with the topology on  $\hat{E}$  as $\hat{A}$-module. Indeed, since  $A$  is essentially of finite type over  $R$ , one can find a subalgebra  $B_0$  of  $B$  such that  $B_0$  is a local R-algebra of essentially finite type over  $R$  and that  $\varphi(B_0) = A$ . Set  $E_0 = \hat{E} \cap B_0$  and denote by  $\underline{m}_B$ , $\underline{m}_0$ , $\underline{m}$  the maximal ideals of  $B$ , $B_0$ , $A$  respectively. Then  $\underline{m}_B = \underline{m}_0 + \hat{E}$  and hence  $\underline{m}_B^{n+1} = \underline{m}_0^{n+1} + \underline{m}^n\hat{E}$  for all  $n$ . Since  $B_0$  is noetherian, there exists an integer  $r > 0$  by Artin-Rees Theorem such that

\begin{equation*}
\begin{aligned}
\hat{E} \cap \underline{m}_B^{n+1} &= \underline{m}^n\hat{E} + \hat{E} \cap \underline{m}_0^{n+1} = \underline{m}^n\hat{E} + E_0 \cap \underline{m}_0^{n+1}\\
&= \underline{m}^n\hat{E} + \underline{m}^{n+1-r}(E_0 \cap \underline{m}_0^{\,r}) \subset \underline{m}^{n+1-r}\hat{E}
\end{aligned}
\end{equation*}
for all  $n \geq r$ , which proves our assertion about the two topologies on  $\hat{E}$  . In particular  $\hat{E} = \hat{A}\otimes_A E$  is complete with respect to the topology induced from $\underline{m}_B$-adic topology on  $B$ , and hence we obtain the exact commutative diagram

\begin{center}
\begin{tikzcd}
0 \arrow[r] & \hat{E} \arrow[r] \arrow[d, equal] & B \arrow[r] \arrow[d] & A \arrow[r] \arrow[d] & 0 \\
0 \arrow[r] & \hat{E} \arrow[r] & \hat{B} \arrow[r] & \hat{A} \arrow[r] & 0
\end{tikzcd}
\end{center}












where  $\hat{B}$  stands for  $\underline{m}_B$-adic completion of  $B$  . This proves that
$D^1(\hat{A}|R,\ \hat{E}) \to D^1(A|R,\ \hat{E})$  is surjective and hence we are done.




\underline{Corollary} 3.14. \underline{Let}  $R$  \underline{be noetherian and}  $A$  \underline{an R-algebra of finite type, smooth everywhere except at one closed point}  $x \in \mathrm{Spec}(A)$  . \underline{We then have isomorphisms}

\begin{equation*}
D^1(A|R,\ A) \simeq D^1(A_x|R,\ A_x) \simeq D^1(\hat{A}_x|R,\ \hat{A}_x)\ .
\end{equation*}
\underline{Proof}: Since  $A$  is smooth over  $R$  except at  $x \in \mathrm{Spec}(A)$  ,  $D^1(A|R,\ A)$  is an A-module of finite type with its support on the set  $\{x\}$  , and therefore we have

\begin{equation*}
D^1(A|R,\ A) = D^1(A|R,\ A)_x = \widehat{D^1(A|R,\ A)}_x\ .
\end{equation*}
Therefore our assertion follows from 3.13.

\underline{Remark} 3.15.  Let  $R$  be a topological ring and  $A$  a topological R-algebra. We then define, for any A-module  $E$  ,

\begin{equation*}
D^i_{\mathrm{top}}(A|R,\ E) = \varinjlim_{\alpha} D^i(A_\alpha|R_\alpha,\ A_\alpha \otimes_A E)
\end{equation*}
where  $A_\alpha = A/J_\alpha$ , $R_\alpha = R/I_\alpha$  , and  $J_\alpha$ , $I_\alpha$  are both open in  $A, R$  respectively. Then to say that  $A$  is formally smooth as a topological R-algebra means that  $D^1_{\mathrm{top}}(A|R,\ E) = 0$  for every A-module  $E$  .

        Now let  $X$  be a scheme over a ring  $R$  and  $\underline{E}$  a quasi-coherent  X-module. We then define the sheaves  $\underline{D}^i_{X|R}(\underline{E}) = \underline{D}^i(X|R,\ \underline{E})$  on  $X$  via presheaves on  $X$  given by

\begin{equation*}
[\underline{D}^i_{X|R}(\underline{E})](U) = D^i(\Gamma(U,\ \underline{O}_X)|R,\ \Gamma(U,\ \underline{E}))
\end{equation*}
for every affine open set  $U \subset X$  . If  $R$  is noetherian and  $X$  is of finite type over  $R$  , then the property 3.13(c) shows that  $\underline{D}^i_{X|R}(\underline{E})$  can actually be constructed canonically, as a quasi-coherent X-module.

        In case when there is no possible confusion we shall abbreviate by setting  $\underline{D}^i_{X|R} = \underline{D}^i_{X|R}(\underline{O}_X)$  . All the statements of 3.13 can now be translated in terms of these quasi-coherent sheaves  $\underline{D}^i_{X|R}(\underline{E})$  , which we leave to the readers. We list below a few properties which are most relevant to our purpose.

\underline{Corollary} 3.15. \underline{Let}  $R$  \underline{be noetherian and}  $X$  \underline{an} R-\underline{scheme of finite type. Then}

(a)  \underline{For any coherent} X-\underline{module}  $\underline{E}$ , $\underline{D}^i_{X|R}(\underline{E})$  \underline{is again a coherent} X-\underline{module} \underline{for all}  $i$ , \underline{and furthermore}  $\operatorname{Supp} \underline{D}^i_{X|R}(\underline{E}) \subset X^{\mathrm{Sing}}$  \underline{for all}  $i > 0$  \underline{where} $X^{\mathrm{Sing}} = \{x \in X| X$ \underline{is non-smooth over}  $R$  \underline{at the point}  $x \in X\}$ .

(b)  \underline{If}  $X$  \underline{is flat over}  $R$ , \underline{then for any} R-\underline{algebra}  $S$ , \underline{we have the} \underline{canonical isomorphism}

\begin{equation*}
\underline{D}^i_{X\underset{R}{\otimes}S\,|\,S}(\underline{E}) \overset{\sim}{\to} \underline{D}^i_{X|R}(\underline{E})
\end{equation*}
\underline{for all}  $i$ .

(c)  \underline{If}  $X$  \underline{is a relative complete intersection over}  $R$ , \underline{then for every} \underline{surjective ring homomorphism}  $S \to R$  \underline{we have the exact sequence}

\begin{equation*}
0 \to \underline{D}^1_{X|R}(\underline{E}) \to \underline{D}^1_{X|S}(\underline{E}) \to \underline{\mathrm{Hom}}_{\underline{O}_X}(I/I^2\underset{R}{\otimes}\underline{O}_X, \underline{E}) \to 0
\end{equation*}
\underline{where}  $I = \mathrm{Ker}(S \to R)$ . \underline{If, furthermore,}  $R$  \underline{is local with the residue field}  $k$ \underline{and}  $X$  \underline{is} R-\underline{flat,} \underline{then we have the exact sequence}

\begin{equation*}
0 \to \underline{D}^1_{X_0|k}(\underline{O}_{X_0}) \to \underline{D}^1_{X|S}(\underline{O}_{X_0}) \to D^1(R|S,\ k)\underset{k}{\otimes}\underline{O}_{X_0} \to 0
\end{equation*}
\underline{where}  $X_0 = X\underset{R}{\otimes}k$ .

\underline{Proof}:  (a)  Follows from 3.12(7) and the vanishing for smooth algebras (cf. 3.13(a)), whereas (b) follows from 3.12(3).

(c)  Since  $X$  is a relative complete-intersection over  $R$ , we have $\underline{D}^i_{X|R}(\underline{E}) = 0$  for all  $i \geq 2$  by the complete-intersection vanishing (cf. 3.13(b)) and hence

\begin{equation*}
0 \to \underline{D}^0_{X|R}(\underline{E}) \to \underline{D}^0_{X|S}(\underline{E}) \to \underline{D}^0_{R|S}(\underline{E}) \to \underline{D}^1_{X|R}(\underline{E}) \to \underline{D}^1_{X|S}(\underline{E}) \to \underline{D}^1_{R|S}(\underline{E}) \to 0
\end{equation*}
is exact by 3.12(2), where  $\underline{D}^i_{R|S}(\underline{E})$  are quasi-coherent sheaves of  $X$  defined by

\begin{equation*}
[\underline{D}^i_{R|S}(\underline{E})](U) = D^i(R|S,\ \underline{E}(U))
\end{equation*}
for every affine open subset  $U \subset X$ . In particular,  $\underline{D}^0_{R|S}(\underline{E}) = 0$  since  $S \to R$ is surjective, and

\begin{equation*}
\underline{D}^1_{R|S}(\underline{E}) = \underline{\mathrm{Hom}}_{\underline{O}_X}(I/I^2\underset{R}{\otimes}\underline{O}_X, \underline{E})
\end{equation*}
by 3.12(8), and hence the first exact sequence. If  $X$  is R-flat, we have

$\underline{D}^i_{X_0|k}(\underline{E}) \overset{\sim}{\to} \underline{D}^i_{X|R}(\underline{E})$  for all  $i$  and for every quasi-coherent $X_0$-module  $\underline{E}$  and in particular

\begin{equation*}
\underline{D}^1_{X_0|k}(\underline{O}_{X_0}) \overset{\sim}{\to} \underline{D}^1_{X|R}(\underline{O}_{X_0})
\end{equation*}
from which the second exact sequence follows.

\underline{Remark} 3.16:  The quasi-coherent sheaves  $\underline{D}^i_{X|R}(\underline{E})$  we have defined should appear as  $E_2^{0,i}$  of a spectral sequence relating the local ones and the global ones. L. Illusie has obtained such a theory (Lecture Notes in Mathematics 239). His method is via  "homotopical algebra"  generalizing the methods of M. André and D. Quillen rather than  "cohomological algebra" . It seems that the approach we have taken here can be globalized via Grothendieck cohomology on the category of schemes with an appropriate topology generalizing the one on the affine category.


4.  \underline{Formal moduli of deformations}

One amongst the nice cofibered categories in which the isomorphism classes of objects are usually not prorepresentable, but nevertheless admit a formal versal object is the cofibered category of deformations. We now come back to the situations and notations of paragraph 1. Thus, throughout the section,  $\Lambda$  is a fixed complete local noetherian ring with the residue field  $k$ , and  $\underline{C}_{\Lambda}$  is the category of artinian local $\Lambda$-algebras with the same residue field  $k$ .

Let  $X_0$  be a fixed scheme over the field  $k$ . By an (infinitesimal) deformation of  $X_0$ , we mean a pair  $(R, X)$  where  $R \in \mathrm{ob}(\underline{C}_{\Lambda})$  and  $X$  is a flat R-scheme together with a commutative diagram

\begin{tikzcd}[column sep=huge, row sep=huge]
X_0 \arrow[r, "i_X"] \arrow[d] & X \arrow[d, "\mathrm{flat}"] \\
\mathrm{Spec}(k) \arrow[r] & \mathrm{Spec}(R)
\end{tikzcd}













such that the induced morphism $X_0 \to X \times_{\mathrm{Spec}(R)} \mathrm{Spec}(k)$ is an isomorphism. We note that, since $R$ is an artinian local ring, $i_X : X_0 \to X$ is necessarily a closed immersion which is a homeomorphism on underlying topological spaces. If $(R, X)$ , $(R', X')$ are deformations of $X_0$ to $R, R'$ respectively, we define an arrow $(R', X') \to (R, X)$ to consist of a map $R' \xrightarrow{\ \varphi\ } R$ in $\underline{C}_\Lambda$ and a morphism $\Phi : X \to X'$ of schemes with a commutative diagram

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=large]
X \arrow[rr, "\Phi"] \arrow[ddd] & & X' \arrow[ddd] \\
 & X_0 \arrow[ul, "i_X"'] \arrow[ur, "i_{X'}"] \arrow[d] & \\
 & \mathrm{Spec}(k) \arrow[dl] \arrow[dr] & \\
\mathrm{Spec}(R) \arrow[rr, "\mathrm{Spec}(\varphi)"'] & & \mathrm{Spec}(R')
\end{tikzcd}
\end{center}












We thus obtain the category $\underline{M}_{X_0}$ of (infinitesimal) deformations of $X_0$ in which the objects and the arrows are defined as above. The category $\underline{M}_{X_0}$ is provided with a functor $P : \underline{M}_{X_0} \to \underline{C}_\Lambda$ defined by $(R, X) \to R$ . Now let $(R, X) \in \mathrm{ob}(\underline{M}_{X_0})$ and a map $R \xrightarrow{\ \varphi\ } S$ in $\underline{C}_\Lambda$ be given. We then obtain a commutative diagram

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=huge]
X \times_{\mathrm{Spec}(R)} \mathrm{Spec}(S) \arrow[r, "p_1"] \arrow[d, "\mathrm{flat}"'] & X \arrow[d, "\mathrm{flat}"] \\
\mathrm{Spec}(S) \arrow[r, "\mathrm{Spec}(\varphi)"'] & \mathrm{Spec}(R)
\end{tikzcd}
\end{center}









and $\varphi$-arrow $(\varphi, p_1) : (R, X) \to (S, X \times_{\mathrm{Spec}(R)} \mathrm{Spec}(S))$ is obviously cocartesian in $\underline{M}_{X_0}$ . It follows that the category $\underline{M}_{X_0}$ is a cofibered category over $\underline{C}_\Lambda$ via $P : \underline{M}_{X_0} \to \underline{C}_\Lambda$ . We observe the following facts:




4.1(a): Let $(1_R, \Phi) : (R, X_1) \to (R, X_2)$ be an arrow in $\underline{M}_{X_0}$ i.e., $\Phi : X_2 \to X_1$ is a morphism over $R$ such that $X_2 \otimes_R k \to X_1 \otimes_R k$ is an isomorphism. Since $R$ is artinian and $X_i$ is $R$-flat, it follows immediately that $\Phi$ is an isomorphism so that $(1_R, \Phi) : (R, X_1) \to (R, X_2)$ is an isomorphism in $\underline{M}_{X_0}$ . Consequently, $\underline{M}_{X_0}$ is a cofibered category in groupoids over $\underline{C}_\Lambda$ .

4.1(b): Suppose that $X_0$ is affine, say $X_0 = \mathrm{Spec}(A_0)$ . Then for any object $(R, X) \in \mathrm{ob}(\underline{M}_{X_0})$ , $X$ is also affine. Consequently, for any $R \in \mathrm{ob}(\underline{C}_\Lambda)$ , the category $\underline{M}_{X_0}(R)$ is canonically equivalent, via the sections, to the category in which an object is a flat algebra $A$ over $R$ together with an $R$-algebra map $j_A : A \to A_0$ inducing an isomorphism $A \otimes_R k \xrightarrow{\ \sim\ } A_0$ , and a map $\Phi : A_1 \to A_2$ is an $R$-algebra map with a commutative diagram

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=huge]
A_1 \arrow[r, "\Phi"] \arrow[d, "j_{A_1}"'] & A_2 \arrow[d, "j_{A_2}"] \\
A_0 \arrow[r, equal] & A_0
\end{tikzcd}
\end{center}

4.1(c): Consider the cofibered category $\widehat{\underline{M}}_{X_0}$ in groupoids over $\widehat{\underline{C}}_\Lambda$ . By definition, the category $\widehat{\underline{M}}_{X_0}(R)$ for any $R \in \mathrm{ob}(\widehat{\underline{C}}_\Lambda)$ is canonically equivalent to the category of formal schemes $\mathfrak{X}$ , adic over the formal spectrum $\mathrm{Spf}(R)$ , such that $\mathfrak{X}_n = \mathfrak{X} \otimes_R R/\underline{m}^{n+1}$ is flat over $R/\underline{m}^{n+1}$ for every $n \geq 0$ (or what amounts to the same, if $X_0$ is noetherian, such that $\mathfrak{X}$ is flat over $\mathrm{Spf}(R)$) . Consequently, if $X_0$ is noetherian, $\widehat{\underline{M}}_{X_0}$ is canonically $\widehat{\underline{C}}_\Lambda$-equivalent to the category of deformations of $X_0$ over the objects in $\widehat{\underline{C}}_\Lambda$ , in the sense of formal schemes.

4.1(d): Let $(R, X) \in \mathrm{ob}(\underline{M}_{X_0})$ i.e., we have a commutative diagram

such that  $U_0 \to (X|U_0) \times_{\mathrm{Spec}(R)} \mathrm{Spec}(k) = X \otimes_R k|U_0$  is an isomorphism, so that $(R, X|U_0)$  is a deformation of  $U_0$  to  $R$ . Furthermore, for any arrow $(\varphi, \Phi) : (R, X) \to (R', X')$  in  $\underline{M}_{X_0}$ ,  $(\varphi, \Phi|U_0) : (R, X|U_0) \to (R', X'|U_0)$  is an arrow in  $\underline{M}_{U_0}$ . Consequently we have the restriction functor  $\underline{M}_{X_0} \to \underline{M}_{U_0}$  over $\underline{C}_\Lambda$ . One may also consider a localization as well as a formalization at a point. Namely let  $x_0$  be a fixed point in  $X_0$ . If  $(R, X) \in \mathrm{ob}(\underline{M}_{X_0})$ , then $\mathrm{Spec}(\underline{O}_{X,x_0})$  is a deformation of  $\mathrm{Spec}(\underline{O}_{X_0,x_0})$  to  $R$  and  $\mathrm{Spec}(\hat{\underline{O}}_{X,x_0})$  is a deformation of  $\mathrm{Spec}(\hat{\underline{O}}_{X_0,x_0})$  over  $R$ , where  $\hat{\ }$  stands for the completion with respect to the linear topology given by the powers of the maximal ideal. We thus obtain functors  $\underline{M}_{X_0} \to \underline{M}_{\mathrm{Spec}(\underline{O}_{X_0,x_0})} \to \underline{M}_{\mathrm{Spec}(\hat{\underline{O}}_{X_0,x_0})}$ .

Firstly we establish that  $\underline{M}_{X_0}$  is a homogeneous cofibered category over $\underline{C}_\Lambda$ .

\underline{Lemma} 4.2.  \underline{Consider a diagram}

\begin{center}
\begin{tikzcd}
 & R' \arrow[d] \\
R \arrow[r, "\text{surjective}"'] & \bar{R}
\end{tikzcd}
\end{center}

\underline{in}  $\underline{C}_\Lambda$ , \underline{and let}  $E, E'$  \underline{be flat modules over}  $R, R'$  \underline{respectively. Then for any} $R'$-\underline{homomorphism}  $E' \to \bar{E} = E \otimes_R \bar{R}$ , \underline{the fibre-product}  $E \times_{\bar{E}} E'$  \underline{is flat as} $R \times_{\bar{R}} R'$-\underline{module}




\underline{Proof}:  Let  $0 \to I \to R \to \bar{R} \to 0$  be exact so that  $0 \to I \to R \times_{\bar{R}} R' \to R' \to 0$  is exact. Since  $E$  is $R$-flat,  $0 \to I \otimes_R E \to E \to \bar{E} \to 0$  is exact and hence we obtain the exact sequence

\begin{equation}\tag{*}
0 \to I \otimes_R E \to E \times_{\bar{E}} E' \to E' \to 0 \ .
\end{equation}
Set  $S = R \times_{\bar{R}} R'$ . Since  $I$  is nilpotent,  $E \times_{\bar{E}} E'$  is flat as an $S$-module if and only if  $(E \times_{\bar{E}} E') \otimes_S R'$  is flat as an $R'$-module and  $\mathrm{Tor}_1^S (E \times_{\bar{E}} E', R') = 0$ . However, we note that  $I \otimes_R E = I \otimes_S (E \times_{\bar{E}} E')$  and  $E' = R' \otimes_S (E \times_{\bar{E}} E')$  and therefore the exact sequence (*) can be rewritten as

\begin{equation*}
0 \ \to \ I \otimes_S (E \times_{\bar{E}} E') \ \to \ E \times_{\bar{E}} E' \ \to \ R' \otimes_S (E \times_{\bar{E}} E') \ \to \ 0 \ .
\end{equation*}
This means that  $\mathrm{Tor}_1^S (R', E \times_{\bar{E}} E') = 0$  and  $R' \otimes_S (E \times_{\bar{E}} E') = E'$  is flat as $R'$-module, and therefore  $E \times_{\bar{E}} E'$  is $S$-flat.

\underline{Corollary} 4.3.  \underline{Given a diagram}

\begin{center}
\begin{tikzcd}[column sep=large]
(R,\ X) \arrow[dr, "{(\varphi,\ \Phi)}"'] & & (R',\ X') \arrow[dl, "{(\varphi',\ \Phi')}"] \\
 & (\bar{R},\ \bar{X}) &
\end{tikzcd}
\end{center}








\underline{in}  $\underline{M}_{X_0}$ , \underline{the amalgamated sum}  $X \underset{\bar{X}}{\amalg} X'$  \underline{(in the sense of schemes) is a flat scheme over}  $R \times_{\bar{R}} R'$ , \underline{provided}  $\varphi : R \to \bar{R}$  \underline{is surjective. Consequently,}  $\underline{M}_{X_0}$ \underline{is a homogeneous cofibered category in groupoids over}  $\underline{C}_\Lambda$ .

\underline{Proof}:  For each affine open  $U_0 \subset X_0$ , we have by definition that $X \underset{\bar{X}}{\amalg} X'|U_0 \simeq \mathrm{Spec}(\Gamma(U_0,\ X) \times_{\Gamma(U_0,\bar{X})} \Gamma(U_0,\ X'))$ . Consequently, if  $\varphi : R \to \bar{R}$ is surjective,  $X \underset{\bar{X}}{\amalg} X'$  is a flat scheme over  $R \times_{\bar{R}} R'$  by 4.2, and the morphism $i_X \underset{i_{\bar{X}}}{\amalg} i_{X'} : X_0 \to X \underset{\bar{X}}{\amalg} X'$  induces an isomorphism  $X_0 \to (X \underset{\bar{X}}{\amalg} X') \otimes_S k$ , where $S = R \times_{\bar{R}} R'$ . Therefore  $(R \times_{\bar{R}} R' ,\ X \underset{\bar{X}}{\amalg} X') \in \mathrm{ob}(\underline{M}_{X_0})$  and we obviously have that  $(R \times_{\bar{R}} R',\ X \underset{\bar{X}}{\amalg} X') = (R,\ X) \times_{(\bar{R},\bar{X})} (R',\ X')$  in the category  $\underline{M}_{X_0}$ , which

means that $\underline{M}_{X_0}$ is homogeneous over $\underline{C}_\Lambda$ .

\underline{Lemma} 4.4.  \underline{For any scheme} $X_0$ \underline{over} $k$ , \underline{we have a canonical exact sequence}

\begin{equation*}
0 \;\to\; H^{1}(X_{0},\ \underline{D}^{0}_{X_{0}}) \;\to\; [\underline{M}_{X_{0}}(k[\varepsilon])] \;\to\; H^{0}(X_{0},\ \underline{D}^{1}_{X_{0}})
\end{equation*}
\underline{where} $\underline{D}^{i}_{X_{0}}$ \underline{are as defined in paragraph 3.}

\underline{Proof}:  (Special case)  Assume that $X_{0}$ is affine and let $\Gamma(X_{0},\ \underline{O}_{X_{0}}) = A_{0}$ . Then as it was noted in 4.1(b), the category $\underline{M}_{X_{0}}(k[\varepsilon])$ is canonically equivalent to the category $\underline{E}$ , where

\begin{equation*}
\mathrm{ob}(\underline{E}) : \text{object in } \underline{E} \text{ is a flat algebra } A \text{ over } k[\varepsilon]
\end{equation*}
together with a  $k[\varepsilon]$ -algebra map  $j_{A} : A \to A_{0}$  inducing the isomorphism $k \otimes_{k[\varepsilon]} j_{A} : k \otimes_{k[\varepsilon]} A \overset{\sim}{\longrightarrow} A_{0}$ . Alternatively, an object in $\underline{E}$ is a $k$-algebra $A$  together with an exact sequence  $0 \to A_{0} \overset{\varepsilon}{\longrightarrow} A \overset{j_{A}}{\longrightarrow} A_{0} \to 0$  in which $\varepsilon(A_{0})^{2} = 0$  as an ideal in  $A$ .

F$\ell$($\underline{E}$) :  An arrow  $A_{1} \to A_{2}$  in  $\underline{E}$  with respect to first description of the object in  $\underline{E}$  is a  $k[\varepsilon]$-algebra map  $\Phi : A_{1} \to A_{2}$  such that  $j_{A_{1}} = j_{A_{2}} \circ \Phi$ . Therefore, an arrow  $A_{1} \to A_{2}$  in  $\underline{E}$  with respect to the alternative description of objects in  $\underline{E}$  is a $k$-algebra map  $\Phi : A_{1} \to A_{2}$  yielding a commutative diagram

\begin{center}
\begin{tikzcd}[column sep=large]
0 \arrow[r] & A_{0} \arrow[r, "\varepsilon"] \arrow[d, equal] & A_{1} \arrow[r, "j_{A_{1}}"] \arrow[d, "\Phi"] & A_{0} \arrow[r] \arrow[d, equal] & 0 \\
0 \arrow[r] & A_{0} \arrow[r] & A_{2} \arrow[r, "j_{A_{2}}"] & A_{0} \arrow[r] & 0
\end{tikzcd}\quad .
\end{center}
















It follows that  $[\underline{M}_{X_{0}}(k[\varepsilon])]$  is canonically isomorphic, via  $\Gamma(X_{0},\ -)$ , to the set of isomorphism classes of $k$-algebra extensions of  $A_{0}$  by  $A_{0}$ . In other words, we have a canonical bijection  $[\underline{M}_{X_{0}}(k[\varepsilon])] \overset{\sim}{\longrightarrow} H^{0}(X_{0},\ \underline{D}^{1}_{X_{0}})$  via $\Gamma(X_{0},\ -)$, which is trivially seen to respect the vector space structures on both sides.




(General case)  For each affine open  $U_{0} \subset X_{0}$ , we get a canonical map $[\underline{M}_{X_{0}}(k[\varepsilon])] \to H^{0}(U_{0},\ \underline{D}^{1}_{X_{0}})$  defined as the composite map $[\underline{M}_{X_{0}}(k[\varepsilon])] \to [\underline{M}_{U_{0}}(k[\varepsilon])] \overset{\sim}{\longrightarrow} H^{0}(U_{0},\ \underline{D}^{1}_{X_{0}})$  and hence we obtain a canonical map $[\underline{M}_{X_{0}}(k[\varepsilon])] \to H^{0}(X_{0},\ \underline{D}^{1}_{X_{0}})$ . Its kernel is the set of isomorphism classes of locally-trivial deformations of  $X_{0}$  to  $k[\varepsilon]$ , i.e., the set of isomorphism classes of deformations of  $X_{0}$  to  $k[\varepsilon]$ , locally (on $X$ ) isomorphic to $X_{0} \otimes_{k} k[\varepsilon]$ . Since  $\underline{D}^{0}_{X_{0}} = \underline{\mathrm{Der}}_{k}\,(\underline{O}_{X_{0}},\ \underline{O}_{X_{0}}) = \underline{\mathrm{Aut}}(X_{0} \otimes_{k} k[\varepsilon]|X_{0})$  $=$ the sheaf of germs of automorphisms of  $X_{0} \otimes_{k} k[\varepsilon]$  inducing the identity on the subscheme $X_{0}$ , it is canonically isomorphic to  $H^{1}(X_{0},\ \underline{D}^{0}_{X_{0}})$ , so that we obtain the desired exact sequence.

\underline{Theorem} 4.5.  \underline{Let} $X_{0}$ \underline{be a scheme of finite type over} $k$ \underline{for which either} (i) $X_{0}$ \underline{is proper over} $k$ \underline{or} (ii) $X_{0}$ \underline{is affine but} $X_{0}^{\mathrm{sing}} = \{x \in X_{0}|X_{0}$ \underline{is non-smooth over} $k$ \underline{at the point} $x \}$ \underline{is a finite set. Then}

(a)  $\underline{M}_{X_{0}}$  \underline{admits a formal versal object} (\underline{called a formal versal deformation of}  $X_{0}$ ) \underline{over}  $\underline{C}_{\Lambda}$ . \underline{If}  $(R,\ \mathfrak{X})$  \underline{is a formal versal deformation of}  $X_{0}$ , \underline{then for any} $(S,\ \mathfrak{Y}) \in \mathrm{ob}(\widehat{\underline{M}}_{X_{0}})$ , \underline{there is a map}  $(\varphi,\Phi) : (R,\mathfrak{X}) \to (S,\mathfrak{Y})$  \underline{in}  $\widehat{\underline{M}}_{X_{0}}$  \underline{such that the diagram below is cartesian}

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=large]
\mathfrak{Y} \arrow[r, "\Phi"] \arrow[d] & \mathfrak{X} \arrow[d] \\
\mathrm{Spf}(S) \arrow[r, "\mathrm{Spf}(\varphi)"'] & \mathrm{Spf}(R)
\end{tikzcd}\quad .
\end{center}









\underline{Furthermore a formal versal deformation}  $(R,\mathfrak{X})$  of  $X_{0}$  \underline{prorepresents the functor} $[\underline{M}_{X_{0}}]$  \underline{if and only if, for every surjective map}  $R' \to R$  \underline{in}  $\underline{C}_{\Lambda}$  \underline{and a deformation} $(R',\ X')$  \underline{of}  $X_{0}$  \underline{to}  $R'$ , \underline{the homomorphism}

\begin{equation*}
\mathrm{Aut}_{R'}(X'|X_{0}) \to \mathrm{Aut}_{R}(X' \underset{R'}{\otimes} R|X_{0})
\end{equation*}
\underline{is surjective.}

(b)  \underline{If}  $X_{0}$  \underline{is proper over}  $k$ , \underline{then}  $\underline{M}_{X_{0}}$  \underline{is smoothly pseudo-representable}

\underline{over} $\underline{C}_{\Lambda}$ .

\underline{Proof}:  (a)  Since  $\underline{M}_{X_{0}}$  is a homogeneous cofibered category in groupoids over $\underline{C}_{\Lambda}$ by 4.3, it suffices to see that  $[\underline{M}_{X_{0}}(k[\epsilon])]$  is a finite-dimensional vector space over  $k$  by 1.11 and 2.9(b).

Now consider the exact sequence

\begin{equation}\tag{*}
0 \to H^{1}(X_{0}, \underline{D}^{0}_{X_{0}}) \to [\underline{M}_{X_{0}}(k[\epsilon])] \to H^{0}(X_{0}, \underline{D}^{1}_{X_{0}}) \ .
\end{equation}
If  $X_{0}$  is proper over  $k$  , then  $H^{1}(X_{0}, \underline{D}^{0}_{X_{0}})$  and  $H^{0}(X_{0}, \underline{D}^{1}_{X_{0}})$  are both finite dimensional since  $\underline{D}^{i}_{X_{0}}$  are coherent for all  $i \geq 0$  by 3.15(a). Now assume that $X_{0}$  is affine such that  $X_{0}^{\mathrm{sing}}$  is a finite set. Since  $\underline{D}^{1}_{X_{0}}$  is a coherent sheaf on  $X_{0}$  such that  $\mathrm{Supp}\ \underline{D}^{1}_{X_{0}} \subset X_{0}^{\mathrm{sing}}$  by 3.15(a), we find that  $H^{0}(X_{0}, \underline{D}^{1}_{X_{0}})$  is a finite-dimensional vector space over  $k$  , whereas  $H^{1}(X_{0}, \underline{D}^{0}_{X_{0}}) = 0$  since  $X_{0}$ is affine. Therefore, in either case, it follows from the exact sequence (*) that $[\underline{M}_{X_{0}}(k[\epsilon])]$  is a finite dimensional vector space over  $k$  . The second statement of (a) follows from 2.7.

          (b)  If  $X_{0}$  is proper,  $\mathrm{Aut}\ (X_{0} \otimes_{k} k[\epsilon]|X_{0}) = H^{0}(X_{0}, \underline{D}^{0}_{X_{0}})$  is a finite dimensional vector space and hence our statement follows from 2.13.

\underline{Remark 4.6(a)}:  Let  $X_{0}$  be affine. Then a formal versal deformation of  $X_{0}$ exists if and only if  $\underline{D}^{1}_{X_{0}}$  has its support on a finite number of points. However this does not imply that non-smooth points of  $X_{0}$  are all isolated. There are affine schemes  $X_{0}$  over $k$  having a non-isolated non-smooth point but  $\mathrm{supp}\ \underline{D}^{1}_{X_{0}}$ is a finite set.

\underline{Remark 4.6(b)}:  Henceforth a deformation of  $X_{0}$  is meant by an object in  $\underline{M}_{X_{0}}$  . In case when there is a possible confusion, an object in  $\underline{M}_{X_{0}}$  will be referred as an infinitesimal deformation of  $X_{0}$  .

\underline{Remark 4.6(c)}:  Let  $X_{0}$  be a scheme over  $k$  . We have fixed a complete local noetherian ring  $\Lambda$  with the residue field  $k$  , and considered the deformations

of  $X_{0}$  over the category  $\underline{C}_{\Lambda}$  . (In practice one usually takes  $\Lambda = k$  or  $W(k)$ if  $k$  is a perfect field of positive characteristic). Now  $\underline{C}_{k} \subset \underline{C}_{\Lambda}$  is a fully faithful imbedding, and that  $\underline{M}_{X_{0}}|\underline{C}_{k}$  is simply the category of deformations of $X_{0}$  over  $S$  where  $S \in \mathrm{ob}(\underline{C}_{k})$  . Therefore if  $(R, \mathfrak{X})$  is a formal versal deformation of  $X_{0}$  over  $\underline{C}_{\Lambda}$  , then  $(k \otimes_{\Lambda} R, k \otimes_{\Lambda} \mathfrak{X})$  is a formal versal deformation of $X_{0}$  over  $\underline{C}_{k}$  . It follows, for example, that  $\dim_{\underline{C}_{\Lambda}} \underline{M}_{X_{0}} = \dim k \otimes_{\Lambda} R$  does not depend on the choice of  $\Lambda$  but depends only on  $X_{0}$  .

          One can generalize the above theorem in many ways. Let us for instance consider a pair  $Y_{0} \to X_{0}$  where  $X_{0}$  is a scheme of finite type over  $k$  and  $Y_{0}$ a fixed closed subscheme of  $X_{0}$  . For each  $R \in \mathrm{ob}(\underline{C}_{\Lambda})$  , a deformation of $(X_{0}, Y_{0})$  to  $R$  is meant to be a commutative diagram

\begin{tikzcd}[row sep=large, column sep=huge]
Y_0 \arrow[rrr] \arrow[dr, hook] \arrow[ddr] & & & Y \arrow[dl, hook] \arrow[ddl, "\text{flat}"] \\
 & X_0 \arrow[r] \arrow[d] & X \arrow[d, "\text{flat}"] & \\
 & \mathrm{Spec}(k) \arrow[r] & \mathrm{Spec}(R) &
\end{tikzcd}


















such that  $(X_{0}, Y_{0}) \to (X \times_{\mathrm{Spec}(R)} \mathrm{Spec}(k), Y \times_{\mathrm{Spec}(R)} \mathrm{Spec}(k))$  is an isomorphism. Defining a morphism  $(R'; X', Y') \to (R; X, Y)$  of deformations of  $(X_{0}, Y_{0})$  to be the obvious ones, we obtain the cofibered category  $\underline{M}_{X_{0},Y_{0}}$  in groupoids over $\underline{C}_{\Lambda}$  . (This is a process often used in rigidification of automorphisms in moduli problems of deformations.) One sees immediately, by the same argument as in 4.3 based on 4.2, that  $\underline{M}_{X_{0},Y_{0}}$  is a homogeneous cofibered category in groupoids over $\underline{C}_{\Lambda}$  .

\underline{Lemma} 4.7.  $0 \to H^{0}(Y_{0}, \underline{\mathrm{Hom}}_{\underline{O}_{Y_{0}}} (\underline{I}/\underline{I}^{2}, \underline{O}_{Y_{0}})) \to [\underline{M}_{X_{0},Y_{0}}(k[\epsilon])] \to [\underline{M}_{X_{0}}(k[\epsilon])]$ \underline{is exact, where}  $\underline{I}$  \underline{is the ideal sheaf of}  $\underline{O}_{X_{0}}$  \underline{defining}  $Y_{0}$  i.e. 




\begin{equation*}
 0 \to \underline{I} \to \underline{O}_{X_0} \to \underline{O}_{Y_0} \to 0 \qquad \underline{\text{is exact,}}
\end{equation*}
\underline{Proof}: Let $\underline{B}$ be the full subcategory of $\underline{M}_{X_0,Y_0}(k[\epsilon])$ whose objects are of the form $(k[\epsilon]; X_0 \times_{\mathrm{Spec}(k)} \mathrm{Spec}(k[\epsilon]), Y)$ . We then have $[B] = \mathrm{Ker}\,([\underline{M}_{X_0,Y_0}(k[\epsilon])] \to [\underline{M}_{X_0}(k[\epsilon])]\,)$ . The category $\underline{B}$ is the groupoid of deformations of $Y_0$ to $k[\epsilon]$ "inside $X_0 \times_{\mathrm{Spec}(k)} \mathrm{Spec}(k[\epsilon])$ ", i.e., an object in $\underline{B}$ is a commutative diagram

\begin{center}
\begin{tikzcd}[column sep=large, row sep=large]
Y \arrow[rr, "i_Y"] \arrow[dr, "\text{flat}"'] & & X_0 \times_{\mathrm{Spec}(k)} \mathrm{Spec}(k[\epsilon]) \arrow[dl] \\
 & \mathrm{Spec}(k[\epsilon]) &
\end{tikzcd}
\end{center}










such that $\mathrm{Spec}(k) \times_{\mathrm{Spec}(k[\epsilon])} i_Y = i_{Y_0}$ , and an arrow $(Y_1, i_{Y_1}) \to (Y_2, i_{Y_2})$ is a $k[\epsilon]$-morphism $\Phi : Y_1 \to Y_2$ (necessarily an isomorphism) such that $\mathrm{Spec}(k) \times_{\mathrm{Spec}(k[\epsilon])} \Phi = \mathrm{id}_{Y_0}$ and $i_{Y_2} \circ \Phi = i_{Y_1}$ . Alternatively, an object in $\underline{B}$ is a pair $(Y, j_Y)$ , where $Y$ is a deformation of $Y_0$ to $k[\epsilon]$ and $j_Y : Y \to X_0$ is a morphism over $k$ such that the composite morphism $Y_0 \to Y \xrightarrow{\;j_Y\;} X_0$ is $i_{Y_0}$ , and an arrow $(Y_1, j_{Y_1}) \to (Y_2, j_{Y_2})$ is a morphism $\Phi : Y_1 \to Y_2$ such that $k \otimes_{k[\epsilon]} \Phi = \mathrm{id}_{Y_0}$ and $j_{Y_2} \circ \Phi = j_{Y_1}$ . Therefore the association

$(Y, j_Y) \;\longmapsto\;$
\begin{tikzcd}[column sep=large]
0 \arrow[r] & \underline{I} \arrow[r] \arrow[d] & \underline{O}_{X_0} \arrow[r] \arrow[d, "j_Y"] & \underline{O}_{Y_0} \arrow[r] \arrow[d, equal] & 0 \\
0 \arrow[r] & \underline{O}_{Y_0} \arrow[r, "\epsilon"] & \underline{O}_Y \arrow[r] & \underline{O}_{Y_0} \arrow[r] & 0
\end{tikzcd}















gives rise to an isomorphism

\begin{equation*}
[B] \;\xrightarrow{\;j|\underline{I}\;}\; \mathrm{Hom}_{\underline{O}_{X_0}}(\underline{I},\, \underline{O}_{Y_0}) = \mathrm{Hom}_{\underline{O}_{Y_0}}(\underline{I}/\underline{I}^2,\, \underline{O}_{Y_0}) = H^0(Y_0,\, \underline{\mathrm{Hom}}_{\underline{O}_{Y_0}}(\underline{I}/\underline{I}^2,\, \underline{O}_{Y_0}))\;.
\end{equation*}



\underline{Remark} 4.8.  For a more general formula implying the above lemma, see SGA3 III 4.4. One may also note the following fact. One can define for any $S$-scheme $X$ and a quasi-coherent $X$-module $\underline{E}$ a quasi-coherent $X$-module $\underline{D}^i_{X|S}(\underline{E})$ for all $i \geq 0$ , generalizing the case when $S$ is affine. As usual we simply write $\underline{D}^i_{X|S}(\underline{O}_X) = \underline{D}^i_{X|S}$ . We then have

\begin{equation*}
H^0(Y_0,\, \underline{\mathrm{Hom}}_{Y_0}(\underline{I}/\underline{I}^2,\, \underline{O}_{Y_0})) = H^0(Y_0,\, \underline{D}^1_{Y_0|X_0})
\end{equation*}
where $0 \to \underline{I} \to \underline{O}_{X_0} \to \underline{O}_{Y_0} \to 0$ is exact.

\underline{Theorem} 4.9.  \underline{Let} $X_0$ \underline{be} $k$-\underline{scheme of finite type and} $Y_0$ \underline{a closed subscheme of} $X_0$ . \underline{Assume that either} (i) $X_0$ \underline{is proper over} $k$ \underline{or} (ii) $X_0$ \underline{is affine and smooth over} $k$ \underline{outside a finite number of points and} $Y_0$ \underline{is proper over} $k$ . \underline{We then have}

(a) $\underline{M}_{X_0,\,Y_0}$ \underline{admits a formal versal deformation over} $\underline{C}_\wedge$ , \underline{and it pro-represents the functor} $[\underline{M}_{X_0,\,Y_0}]$ \underline{if and only if, for every surjective map} $R' \to R$ \underline{in} $\underline{C}_\wedge$ \underline{and a deformation} $(R'; X', Y')$ ,

\begin{equation*}
\mathrm{Aut}_{R'}((X', Y')|X_0) \to \mathrm{Aut}_R((X' \otimes_{R'} R,\, Y' \otimes_{R'} R)|X_0)
\end{equation*}
\underline{is surjective.}

(b) \underline{If furthermore} $H^0(X_0,\, \underline{D}^0_{Y_0|k} \times_{\underline{D}^0_{X_0|k}(\underline{O}_{Y_0})} \underline{D}^0_{X_0|k})$ \underline{is finite dimensional,} \underline{then} $\underline{M}_{X_0,\,Y_0}$ \underline{is smoothly pseudo-representable.}

\underline{Proof}: It is obvious from 4.4 and 4.6 together with 1.11, 2.7, and 2.13.

We now consider the passage to localization and completion in the deformation theory     of schemes. First, some notation: Let $X_0$ be a $k$-scheme of finite type. Given a fixed point $x_0 \in X_0$ , we have natural functors

\begin{equation*}
\underline{M}_{X_0} \to \underline{M}_{\mathrm{Spec}(\underline{O}_{X_0,\, x_0})} \to \underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,\, x_0})} 
\end{equation*}



 and in turn we obtain the functors

\begin{equation*}
\widehat{\underline{M}}_{X_0} \to \widehat{\underline{M}}_{\mathrm{Spec}(\underline{O}_{X_0,\ x_0})} \to \widehat{\underline{M}}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,\ x_0})}\ .
\end{equation*}
As was remarked in 4.1(c), $\widehat{\underline{M}}_{X_0}$  is canonically equivalent to the category in which an object is a pair  $(R,\ \mathfrak{X})$  where  $R \in \mathrm{ob}(\widehat{\underline{C}}_{\Lambda})$  and  $\mathfrak{X}$  is a flat $R$-adic formal scheme together with a fixed isomorphism  $\mathfrak{X}_0 \longleftrightarrow X_0$ . Henceforth we shall denote, when there is no possible confusion, the images of  $(R,\ \mathfrak{X})$  under $\widehat{\underline{M}}_{X_0} \to \widehat{\underline{M}}_{\mathrm{Spec}(\underline{O}_{X_0,\ x_0})}$  and  $\widehat{\underline{M}}_{X_0} \to \widehat{\underline{M}}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,\ x_0})}$  by  $(R,\ \mathfrak{X}_{(x_0)})$  and  $(R,\ \mathfrak{X}_{(\hat{x}_0)})$ respectively. Therefore if  $\mathfrak{X} = \varinjlim\limits_{\nu} \mathfrak{X}_{\nu}$  where  $\mathfrak{X}_{\nu} = \mathfrak{X} \underset{\mathrm{Spf}(R)}{\times} \mathrm{Spec}(R/\underline{m}^{\nu+1})$    then

\begin{equation*}
\mathfrak{X}_{(x_0)} = \varinjlim\limits_{\nu} \mathrm{Spec}(\underline{O}_{\mathfrak{X}_{\nu},\ x_0})
\end{equation*}
\begin{equation*}
\mathfrak{X}_{(\hat{x}_0)} = \varinjlim\limits_{\nu} \mathrm{Spec}(\widehat{\underline{O}}_{\mathfrak{X}_{\nu},\ x_0})\ .
\end{equation*}
\underline{Theorem} 4.10. \underline{Let}  $X_0$  \underline{be an affine scheme of finite type over}  $k$  .

(a)  \underline{If}  $X_0$  \underline{is locally a complete-intersection, then}  $\underline{M}_{X_0}$  \underline{is smooth over}  $\underline{C}_{\Lambda}$  .

(b)  \underline{Assume that, for a fixed closed point}  $x \in X_0$  ,  $X_0 - \{x\}$  \underline{is smooth over}  $k$  . \underline{Then}

\begin{equation*}
\underline{M}_{X_0} \to \underline{M}_{\mathrm{Spec}(\underline{O}_{X_0,\ x})} \to \underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,\ x})}
\end{equation*}
\underline{are both minimally smooth functors. In particular, if}  $(R,\ \mathfrak{X})$  \underline{is a formal versal deformation of}  $X_0$  , \underline{then}  $(R,\ \mathfrak{X}_{(x)})$  \underline{and}  $(R,\ \mathfrak{X}_{(\hat{x})})$  \underline{are formal versal deformations of}  $\mathrm{Spec}(\underline{O}_{X_0,\ x})$  \underline{and}  $\mathrm{Spec}(\widehat{\underline{O}}_{X_0,\ x})$  \underline{respectively}.

\underline{Proof}:  In this proof we go back to the notations of the cohomology of commutative algebras defined in paragraph 3. We set  $X_0 = \mathrm{Spec}(A_0)$




(a)  It suffices to show that  $P : [\underline{M}_{X_0}] \to \underline{C}_{\Lambda}$  is smooth.

Let  $(R,\ \mathrm{Spec}(A))$  be a deformation of  $\mathrm{Spec}(A_0)$  to  $R$  , where  $R \in \mathrm{ob}(\underline{C}_{\Lambda})$  . Given a small extension  $R' \to R$  in  $\underline{C}_{\Lambda}$  (i.e.,  $0 \to k \to R' \to R \to 0$  is exact), we must show that  $(R,\ \mathrm{Spec}(A))$  can be lifted to  $R'$  . The exact sequence for  $D^i$  with coefficients in  $A_0$  applied to the ring homomorphisms  $R' \to R \to A$  gives us the exact sequence

\begin{equation*}
\ldots \to D^1(A|R,\ A_0) \to D^1(A|R',\ A_0) \to D^1(R|R',\ k) \underset{k}{\otimes} A_0 \to D^2(A|R,\ A_0) \to \ldots
\end{equation*}
Since  $R' \to R$  is a small extension, $D^1(R|R',\ k)$  is a 1-dimensional vector space over  $k$  generated by the element (denoted by  $[R']$) represented by the extension $0 \to k \to R' \to R \to 0$  . On the other hand,  $A$  is $R$-flat and hence $D^i(A|R,\ A_0) = D^i(A_0|k,A_0)$  for all  $i > 0$  and in particular  $D^2(A|R,\ A_0) = 0$ by 3.12(8) since  $A_0$  is locally a complete-intersection. Consequently we get the exact sequence

\begin{equation*}
\to D^1(A_0|k,\ A_0) \to D^1(A|R',\ A_0) \to D^1(R|R',\ k) \underset{k}{\otimes} A_0 \to 0
\end{equation*}
This means that there exists an $R'$-algebra extension of  $A$  by  $A_0$  , denoted by $A'$  , such that  $[A'] \to [R'] \otimes 1$  under the map  $D^1(A|R',\ A_0) \to D^1(R|R',\ k) \underset{k}{\otimes} A_0$  , which means that the deformation  $(R,\ \mathrm{Spec}(A))$  can be lifted to a deformation $(R',\ \mathrm{Spec}(A'))$  .

(b)  By 3.14 we have the isomorphisms

\begin{equation*}
D^1(A_0|k,\ A_0) \simeq D^1((A_0)_x|k,\ (A_0)_x) \simeq D^1(\widehat{(A_0)_x}|k,\ \widehat{(A_0)_x})
\end{equation*}
i.e.,   $[\underline{M}_{X_0}(k[\epsilon])] \simeq [\underline{M}_{\mathrm{Spec}(\underline{O}_{X_0,\ x})}(k[\epsilon])] \simeq [\underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,\ x})}(k[\epsilon])]$ .

It suffices to show, by 2.7(a), that

\begin{equation*}
[\underline{M}_{X_0}] \to [\underline{M}_{\mathrm{Spec}(\underline{O}_{X_0,\ x})}] \to [\underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,\ x})}]
\end{equation*}
are both smooth functors. Let  $(R,\ \mathrm{Spec}(A))$  be a deformation of  $X_0 = \mathrm{Spec}(A_0)$  , and let  $0 \to k \to R' \to R \to 0$  be a small extension in  $\underline{C}_{\Lambda}$  . As above, the ring homomorphisms  $R' \to R \to A$  give us the exact commutative diagram

{\small

\begin{tikzcd}[column sep=small, row sep=large]
{} \arrow[r] & D^1(A_0|k,A_0) \arrow[r] \arrow[d, "\approx"'] & D^1(A|R',A_0) \arrow[r, "p"] \arrow[d] & D^1(R|R',k)\underset{k}{\otimes}A_0 \arrow[r] \arrow[d] & D^2(A_0|k,A_0) \arrow[r] \arrow[d, "\approx"] & \dots \\
{} \arrow[r] & D^1(A_0|k,(A_0)_x) \arrow[r] & D^1(A|R',(A_0)_x) \arrow[r] & D^1(R|R',k)\underset{k}{\otimes}(A_0)_x \arrow[r] & D^2(A_0|k,(A_0)_x) \arrow[r] & \dots \\
{} \arrow[r] & D^1((A_0)_x|k,(A_0)_x) \arrow[r] \arrow[u] & D^1(A_x|R',(A_0)_x) \arrow[r, "p_x"] \arrow[u] & D^1(R|R',k)\underset{k}{\otimes}(A_0)_x \arrow[r] \arrow[u] & D^2((A_0)_x|k,(A_0)_x) \arrow[r] \arrow[u] & \dots
\end{tikzcd}
\]}























where the indicated isomorphisms come from the fact that  $A_0$  is smooth over  $k$  except at one closed point  $x$  so that

$$D^i(A_0|k,\ (A_0)_x) = D^i(A_0|k,\ A_0)_x = D^i(A_0|k,\ A_0)$$
for all  $i > 0$ . Now suppose that we are given an arrow $(R',\ \mathrm{Spec}(B)) \to (R,\ \mathrm{Spec}(A_x))$  in  $[\underline{M}_{\mathrm{Spec}((A_0)_x)}]$ . It means that we are given a class $[B] \in D^1(A_x|R',\ (A_0)_x)$  such that  $p_x([B]) = [R']$ . Then a diagram chase shows that there exists $[A'] \in D^1(A|R',\ A_0)$  such that $p([A']) = [R']$  and  $A'_x = B$  i.e.,  $(R',\ \mathrm{Spec}(A'))$  is a deformation of  $\mathrm{Spec}(A_0)$ to  $R'$  such that  $\mathrm{Spec}(A')_x = \mathrm{Spec}(B)$ . This proves that $\underline{M}_{X_0} \to \underline{M}_{\mathrm{Spec}(\underline{O}_{X_0,\ x})}$ is smooth. The smoothness of the functor  $\underline{M}_{\mathrm{Spec}((A_0)_x)} \to \underline{M}_{\mathrm{Spec}(\widehat{(A_0)_x})}$ comes from the similar diagram together with the fact that

$$D^i((A_0)_x|k,\ \widehat{(A_0)_x}) = \widehat{D^i((A_0)_x|k,\ (A_0)_x)} = D^i((A_0)_x|k,\ (A_0)_x)$$
for all  $i > 0$  since  $x$  is the only possible non-smooth point.

\underline{Theorem} 4.11.  \underline{Let}  $X_0$  \underline{be a} (\underline{separated}) $k$-\underline{scheme of finite type, smooth outside a finite closed set}  $X_0^{\mathrm{Sing}} = \{x_1,\dots,x_r\}$  \underline{of}  $X_0$ . \underline{Let}  $U_0^1,\dots,U_0^r$  \underline{be affine open neighbourhoods of}  $x_1,\dots,x_r$  \underline{such that}  $U_0^i \cap X_0^{\mathrm{Sing}} = \{x_i\}$ . \underline{If} $H^2(X_0,\ \underline{D}^0_{X_0}) = 0$ , \underline{then the natural functor}  $\underline{M}_{X_0} \to \underline{M}_{U_0^1} \times\dots\times \underline{M}_{U_0^r}$   \underline{is smooth.}

\underline{Proof}: We can complete  $U_0^1, \dots ,U_0^r$  into an affine open covering of  $X_0$  by choosing $U_0^{r+1},\dots,U_0^N$  such that   $U_0^j \cap X_0^{\mathrm{Sing}} = \emptyset$  for all  $j > r$ . Now let $R' \to R$  be a small extension in  $\underline{C}_{\Lambda}$ , and let  $(R',\ U'^1),\dots,(R',\ U'^r)$  be deformations of  $U_0^1,\dots,U_0^r$  to  $R'$  such that  $U'^i \underset{R'}{\otimes} R = X|U_0^i$ ,  $1 \le i \le r$ , for

some deformation  $(R,\ X)$  of  $X_0$  to  $R$ . We must show that there exists a deformation  $(R',\ X')$  of  $X_0$  to  $R'$  such that  $X' \underset{R'}{\otimes} R = X$  and  $X'|U_0^i = U'^i$  for $1 \le i \le r$ . Since  $U_0^j$  for  $j > r$  is smooth over  $k$ ,  $X|U_0^j$  can be lifted, by 4.9(a), to a deformation  $(R',\ U'^j)$  i.e., there exist deformations  $(R',\ U'^j)$ of  $U_0^j$  to  $R'$  such that  $U'^j \underset{R'}{\otimes} R = X|U_0^j$  for all  $j > r$ . Since, for any pair $i \ne j$ ,  $U_0^i \cap U_0^j$  is affine and smooth over  $k$ , we obtain an isomorphism

$$\tau_{ij} : U'^i|U_0^i \cap U_0^j \xrightarrow{\ \sim\ } U'^j|U_0^i \cap U_0^j$$
such that  $\tau_{ij} \underset{R'}{\otimes} R = \mathrm{id}_{X|U_0^i \cap U_0^j}$ , and in turn defines a cohomology class in $H^2(X_0,\ \underline{D}^0_{X_0})$  given by  $U_0^i \cap U_0^j \cap U_0^k \to \tau_{ij}\tau_{jk}\tau_{ik}^{\ -1}$ . Since  $H^2(X_0,\ \underline{D}^0_{X_0}) = 0$  by hypothesis, the obstruction for glueing these to obtain a global deformation vanishes, and hence we get a deformation  $(R',\ X')$  of  $X_0$  to  $R'$  such that $X' \underset{R'}{\otimes} R = X$  and  $X'|U_0^j \simeq U'^j$ . This completes our proof.

\underline{Remark} 4.12.  The previous proof assumes  $X_0$  to be separated, which is unnecessary. In fact, for a fixed deformation  $(R,\ X)$  of  $X_0$  and deformations  $(R',\ U'^j)$  of $U_0^j$ , the deformations  $(R',\ V')$  of open set  $V$  of  $X$  to  $R'$  compatible with the deformation  $(R',\ U'^j)$  already given, form a  "gerbe"  (in Giraud's terminology) whose structure sheaf is  $\underline{D}^0_{X_0}$ . Hence the obstruction to the existence of a section of this  "gerbe"  (i.e., a global deformation  $(R',\ X')$  of  $X$  compatible with the given datum  $(R',\ U'^j))$  is in $H^2(X_0,\ \underline{D}^0_{X_0})$  which is zero by assumption.

\underline{Corollary} 4.13.  \underline{Let}  $X_0$  \underline{be a} $k$-\underline{scheme of finite type, smooth outside a finite subset}  $X_0^{\mathrm{Sing}} = \{x_1,\dots,x_r\}$  of  $X_0$  \underline{such that}  $H^2(X_0,\ \underline{D}^0_{X_0}) = 0$ . \underline{Then}

$$\text{(a)}\quad \underline{M}_{X_0} \to \underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,x_1})} \times\dots\times \underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,x_r})}\quad \underline{\text{is smooth.}}$$
$$\underline{\text{In particular,}}\ \ \dim \underline{M}_{X_0} = \dim H^1(X_0,\ \underline{D}^0_{X_0}) + \sum_{c=1}^{r} \ \dim \underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,x_c})}\ .$$
(b)  \underline{If furthermore}  $X_0$  \underline{is locally a complete-intersection, then}  $\underline{M}_{X_0}$ \underline{is smooth.}



\underline{Proof}:

(a)  The first statement follows from 4.10 and 4.9(b). Now let  $(R, \mathfrak{X})$  and  $(R_1, \mathfrak{X}_1),...,(R_r, \mathfrak{X}_r)$  be formal versal deformations of  $X_0$  and  $\mathrm{Spec}(\underline{O}_{X_0,x_1}),...,\mathrm{Spec}(\underline{O}_{X_0,x_r})$  respectively. We then obtain a commutative diagram

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=huge]
\underline{h}_R \arrow[r] \arrow[d] & \underline{h}_{R_1 \widehat{\otimes}_\Lambda ... \widehat{\otimes}_\Lambda R_r} \arrow[d] \\
\underline{M}_{X_0} \arrow[r] & \underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,x_1})} \times ... \times \underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,x_r})}
\end{tikzcd}
\end{center}















Since the composite functor

\begin{equation*}
\underline{h}_R \to \underline{M}_{X_0} \to \underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,x_1})} \times ... \times \underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,x_r})}
\end{equation*}
is smooth whereas

\begin{equation*}
\underline{h}_{R_1 \widehat{\otimes}_\Lambda ... \widehat{\otimes}_\Lambda R_r} \to \underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,x_1})} \times .... \times \underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,x_r})}
\end{equation*}
is minimally smooth, it follows from 2.7(a) that

$\underline{h}_R \to \underline{h}_{R_1 \widehat{\otimes}_\Lambda ... \widehat{\otimes}_\Lambda R_r}$   is smooth i.e.,  $R$  is a formal power-series ring over  $R_1 \widehat{\otimes}_\Lambda ... \widehat{\otimes}_\Lambda R_r$ . Since

\begin{equation*}
0 \to H^1(X_0,\underline{D}^0_{X_0}) \to [\underline{M}_{X_0}(k[\epsilon])] \to [\underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,x_1})}(k[\epsilon])] \times ... \times [\underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,x_r})}(k[\epsilon])]
\end{equation*}
is exact by 4.4 i.e.,

\begin{equation*}
0 \to H^1(X_0, \underline{D}^0_{X_0}) \to \mathrm{Hom}_{\Lambda-\mathrm{alg}}(R, k[\epsilon]) \to \mathrm{Hom}_{\Lambda-\mathrm{alg}}(R_1 \widehat{\otimes}_\Lambda ... \widehat{\otimes}_\Lambda R_r, k[\epsilon])
\end{equation*}
is exact, it follows that  $R$  is a formal power-series ring over    $R_1 \widehat{\otimes}_\Lambda ... \widehat{\otimes}_\Lambda R_r$ in $d$-variables where  $d = \dim_k H^1(X_0, \underline{D}^0_{X_0})$  .

Therefore

\begin{equation*}

\dim \underline{M}_{X_0} &= \dim k \otimes_\Lambda R = d + \dim k \otimes_\Lambda (R_1 \widehat{\otimes}_\Lambda ... \widehat{\otimes}_\Lambda R_r) \\
&= d + \dim(k \otimes_\Lambda R_1) \widehat{\otimes}_k ... \widehat{\otimes}_k (k \otimes_\Lambda R_r) \\
&= d + \sum_{i=1}^{r} \dim k \otimes_\Lambda R_i = d + \sum_{i=1}^{r} \dim \underline{M}_{\mathrm{Spec}(\widehat{\underline{O}}_{X_0,x_i})}

\end{equation*}



(b)  follows from 4.10 and 4.9(a).

4.14.    We close this paragraph with an explicit construction of a formal versal deformation in a simple situation. In fact, if  $X_0$  is affine and is a complete-intersection, it is trivial to write down explicitly. Thus let

\begin{equation*}
A_0 = k[x_1,...,x_n]/(f_1,...,f_r) = S/J
\end{equation*}
where  $S = k[x_1,...,x_n]$  ,  $J = (f_1,...,f_r)$  , and  $f_1,...,f_r$  is an $S$-regular sequence. We then obtain the exact sequence

\begin{equation*}
... \to \mathrm{Der}_k(S, A_0) \to \mathrm{Hom}_{A_0}(J/J^2, A_0) \to D^1(A_0|k, A_0) \to 0
\end{equation*}
We note that  $J/J^2$  is  $A_0$-free module of rank  $r$  generated by $f_1(\mathrm{mod}\ J^2),...,f_r(\mathrm{mod}\ J^2)$  , since  $f_1,...,f_r$  is an $S$-regular sequence. We now assume that  $D^1(A_0|k, A_0)$  is a finite-dimensional vector space over  $k$  , say  $A_0$ has isolated non-smooth points only. Let  $d = \dim_k D^1(A_0|k, A_0)$  and choose $p_j : J/J^2 \to A_0$   $(j = 1, 2,...,d)$  which form a $k$-basis of  $D^1(A_0|k, A_0)$  . Now choose  $P_{jk} \in \Lambda[x_1,...,x_n]$  such that  $p_j(f_i) = P_{ji}$  (mod $\underline{m}_\Lambda + J$)  where  $\underline{m}_\Lambda$  is the maximal ideal of  $\Lambda$  . We then consider

\begin{equation*}

\begin{equation*}
\mathrm{Hom}_{\Lambda-\mathrm{alg}}(R, k[\epsilon]) \to D^1(A_0|k, A_0) = [\underline{M}_{\mathrm{Spec}(A_0)}(k[\epsilon])]
\end{equation*}
is bijective by our construction of  $B$  . Therefore, if we set

\begin{equation*}
 \mathrm{Spf}(B) \;=\; \varinjlim_{v}\; \mathrm{Spec}(R/\underline{m}^{v+1}\ \underset{R}{\otimes}\ B)
\end{equation*}
then  $(R,\ \mathrm{Spf}(B))$  is an object in  $\widehat{\underline{M}}_{\mathrm{Spec}(A_0)}$  and the functor  $\underline{h}_R \to \underline{M}_{\mathrm{Spec}(A_0)}$  induced by  $(R,\ \mathrm{Spf}(B))$  is smooth by 1.6, since  $R$  is a formal power-series ring over  $\Lambda$  . In other words,  $(R,\ \mathrm{Spf}(B))$  is a formal versal object of  $\underline{M}_{\mathrm{Spec}(A_0)}$  .

We note, by 4.10(b), that if we set

\begin{equation*}
B = R[[X_1,\ldots,X_n]]/(G_1,\ldots,G_r)\ \ ,
\end{equation*}
then  $(R,\ \mathrm{Spf}(B))$  is a formal versal deformation of  $\mathrm{Spec}(A_0)$  where  $A_0 = k[[X_1,\ldots,X_n]]/(f_1,\ldots,f_r)$  .

\underline{Remark} 4.15.  Let  $X_0$  be a $k$-scheme of finite type with isolated non-smooth points only, and let  $(R,\ \mathfrak{X})$  be a formal versal deformation of  $X_0$  . The above construction shows that if  $X_0$  is affine and locally a complete-intersection, then  $\mathfrak{X}$  is a formalization of an $R$-scheme of finite type. This fact can easily be generalized to the case when  $X_0$  is not necessarily affine but  $H^2(X_0,\ \underline{D}^0_{X_0}) = 0$  .

\underline{Remark} 4.16.  The \underline{global}  theory of the relative cotangent complex (the latter theory being reduced to the truncated complex of length 1 , which is sufficient however for many purposes of deformation theory) allows to generalize and simplify certain results, such as 4.10. Namely let  $S$  be a scheme,  $S_0 \subset S' \subset S$  two subschemes of  $S$  defined by ideals  $J \supset I$  such that  $JI = 0$  ,  $X'$  a scheme flat over  $S'$  ,  $L. = L^{X_0/S_0}$  the relative cotangent complex of  $X_0$  over  $S_0$  , which is an element of the derived category  $D(X_0,\ \underline{O}_{X_0})$  . We consider the category  $\underline{F}$  of all flat schemes  $X$  over  $S$  which extend  $X'/S'$  , i.e. together with an  $S'$-isomorphism  $X \underset{S}{\times} S' \simeq X'$  . Then

(a)  For an object  $X$  of  $\underline{F}$  , the group of automorphisms is canonically isomorphic to  $\mathrm{Ext}^0(X_0;\ L.,I_{X_0})$  (where  $I_{X_0}$  is the inverse image of  $I$  , viewed as a module on  $S_0$  , on  $X_0)$  .




(b)  The set of isomorphism classes of objects of  $\underline{F}$  is empty or a torsor (= a principal homogeneous space) under the group  $\mathrm{Ext}^1(X_0;\ L.,I_{X_0})$  .

(c)  One can define a canonical element  $c \in \mathrm{Ext}^2(X_0;\ L.,I_{X_0})$  whose vanishing is necessary and sufficient for  $\underline{F}$  to be non empty.

In order to study the  $\mathrm{Ext}^i(X_0;\ L.,I_{X_0})$  , it is often convenient to write

\begin{equation*}
\mathrm{Ext}^i(X_0;L.,I_{X_0}) = H^i(X_0,\ \underline{RHom}(L.,I_{X_0}))\ \ .
\end{equation*}
and to notice that the complex  $\underline{RHom}(L.,I_{X_0})$  has as cohomology sheaves the sheaves  $\underline{D}^i_{X_0}(I_{X_0})$  introduced in §3. For  $i = 0, 1, 2$,  these sheaves may be viewed respectively as the sheaf of automorphisms of any object  $X$  of  $\underline{F}$  (understood:  automorphisms inducing the identity on  $X')$  , the sheaf of indeterminacy of isomorphism classes of local solutions to the flat deformation problem, and the sheaf of obstructions to the existence of local solutions. On the other hand, the standard spectral sequence gives us

\begin{equation*}
\mathrm{Ext}^*(X_0;\ L.,I_{X_0}) \leftarrow E_2^{p,q} = H^p(X_0,\ \underline{D}^q_{X_0}(I_{X_0}))\ \ ,
\end{equation*}
which yields the well-known isomorphism

\begin{equation*}
\mathrm{Aut}(X/X') \simeq H^0(X_0,\underline{D}^0_{X_0}(I_{X_0})) \simeq H^0(X_0,\underline{Hom}(\underline{\Omega}^1_{X_0/S_0},I_{X_0})) = \mathrm{Hom}(\underline{\Omega}^1_{X_0/S_0},I_{X_0})\ \ ,
\end{equation*}
and the exact sequence in low degrees

\begin{equation*}
0 - H^1(X_0,\underline{D}^0_{X_0}) - \mathrm{Ext}^1 - H^0(X_0,\underline{D}^1_{X_0}) - H^2(X_0,\underline{D}^0_{X_0}) - \mathrm{Ext}^2
\end{equation*}
This shows in particular that if  $H^2(X_0,\underline{D}^0_{X_0}) = 0$  , and if there exists any local flat deformation  $X$  of  $X'/S'$  , then there exists a flat global deformation which corresponds to given local deformations. More precisely and generally, for given local deformations (i.e. a section of the  "sheaf of isomorphism classes of local flat deformations" ), the argument 4.10 shows that the obstruction to finding a global flat deformation compatible with these is in  $H^2(X_0,\ \underline{D}^0_{X_0})$  , hence such a global flat deformation exists if  $H^2(X_0,\ \underline{D}^0_{X_0}) = 0$  : this is essentially 4.10.




On the other hand, the spectral sequence shows that the  $\mathrm{Ext}^2$  is zero whenever we have the relations

\begin{equation}\tag{*}
H^0(X_0,\ \underline{D}^2_{X_0}\ ) = 0 \quad ,\quad H^1(X_0,\ \underline{D}^1_{X_0}\ ) = 0 \quad ,\quad H^2(X_0,\ \underline{D}^0_{X_0}\ ) = 0 \quad .
\end{equation}
The first relation is always satisfied if  $X_0$  is a relative complete intersection over  $S_0$  (as then  $\underline{D}^2_{X_0} = 0$  for any module  $M$  on  $X_0$ ), the second is satisfied provided the support of  $\underline{D}^1_{X_0}$  is discrete, as is the case if  $X_0$  is smooth over  $S_0$  except on a discrete subset of  $X_0$  over  $S_0$ . When the previous three relations $(*)$ are all satisfied, then by (c) above,  $\underline{F}$  is non empty, which generalizes 4.13(b).

More geometrically, and without using the global theory of the relative cotangent complex (but only the globalizing of the functors  $\underline{D}^i_{X_0}$  ), one can get a simple geometric interpretation of the three successive obstructions to deforming flatly  $X'$  to  $X$ , lying in the three left hand terms of $(*)$. Namely by the local theory, the first obstruction  $c_1$  in  $H^0(X_0,\ \underline{D}^2_{X_0})$  can be defined as the obstruction to finding local solutions, when this obstruction vanishes, the sheaf  $\underline{F}$  of isomorphism classes of local solutions of the problem is (by the local theory) in a canonical way a torsor under  $\underline{D}^1_{X_0}$ , and the second obstruction  $c_2$ , lying in  $H^1(X_0,\ \underline{D}^1_{X_0})$ , is the obstruction to finding a section of this torsor, i.e. of finding a  "coherent system of isomorphism classes of local solutions" ; if this second obstruction also vanishes, then, choosing arbitrarily a section of  $\underline{F}$ , one gets, as noted above, an obstruction  $c_3$  in  $H^2(X_0,\ \underline{D}^0_{X_0})$  to finding a global solution corresponding to the given system of (isomorphism classes of) local solutions. Using the fact that the section of  $\underline{F}$  is determined up to adding a section of  $\underline{D}^1_{X_0}$ , we get a map  $d : H^0(X_0,\ \underline{D}^1_{X_0}) \to H^2(X_0,\ \underline{D}^0_{X_0})$ , and a solution to the deformation problem exists if and only if  $c_1 = 0$ ,  $c_2 = 0$ , and  $c_3$  is zero as an element of Coker $d$  (each  $c_i$  being defined when the previous ones are zero). Of course, the groups  $H^0(X_0,\ \underline{D}^2_{X_0})$ ,  $H^1(X_0,\ \underline{D}^1_{X_0})$  and

$H^2(X_0,\ \underline{D}^0_{X_0})/\mathrm{Im}\ d$  are just the initial terms  $E_2^{0,2}$ ,  $E_2^{1,1}$ , and  $E_3^{2,0}$  of the spectral sequence above,  $d$  being the differential (up to sign ?)

\begin{equation*}
d_2 : E_2^{0,1} \to E_2^{2,0} \quad .
\end{equation*}

5.  \underline{Formal Jacobian subschemes}

Let  $X_0$  be a scheme of finite type over a field  $k$ , and let  $(R,\ \mathfrak{X})$  be a formal versal deformation of  $X_0$ . Then  $\mathfrak{X}$  is not an ordinary scheme over  $R$  but an $R$-adic formal scheme. The purpose of this section is to clarify  "the non-smooth locus of  $\mathfrak{X}$  over  $R$ ".

We first recall the definition of Fitting ideals associated to a module of finite type: Let  $A$  be a commutative ring and  $E$  an $A$-module of finite type. Choose a presentation

\begin{equation*}
K \to F \to E \to 0
\end{equation*}
where  $F$  is locally-free of constant rank  $n$ . We define

\begin{equation*}
I^p_A(E) = \mathrm{Im}(\overset{n-p}{\wedge} K \otimes \overset{n-p}{\wedge} F^* \to A) \qquad \text{for}\quad p = 0,\ 1,\ 2,\ \ldots
\end{equation*}
The ideals  $I^p_A(E)$  thus defined do not depend on the choice of a presentation and therefore are invariants of the $A$-module  $E$ , called the Fitting ideals of the $A$-module  $E$ . The following properties readily follow from the definition.

5.1.    (a) For any ring homomorphism  $A \to B$ , the canonical map

\begin{equation*}
B \underset{A}{\otimes} A/I^p_A(E) \overset{\sim}{\to} B/I^p_B(B \underset{A}{\otimes} E)
\end{equation*}
is an isomorphism for all  $p$ . In particular we have

\begin{equation*}
I^p_{S^{-1}A}(S^{-1}E) = S^{-1}I^p_A(E)
\end{equation*}
for any multiplicative subset  $S$  in  $A$ .




(b)  We have  $I_A^0(E) \subset I_A^1(E) \subset I_A^2(E) \subset \ \dots$ , and, for each point $x \in \operatorname{Spec}(A)$ , $I_A^p(E)_x = A_x$  for all  $p \geq \dim_{\varkappa(x)} E(x)$ , where  $E(x) = \varkappa(x) \underset{A}{\otimes} E$ .

(c)  $x \in \operatorname{Spec}(A) - \operatorname{Supp} A/I_A^p(E)$  if and only if, for any (or for some) presentation

\begin{equation*}
K \to F \to E \to 0
\end{equation*}
where  $F \approx A^n$ , $K_x$  contains  $A_x^{n-p}$  which is isomorphic to a direct summand of $F_x$ . In particular, we have that

\begin{equation*}
\operatorname{Supp} A/I_A^0(E) = \operatorname{Supp} E \ .
\end{equation*}
(d)

\begin{equation*}
I_A^r(E_1 \oplus E_2) = \sum_{p+q=r} \ I_A^p(E_1) \cdot I_A^q(E_2)
\end{equation*}
(e)  If  $A$  is a noetherian adic ring, then

\begin{equation*}
A/I_A^p(E) = \varprojlim_{\nu} A_\nu \big/ I_{A_\nu}^p (E_\nu)
\end{equation*}
where  $A = \varprojlim_{\nu} A_\nu$  and  $E_\nu = E \underset{A}{\otimes} A_\nu$ .

In view of the property 5.1(a), our definition of Fitting ideals is readily globalized. Thus let  $X$  be any scheme, and  $\underline{E}$  a quasi-coherent $X$-module of finite presentation. We then obtain a sequence of quasi-coherent ideal sheaves $\underline{I}_X^p(\underline{E})$  for  $p \geq 0$  defined by

\begin{equation*}
\Gamma(U, \ \underline{I}_X^p(\underline{E})) \xrightarrow{\sim} I^p_{\Gamma(U, \ \underline{O}_X)}(\Gamma(U, \ \underline{E}))
\end{equation*}
for every affine open subset  $U \subset X$ .

Now let  $X \to Y$  be a morphism of schemes. The relative module of Kähler differentials $\underline{\Omega}_{X|Y}(= \underline{\Omega}^1_{X|Y})$  is a quasi-coherent $X$-module. If the morphism  $X \to Y$  is of essentially finite presentation, then  $\underline{\Omega}_{X|Y}$  is a quasi-coherent $X$-module of finite presentation, and in turn we may consider the ideal sheaves  $\underline{I}_X^p(\underline{\Omega}_{X|Y})$  .

\underline{Definition} 5.2.  \underline{Let}  $X \to Y$  \underline{be a morphism of essentially finite presentation.} \underline{For each integer}  $p \geq 0$ , \underline{we define}  $J_X^p(X|Y)$  \underline{to be the closed subscheme of}  $X$

\underline{defined by the ideal sheaf}  $\underline{I}_X^p(X|Y) = \underline{I}_X^p(\underline{\Omega}_{X|Y})$ , \underline{called the Jacobian subschemes} \underline{of}  $X$  \underline{over}  $Y$ . \underline{For each point}  $x \in X$ , \underline{we set}  $X_x = \operatorname{Spec}(\underline{O}_{X,x})$ .

\underline{Theorem} 5.3.  \underline{Let}  $X \to Y$  \underline{be a morphism of essentially finite presentation. Then}

(1)  \underline{For any base change}  $Y \leftarrow Y'$ , \underline{the canonical map} $J^p_{X'}(X'|Y') \xrightarrow{\sim} J^p_X(X|Y) \underset{Y}{\times} Y'$  \underline{is an isomorphism for all}  $p$  \underline{where}  $X' = X \underset{Y}{\times} Y'$ .

(2)  \underline{For each point}  $x \in X$ , \underline{we have the canonical isomorphism} $J^p_{X_x}(X_x|Y) \xrightarrow{\sim} J^p_X(X|Y)_x$ .

(3)  $J^0_X(X|Y) \supset J^1_X(X|Y) \supset J^2_X(X|Y) \supset \dots,$  \underline{and}  $x \notin J^p_X(X|Y)$  \underline{for all} $p \geq \dim_{\varkappa(x)} \Omega_{X|Y}(x)$ .

(4)  $x \notin J^p_X(X|Y)$  \underline{if and only if there exists an open neighbourhood}  $U$ \underline{of}  $x$  \underline{which admits a closed immersion into a}  $Y$-\underline{scheme}  $U'$  \underline{such that}  $U'$  \underline{is} \underline{smooth over}  $Y$  at  $x'$  \underline{and}  $\dim_{x'} U'_{f(x)} = p$  \underline{where}  $x'$  \underline{is the image of}  $x$  \underline{under} $U \to U'$ .

\begin{equation*}
(5) \quad \underline{I}^r_{X_1 \underset{Y}{\times} X_2}(X_1 \underset{Y}{\times} X_2 | Y) = \sum_{p+q=r} \ \pi_1^* \underline{I}^p_{X_1}(X_1|Y) \cdot \pi_2^* \underline{I}^q_{X_2}(X_2|Y)
\end{equation*}
\underline{where}  $\pi_i : X_1 \underset{Y}{\times} X_2 \to X_i$  \underline{is the projection}.

\underline{Proof}:  (3) follows from 5.1(b) whereas (1) follows from 5.1(a) together with the fact that  $P^*\underline{\Omega}_{X|Y} \xrightarrow{\sim} \underline{\Omega}_{X'|Y'}$  is an isomorphism where  $P : X \underset{Y}{\times} Y' \to X$  is the projection. (2) also follows from 5.1(a) since  $\underline{O}_{X,x} \underset{\underline{O}_X}{\otimes} \underline{\Omega}_{X|Y} \xrightarrow{\sim} \underline{\Omega}_{X_x|Y}$  is an isomorphism. (5) follows from 5.1(d) and the isomorphism

\begin{equation*}
\pi_1^*\underline{\Omega}_{X_1|Y} \oplus \pi_2^*\underline{\Omega}_{X_2|Y} \xrightarrow{\sim} \underline{\Omega}_{X_1 \underset{Y}{\times} X_2|Y}
\end{equation*}
(4)  Assume the existence of a diagram

\begin{tikzcd}[column sep=huge, row sep=huge]
U \arrow[r, "i"] \arrow[d, "f"'] & U' \arrow[dl] \\
Y &
\end{tikzcd}












where $U'$ is smooth over $Y$ at $x' = i(x)$ and $\dim_{x'}U'_{f(x)} = p$ . Then $\dim_{\varkappa(x')}\underline{\Omega}_{U'|Y}(x') = p$ and $i^{*}\underline{\Omega}_{U'|Y} \to \underline{\Omega}_{U|Y} \to 0$ is exact, so that $\dim_{\varkappa(x)}\underline{\Omega}_{U|Y}(x) \leq p$ which implies that $x \notin J^{p}_{U}(U|Y)$ by 5.3(3). Since $J^{p}_{U}(U|Y) = J^{p}_{X}(X|Y)|U$ , this means that $x \notin J^{p}_{X}(X|Y)$ . Now assume conversely that $x \notin J^{p}_{X}(X|Y)$ .

The question being local, we may assume that $X, Y$ are both affine, say $X = \mathrm{Spec}(B)$ , $Y = \mathrm{Spec}(A)$ . Choose a presentation over $A$

\begin{equation*}
0 \to J \to P \to B \to 0
\end{equation*}
where $P = A[x_1,\ldots,x_n]$ . Then $J/J^{2} \overset{d}{\to} B \underset{P}{\otimes} \Omega_{P|A} \to \Omega_{B|A} \to 0$ is exact and $B \underset{P}{\otimes} \Omega_{P|A}$ is $B$-free of rank $n$ , and therefore $I^{p}_{B}(\Omega_{B|A}) = \mathrm{Im}(\overset{n-p}{\wedge}J/J^{2} \underset{B}{\otimes} (B \underset{P}{\otimes} \overset{n-p}{\wedge}\Omega_{P|A})^{*} \to B)$ . Therefore, $x \notin J^{p}_{X}(X|Y)$ $\Leftrightarrow$ there exists $f_1,\ldots,f_{n-p}$ in $J$ such that $\left[\det\left(\dfrac{\partial f_i}{\partial x_j}\right)\right](x) \neq 0$ for some choice of $n-p$ variables among $x_1, x_2,\ldots,x_n$   there exists $f_1, f_2,\ldots,f_{n-p}$ in $J$ such that $\mathrm{Spec}(P/(f_1,\ldots,f_{n-p})) \to \mathrm{Spec}(A)$ is smooth at $x'$ where $x'$ is the image of $x$ under $\mathrm{Spec}(B) \to \mathrm{Spec}(P/(f_1,\ldots,f_{n-p}))$ . Thus it suffices to take $U' = \mathrm{Spec}(P/(f_1,\ldots,f_{n-p}))$ .

The following is a generalization of the usual Jacobian criteria for relative situation.

\underline{Theorem} 5.4.   \underline{Let} $X \overset{f}{\to} Y$ \underline{be a morphism of essentially finite presentation. Assume that there exists a fixed integer} $n \geq 0$ \underline{with either conditions:}

(1)  $f$  \underline{is flat and} $\dim_{x}X_{f(x)} = n$ \underline{for every point} $x \in X$ .

(2)  $f$  \underline{is a relative complete-intersection with virtual dimension} $n$ (SGA6 VIII 1.9).

\underline{Then} $x \notin J^{n}_{X}(X|Y)$ \underline{if and only if} $f$ \underline{is smooth at} $x$ .

\underline{Proof:}  We have, by 5.3(4) that $x \notin J^{n}_{X}(X|Y)$ if and only if there exists a diagram

\begin{tikzcd}
U \arrow[r, hook, "i"] \arrow[d, "f"'] & U' \arrow[dl, "f'"] \\
Y &
\end{tikzcd}








such that $f'$ is smooth at $x'$ and $\dim_{x'}U'_{f(x)} = n$ , where $i$ is a closed immersion and $x' = i(x)$ . Thus it suffices to show that either conditions (1) or (2) entails the isomorphism of $i$ at the point $x$ . Set $A = \underline{O}_{Y,f(x)}$ , $B' = O_{U',x'}$ , $B = O_{U,x}$ and let

\begin{equation*}
0 \to I \to B' \to B \to 0
\end{equation*}
be exact. We must show that $I = 0$ . Assume (1). Since $B$ is $A$-flat,

\begin{equation*}
0 \to I/\underline{m}I \to B'/\underline{m}B' \to B/\underline{m}B \to 0
\end{equation*}
is exact where $\underline{m}$ is the maximal ideal of $A$ . By hypothesis, $\dim_{x}U_{f(x)} = \dim_{x'}U'_{f(x)}$ so that $\dim B'/\underline{m}B' = \dim B/\underline{m}B$ . However $B'/\underline{m}B'$ is a regular local ring and therefore it entails that $I/\underline{m}I = 0$ so that $I = 0$ . Now assume (2), and consider the exact sequence

\begin{equation*}
I/I^{2} \overset{d}{\to} B \underset{B'}{\otimes} \Omega_{B'|A} \to \Omega_{B|A} \to 0
\end{equation*}
Since $X$ is a relative complete-intersection over $Y$ and $U' \to Y$ is smooth at $x$ , it follows that $d : I/I^{2} \to B \underset{B'}{\otimes} \Omega_{B'|A}$ is injective at $x$ and $I/I^{2}$ and $B \underset{B'}{\otimes} \Omega_{B'|A}$ are both free at $x$ . Therefore by the definition of virtual dimension of relative complete-intersection we must have that

\begin{equation*}
n = \dim_{\varkappa(x)}\Omega_{B'|A}(x') - \dim_{\varkappa(x)}I/I^{2}(x) = n - \dim_{\varkappa(x)}I/I^{2}(x)
\end{equation*}
i.e., $I/I^{2} = 0$ i.e., $I = 0$ .

\underline{Definition} 5.5.   \underline{Let} $X \overset{f}{\to} Y$ \underline{be a morphism of essentially finite presentation.} \underline{In case when there exists a fixed integer} $n$ \underline{with the property} (1) \underline{or} (2) \underline{in} 5.4,

\underline{we set}  $\underline{I}_X(X|Y) = \underline{I}^n_X(X|Y)$  \underline{and}  $J_X(X|Y) = J^n_X(X|Y)$ .

We can extend this notion to formal schemes in an obvious manner.

Thus let $\mathfrak{X}$ be a noetherian formal scheme and $\underline{E}$ a coherent $\mathfrak{X}$-module. Then we can define the ideal sheaf $\underline{I}^p_{\mathfrak{X}}(\underline{E})$ by setting

\begin{equation*}
\underline{I}^p_{\mathfrak{X}}(\underline{E})(U) \;=\; I^p_{\mathfrak{X}(U)}(\underline{E}(U))
\end{equation*}
for every affine open $U \subset \mathfrak{X}$ . If $\mathfrak{X} = \varinjlim_{v} X_v$ , then $\underline{E} = \varprojlim_{v} \underline{E}_v$ where $\underline{E}_v = \underline{E} \otimes_{\underline{O}_{\mathfrak{X}}} \underline{O}_{X_v}$ and it follows from the fact that $\mathfrak{X}$ is noetherian that

\begin{equation*}
\underline{I}^p_{\mathfrak{X}}(\underline{E}) \;=\; \varprojlim_{v} \underline{I}^p_{X_v}(\underline{E}_v)
\end{equation*}
Now let $S$ be a noetherian formal scheme and $\mathfrak{X}$ an $S$-adic formal scheme of essentially finite type. Let $\underline{I}_{\mathfrak{X}}$ be the ideal sheaf defining the closed immersion $\Delta : \mathfrak{X} \to \mathfrak{X} \underset{S}{\times} \mathfrak{X}$ (= the fibre-product in the category of formal schemes) i.e.,

\begin{equation*}
0 \to \underline{I}_{\mathfrak{X}} \to \underline{O}_{\mathfrak{X} \underset{S}{\times} \mathfrak{X}} \to \underline{O}_{\mathfrak{X}} \to 0
\end{equation*}
is exact. We define $\underline{\Omega}_{\mathfrak{X}|S} = \underline{I}_{\mathfrak{X}}/I^2_{\mathfrak{X}}$ . Since $\mathfrak{X}$ is an $S$-adic formal scheme of essentially finite type, it follows that $\mathfrak{X} = \varinjlim_{v} X_v$ where $X_v = \mathfrak{X} \underset{S}{\times} S_v$ , and hence $\underline{\Omega}_{\mathfrak{X}|S} \simeq \varprojlim_{v} \underline{\Omega}_{X_v|S_v}$ is a coherent $\mathfrak{X}$-module. We note that for any formal $S$-scheme $S'$ of finite type, we have a canonical isomorphism

\begin{equation*}
\underline{\Omega}_{\mathfrak{X} \underset{S}{\times} S'|S'} \;\simeq\; \underline{O}_{S'} \otimes_{\underline{O}_S} \underline{\Omega}_{\mathfrak{X}|S} \quad .
\end{equation*}
\underline{Definition} 5.6. \underline{Let} $S$ \underline{be a noetherian formal scheme and} $\mathfrak{X}$ \underline{an} $S$-\underline{adic formal scheme of essentially finite type. We define the ideal sheaf} $\underline{I}^p_{\mathfrak{X}}(\mathfrak{X}|S)$ \underline{by}

\begin{equation*}
\underline{I}^p_{\mathfrak{X}}(\mathfrak{X}|S) \;=\; \underline{I}^p_{\mathfrak{X}}(\underline{\Omega}_{\mathfrak{X}|S})
\end{equation*}
\underline{and we set} $J^p_{\mathfrak{X}}(\mathfrak{X}|S)$ \underline{the formal closed subscheme of} $\mathfrak{X}$ \underline{defined by} $\underline{I}^p_{\mathfrak{X}}(\mathfrak{X}|S)$ .

Since $\Omega_{\mathfrak{X}|S} = \varprojlim_{n} \Omega_{X_n|S_n}$ we have 




\begin{equation*}
 I^p_{\mathfrak{X}}(\mathfrak{X}|S) \;=\; \varprojlim_{n} I^p_{X_n}(X_n|S_n)
\end{equation*}
\begin{equation*}
J^p_{\mathfrak{X}}(\mathfrak{X}|S) \;=\; \varinjlim_{n} J^p_{X_n}(X_n|S_n) \quad .
\end{equation*}
$\mathfrak{X}_{(x)}$ is an $S$-adic formal scheme of essentially finite type and we have a commutative diagram

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=large]
\mathfrak{X}_{(\widehat{x})} \arrow[rr, "i_{(\widehat{x})}"] \arrow[dr] & & \mathfrak{X} \\
& \mathfrak{X}_{(x)} \arrow[ur, "i_{(x)}"'] &
\end{tikzcd}
\end{center}












We note that if $x$ is an isolated point of $\mathfrak{X}$ , then $i_{(x)}$ , $i_{(\widehat{x})}$ are both isomorphisms to the connected component of $\mathfrak{X}$ containing the point $x$ .

In particular, if $|\mathfrak{X}| = \{x_1,\dots,x_m\}$ is a finite discrete space, then we have a canonical identification $\mathfrak{X} = \coprod_{1 \leq i \leq m} \mathfrak{X}_{(x_i)}$ (disjoint union).

\underline{Corollary} 5.7. \underline{Let} $S$ \underline{be a noetherian formal scheme, and} $\mathfrak{X}$ \underline{an} $S$-\underline{adic formal scheme of essentially finite type. We then have}

(1) $J^p_{\mathfrak{X}}(\mathfrak{X}|S)$ \underline{commutes with base change} i.e., $J^p_{\mathfrak{X}'}(\mathfrak{X}'|S') = J^p_{\mathfrak{X}}(\mathfrak{X}|S) \underset{S}{\times} S'$ \underline{where} $\mathfrak{X}' = \mathfrak{X} \underset{S}{\times} S'$ .

(2) \underline{The connected components of} $J^p_{\mathfrak{X}}(\mathfrak{X}|S)$ \underline{are in bijective correspondence with those of} $J^p_{X_0}(X_0|S_0)$ . \underline{For each point} $x \in |J^p_{X_0}(X_0|S_0)|$ \underline{we have a canonical isomorphism} $J^p_{\mathfrak{X}}(\mathfrak{X}|S)_{(x)} \simeq J^p_{\mathfrak{X}_{(x)}}(\mathfrak{X}_{(x)}|S)$ . \underline{In particular if}

\begin{equation*}
|J^p_{X_0}(X_0|S_0)| \;=\; \{x_1,\dots,x_m\}
\end{equation*}
\underline{is discrete, then}

\begin{equation*}
J^p_{\mathfrak{X}}(\mathfrak{X}|S) \;=\; \coprod_{1 \leq i \leq m} J^p_{\mathfrak{X}_{(x_i)}}(\mathfrak{X}_{(x_i)}|S)
\end{equation*}
\underline{(disjoint union)}.




(3) \underline{Let} $S$ \underline{be an ordinary noetherian scheme and} $X$ \underline{an} $S$-\underline{scheme of essentially finite type. Given a closed subscheme} $S_0 \subset S$ , \underline{let} $\widehat{S}$ \underline{be the formal completion of} $S$ \underline{along} $S_0$ .

\underline{If we set}

\begin{equation*}
\widehat{X} \;=\; X \underset{S}{\times} \widehat{S} \;=\; \underline{\text{the formal completion of}}\;\; X \;\; \underline{\text{along}} \;\; X_0 \;=\; X \underset{S}{\times} S_0 \;\;,\;\; \underline{\text{then}}
\end{equation*}
\begin{equation*}
J^{p}_{\widehat{X}}(\widehat{X}|\widehat{S}) \;=\; J^{p}_{X}(X|S) \underset{S}{\times} \widehat{S} \;=\; \underline{\text{the formal completion of}} \;\; J^{p}_{X}(X|S) \;\; \underline{\text{along}} \;\; J^{p}_{X_0}(X_0|S_0) \;\;.
\end{equation*}
(4) \underline{If there exists a fixed integer} $n \geq 0$ \underline{with the property} 5.4(1) \underline{or} (2) \underline{for} $X_\nu \to S_\nu$ \underline{for all} $\nu$ , \underline{then} $x \notin J^{n}_{\mathfrak{X}}(\mathfrak{X}|S)$ \underline{if and only if} $\mathfrak{X}$ \underline{is formally smooth over} $S$ \underline{at} $x$ .

\underline{Proof}: (1) follows from $\underline{\Omega}_{\mathfrak{X}'|S'} \simeq \underline{O}_{S'} \widehat{\otimes}_{\underline{O}_S} \underline{\Omega}_{\mathfrak{X}|S}$ whereas (2) follows from

\begin{equation*}
\underline{O}_{\mathfrak{X}_{(x)}} \;\widehat{\otimes}_{\underline{O}_{\mathfrak{X}}}\; \underline{\Omega}_{\mathfrak{X}|S} \;\simeq\; \underline{\Omega}_{\mathfrak{X}_{(x)}|S} \;\;.
\end{equation*}
\begin{equation*}
(3)\quad J^{p}_{\widehat{X}}(\widehat{X}|\widehat{S}) \;=\; \varinjlim_{\nu} \; J^{p}_{X \underset{S}{\times} S_\nu}\!\left(X \underset{S}{\times} S_\nu \,\middle|\, S_\nu\right) \;=\; \varinjlim_{\nu} \; J^{p}_{X}(X|S) \underset{S}{\times} S_\nu \;=\; J^{p}_{X}(X|S) \underset{S}{\times} \widehat{S} \;\;.
\end{equation*}
\begin{multline*}
(4)\quad \text{Since } \mathfrak{X} \text{ is an S-adic formal scheme, } \mathfrak{X} \to S \text{ is formally smooth at}\\ x \Leftrightarrow X_\nu \to S_\nu \text{ is formally smooth at } x \text{ for all } \nu \;\Leftrightarrow\; x \notin J^{n}_{X_\nu}(X_\nu|S_\nu) \text{ for all } \nu\\ \Leftrightarrow\; x \notin \varinjlim_{\nu} J^{n}_{X_\nu}(X_\nu|S_\nu) \;=\; J^{n}_{\mathfrak{X}}(\mathfrak{X}|S) \;\;.
\end{multline*}
\underline{Remark} 5.8. Let $\mathfrak{X}$ be an $S$-adic formal scheme of essentially finite type. Given a point $x \in \mathfrak{X}$ we also consider the $S$-adic formal scheme $\mathfrak{X}_{(\hat{x})} = \varinjlim_{\nu} \mathrm{Spec}\big(\widehat{\underline{O}_{X_\nu,x}}\big)$ . We thus have the natural morphisms $\mathfrak{X}_{(\hat{x})} \to \mathfrak{X}_{(x)} \to \mathfrak{X}$ . Now $\widehat{\underline{O}_{X_0,x}}$ is in general not essentially finite type over $S_{(y)}$ where $y$ = the image of $x$ under $\mathfrak{X} \to S$ . For simplicity, let us set $A_\nu = \underline{O}_{X_\nu,x}$ , $R_\nu = \underline{O}_{S_\nu,y}$ . Now the natural map $\Omega_{A_\nu|R_\nu} \to \Omega_{\widehat{A}_\nu|R_\nu}$ induces an isomorphism $\widehat{\Omega_{A_\nu|R_\nu}} \to \widehat{\Omega_{\widehat{A}_\nu|R_\nu}}$ , and therefore $\varprojlim_{\nu} \widehat{\Omega_{A_\nu|R_\nu}} \;\xrightarrow{\;\sim\;}\; \varprojlim_{\nu} \widehat{\Omega_{\widehat{A}_\nu|R_\nu}}$ where $\widehat{\phantom{xx}}$ stands for the separated completion of a module with respect to the topology induced from the ring. Therefore if we define $\widehat{\Omega_{\mathfrak{X}_{(\hat{x})}|S}} = \varprojlim_{\nu} \widehat{\Omega_{\widehat{\underline{O}}_{X_\nu,x}|\underline{O}_{S_\nu,y}}}$ , then $\widehat{\Omega_{\mathfrak{X}_{(\hat{x})}|S}}$ is a coherent $\mathfrak{X}_{(\hat{x})}$-module. Thus if

we set $J^{p}_{\mathfrak{X}_{(\hat{x})}}(\mathfrak{X}_{(\hat{x})}|S)$ to be the formal closed subscheme of $\mathfrak{X}_{(\hat{x})}$ defined by the ideal sheaf $\underline{I}^{p}_{\mathfrak{X}_{(\hat{x})}}(\mathfrak{X}_{(\hat{x})}|S) = \underline{I}^{p}_{\mathfrak{X}_{(\hat{x})}}(\widehat{\Omega}_{\mathfrak{X}_{(\hat{x})}|S})$ , then we have

\begin{equation*}
J^{p}_{\mathfrak{X}_{(x)}}(\mathfrak{X}_{(x)}|S)_{(\hat{x})} \;\simeq\; J^{p}_{\mathfrak{X}_{(\hat{x})}}(\mathfrak{X}_{(\hat{x})}|S) \;\;.
\end{equation*}
We note that if $x$ is an isolated point of $J^{p}_{\mathfrak{X}}(\mathfrak{X}|S)$ , then $J^{p}_{\mathfrak{X}_{(\hat{x})}}(\mathfrak{X}_{(\hat{x})}|S) \to J^{p}_{\mathfrak{X}_{(x)}}(\mathfrak{X}_{(x)}|S)$ is an isomorphism.

To consider the "image" of $J^{p}_{\mathfrak{X}}(\mathfrak{X}|S)$ under the morphism $\mathfrak{X} \xrightarrow{\,f\,} S$ , one may simply take the formal subscheme of $S$ defined by the ideal sheaf $\mathrm{Ker}(\underline{O}_S \to \underline{O}_{\mathfrak{X}}/\underline{I}^{p}_{\mathfrak{X}}(\mathfrak{X}|S))$ . However, it is more convenient for our purpose to use the Fitting ideal again.

\underline{Definition} 5.9. \underline{Let} $S$ \underline{be a noetherian formal scheme and} $f : \mathfrak{X} \to S$ \underline{an} $S$-\underline{adic formal scheme of essentially finite type. Assume that} $J^{p}_{\mathfrak{X}}(\mathfrak{X}|S)$ \underline{is proper over} $S$ , \underline{so that} $f_{*}\underline{O}_{J^{p}_{\mathfrak{X}}(\mathfrak{X}|S)}$ \underline{is a coherent} $\underline{O}_S$-\underline{module. We then define the ideal sheaf} $\underline{I}^{p}_{S}(\mathfrak{X}|S)$ \underline{of} $\underline{O}_S$ \underline{by}

\begin{equation*}
\underline{I}^{p}_{S}(\mathfrak{X}|S) \;=\; \underline{I}^{0}_{S}\big(f_{*}\underline{O}_{J^{p}_{\mathfrak{X}}(\mathfrak{X}|S)}\big)
\end{equation*}
\underline{and set} $J^{p}_{S}(\mathfrak{X}|S)$ \underline{to be the closed formal subscheme of} $S$ \underline{defined by the ideal sheaf} $\underline{I}^{p}_{S}(\mathfrak{X}|S)$ . \underline{In case when there exists a fixed integer} $n$ \underline{having the property} (1) \underline{or} (2) \underline{in} 5.4 \underline{for} $X_\nu \to S_\nu$ \underline{for all} $\nu$ , \underline{we set}

\begin{equation*}
\underline{I}_{\mathfrak{X}}(\mathfrak{X}|S) \;=\; \underline{I}^{n}_{\mathfrak{X}}(\mathfrak{X}|S) \;\;,\qquad J_{\mathfrak{X}}(\mathfrak{X}|S) \;=\; J^{n}_{\mathfrak{X}}(\mathfrak{X}|S)
\end{equation*}
\begin{equation*}
\underline{I}_{S}(\mathfrak{X}|S) \;=\; \underline{I}^{n}_{S}(\mathfrak{X}|S) \;\;,\qquad J_{S}(\mathfrak{X}|S) \;=\; J^{n}_{S}(\mathfrak{X}|S)
\end{equation*}
\underline{Corollary} 5.10. \underline{Let} $S$ \underline{be a noetherian formal scheme and} $\mathfrak{X} \xrightarrow{\,f\,} S$ \underline{an} $S$-\underline{adic formal scheme, essentially of finite type such that} $J^{p}_{\mathfrak{X}}(\mathfrak{X}|S)$ \underline{is proper over} $S$ . \underline{Then}

\begin{equation*}
(1)\quad \big|J^{p}_{S}(\mathfrak{X}|S)\big| \;=\; \underline{\text{the image of}} \;\; \big|J^{p}_{\mathfrak{X}}(\mathfrak{X}|S)\big| \;\; \underline{\text{under}} \;\; f : \mathfrak{X} \to S \;\;.
\end{equation*}



(2)  $J^p_S(\mathfrak{X}|S)$  \underline{commutes with base change}  i.e.,  $J^p_{S'}(\mathfrak{X}'|S') = J^p_S(\mathfrak{X}|S) \times_S S'$  .

(3)  If  $J^p_{\mathfrak{X}}(\mathfrak{X}|S) = \coprod_{1\leq i\leq m} \mathfrak{Y}^{(i)}$  \underline{(disjoint union), then}

$\underline{I}^p_S(\mathfrak{X}|S) = \prod_{1\leq i\leq m} \underline{I}^0_S(f_*\underline{O}_{\mathfrak{Y}(i)})$  . \underline{In particular if}

\begin{equation*}
|J^p_{X_0}(X_0|S_0)| = \{x_1,\ldots,x_m\}
\end{equation*}
\underline{is discrete, then}

\begin{equation*}
\underline{I}^p_S(\mathfrak{X}|S) = \prod_{1\leq i\leq m} \underline{I}^p_S(\mathfrak{X}_{(x_i)}|S) = \prod_{1\leq i\leq m} \underline{I}^p_S(\mathfrak{X}_{(\hat{x}_i)}|S)
\end{equation*}
(4)  \underline{Let}  $S$  \underline{be an ordinary noetherian scheme and}  $X$  \underline{an} $S$-\underline{scheme of essentially finite type. Given a closed subscheme}  $S_0 \to S$  , \underline{let}  $\hat{S}$  \underline{be the formal completion of}  $S$  \underline{along}  $S_0$  . \underline{If we set}  $\hat{X} = X \times_S \hat{S}$ $=$ \underline{the formal completion of}  $X$  \underline{along}  $X_0 = X \times_S S_0$  , \underline{then}  $J^p_{\hat{S}}(\hat{X}|\hat{S}) = J^p_S(X|S) \times_S \hat{S}$ $=$ \underline{the formal completion of}  $J^p_S(X|S)$  \underline{along}  $J^p_{S_0}(X_0|S_0)$  .

\underline{Proof}:  Supp $f_*\underline{O}_{J^p_{\mathfrak{X}}(\mathfrak{X}|S)}$ $=$ $|J^p_S(\mathfrak{X}|S)|$  by 5.1(c), and hence (1) follows. (2) and (4) are clear from 5.1(a), and (3) follows from 5.1(d), and the isomorphism $J^p_{\mathfrak{X}_{(\hat{x})}}(\mathfrak{X}_{(\hat{x})}|S) \xrightarrow{\sim} J^p_{\mathfrak{X}_{(x)}}(\mathfrak{X}_{(x)}|S)$  for an isolated point  $x$  in  $J^p_{\mathfrak{X}}(\mathfrak{X}|S)$  .

\underline{Remark} 5.11.  Our definition of Jacobian ideal, adopted from the classical one over base field, commutes with base change and gives a smoothness criteria under a mild condition of 5.4. However one can define, probably in many different ways, a canonical subscheme which gives the non-smooth locus in a general setting. We shall outline one here:  Given an $A$-algebra  $B$  , define  $I_{B|A} = \bigcap_E \mathrm{Ann}\ D^1(B|A,E)$ where  $E$  runs through all  $B$-modules of finite type. This ideal  $I_{B|A}$  commutes with localizations by 3.13(c), and therefore, given a morphism  $X \xrightarrow{\ f\ } Y$  , we obtain the ideal sheaf  $\underline{I}_{X|Y}$  . If  $f$  is a morphism of essentially finite type, then  $f$  is smooth at  $x$  if and only if  $x \notin \mathrm{Supp}\ \underline{O}_X/\underline{I}_{X|Y}$  by 3.13(a). This notion is in an obvious way carried over to adic formal schemes of essentially

finite type and thus it is equally suitable for deformation theory.


6.  \underline{Non-degenerate quadratic singularities}

The objective in this section is to investigate the deformations of a $k$-scheme having non-degenerate quadratic singularities only. In view of 4.13, it becomes purely a local problem in an appropriate situation.

We go back to the notations of  §4. Thus  $\Lambda$  is a fixed complete noetherian local ring with the residue field  $k$  , and  $\underline{C}_\Lambda$  stands for the category of local artinian $\Lambda$-algebras with the same residue field  $k$  .

Let  $X$  be a $k$-scheme of finite type, and let  $x$  be a closed point of $X$  . We recall that the point  $x$  is said to be a non-degenerate quadratic singularity rational over  $k$  if  $\hat{O}_{X,x}$ $\simeq$ $k$ $[[x_1,\ldots,x_n]]/(f)$  with $(\partial f/\partial x_1,\ldots,\partial f/\partial x_n) = (x_1,\ldots,x_n)$  . One  can always assume  $f$  to be a quadratic form. Indeed we have

\underline{Lemma} 6.1.  \underline{Let}  $f \in k[[x_1,\ldots,x_n]]$  . \underline{If}  $(\partial f/\partial x_1,\ldots,\partial f/\partial x_n) = M$  $(= (x_1,\ldots,x_n))$, \underline{then one can find}  $x_1',\ldots,x_n'$  \underline{with}  $x_i = x_i'$  (mod $M^2$)  \underline{such that} $f = q(x_1',\ldots,x_n')$  \underline{where}  $q$  \underline{is a quadratic form.}

\underline{Proof}:  We do this by a successive approximation. Write  $f = f_2 + h_3$  where  $f_2$ is a quadratic form and  $h_3 \in M^3$  . Since  $(\partial f/\partial x_1,\ldots,\partial f/\partial x_n) = M$  , there exists $\epsilon_1^{(1)},\ldots,\epsilon_n^{(1)}$  in  $M^2$  such that  $\Sigma\ \epsilon_i^{(1)}\ \partial f/\partial x_i \equiv h_3$  (mod $M^4$)  . If we set $x_i^{(1)} = x_i - \epsilon_i^{(1)}$  , then  $f(x_1^{(1)},\ldots,x_n^{(1)}) =$ $f(x_1,\ldots,x_n) - \Sigma\ \epsilon_i^{(1)}\ \partial f/\partial x_i + \ldots \equiv f_2(x_1,\ldots,x_n)$  (mod $M^4$)  i.e., $f(x_1^{(1)},\ldots,x_n^{(1)}) \equiv f_2(x_1,\ldots,x_n) + h_4$  with  $h_4 \in M^4$  . Now $(\partial f/\partial x_1^{(1)},\ldots,\partial f/\partial x_n^{(1)}) = (\partial f/\partial x_1,\ldots,\partial f/\partial x_n) = M$  and therefore we can choose

$\varepsilon_1^{(2)},\dots,\varepsilon_n^{(2)}$  in  $M^3$  such that  $\Sigma\ \varepsilon_i^{(2)}\ \partial f/\partial x_i^{(1)} \equiv h_4\ (\mathrm{mod}\ M^5)$ . Then $f(x_1^{(1)} - \varepsilon_1^{(2)},\dots,x_n^{(1)} - \varepsilon_n^{(2)}) = f(x_1^{(1)},\dots,x_n^{(1)}) - \Sigma\ \varepsilon_i^{(2)}\partial f/\partial x_i^{(1)} + \dots \equiv f_2(x_1,\dots,x_n)\ (\mathrm{mod}\ M^5)$ . Continuing this process we can find $\varepsilon_i^{(1)},\ \varepsilon_i^{(2)},\ \varepsilon_i^{(3)},\dots$  $(i = 1,2,\dots,n)$  with  $\varepsilon_i^{(v)} \in M^{v+1}$  such that if we set $x_i^{(v)} = x_i - (\varepsilon_i^{(1)} + \dots + \varepsilon_i^{(v)})$  then  $f(x_1^{(v)},\dots,x_n^{(v)}) \equiv f_2(x_1,\dots,x_n)$ $(\mathrm{mod}\ M^{v+3})$ . Thus if we set  $\varepsilon_i = \sum_{v} \varepsilon_i^{(v)}$  then  $f(x_1-\varepsilon_1,\dots,x_n-\varepsilon_n) =$ $= f_2(x_1,\dots,x_n)$  i.e.,  $f(x_1,\dots,x_n) = f_2(x_1+\varepsilon_1,\dots,x_n+\varepsilon_n)$ .

\underline{Lemma} 6.2.   \underline{Let}  $A_0$  \underline{be a local} $k$-\underline{algebra, essentially of finite type such that}

\begin{equation*}
\hat{A}_0 \simeq k[[x_1,\dots,x_n]]/(f)
\end{equation*}
\underline{where}  $f$  \underline{is a non-degenerate quadratic form, and let}  $(R,\ \mathfrak{X})$  \underline{be a formal versal deformation of}  $X_0 = \mathrm{Spec}(A_0)$  . \underline{Then}

(1)  $J_{\mathfrak{X}}(\mathfrak{X}|R) \rightarrow J_R(\mathfrak{X}|R) \rightarrow \mathrm{Spec}(\Lambda)$  \underline{are both isomorphisms.}

(2)  $I_R(\mathfrak{X}|R)$  \underline{is a principal ideal in}  $R$  \underline{generated by a free formal generator of}  $R$  \underline{over}  $\Lambda$  i.e.  $I_R(\mathfrak{X}|R) = (t)$  \underline{and}  $R = \Lambda[[t]]$  .

(3)  $\mathfrak{X} \rightarrow \mathrm{Spec}(\Lambda)$  \underline{is formally smooth.}

\underline{Proof}:  We set  $\mathfrak{X} = \mathrm{Spf}(A)$  . By 4.10(b),  $(R,\ \mathrm{Spf}(\hat{A}))$  is a formal versal deformation of  $\hat{X}_0 = \mathrm{Spec}(\hat{A}_0)$  where  $\hat{A} = \varprojlim_{v} A \otimes_R R_v$  . Now  $\hat{A}_0 \simeq k[[x_1,\dots,x_n]]/(f)$  and  $(\partial f/\partial x_1,\dots,\partial f/\partial x_n) = (x_1,\dots,x_n)$  in $k[[x_1,\dots,x_n]]$  . It follows readily that  $[\underline{M}_{\hat{X}_0}(k[\varepsilon])] \simeq k$  and, by 4.14, we get

\begin{equation*}
R \simeq \Lambda[[t]] \quad\text{and}\quad \hat{A} \simeq R[[x_1,\dots,x_n]]/(F - t)
\end{equation*}
where  $F$  is a quadratic polynomial in  $\Lambda[x_1,\dots,x_n]$  $(\subset R[[x_1,\dots,x_n]])$ obtained from  $f$  by lifting the coefficients to  $\Lambda$  . Now

\begin{equation*}
0 \rightarrow \hat{A} \ \overset{dF}{\longrightarrow}\ \hat{A}dx_1 \oplus \dots \oplus \hat{A}dx_n \ \xrightarrow{\hspace{3em}}\ \hat{\Omega}_{\hat{A}|R} \rightarrow 0 
\end{equation*}



 is exact where  $dF : \hat{A} \rightarrow \hat{A}dx_1 \oplus \dots \oplus \hat{A}dx_n$  is given by $1 \rightarrow (\partial F/\partial x_1)dx_1 + \dots + (\partial F/\partial x_n)dx_n$  , and therefore $I_{\hat{A}}(\hat{A}|R) = (\partial F/\partial x_1,\dots,\partial F/\partial x_n) = (x_1,\dots,x_n)$  , and hence $\hat{A}/I_{\hat{A}}(\hat{A}|R) = \hat{A}/(x_1,\dots,x_n) = R[[x_1,\dots,x_n]]/(x_1,\dots,x_n,F - t) \simeq \Lambda$ i.e., the canonical map  $\Lambda \rightarrow \hat{A}/I_{\hat{A}}(\hat{A}|R)$  is an isomorphism. It follows that $\hat{A}/I_{\hat{A}}(\hat{A}|R) \rightarrow A/I_A(A|R)$  is an isomorphism, and consequently  $\Lambda \rightarrow R/I_R(A|R)$  is also an isomorphism. This proves (1) and (2). On the other hand, (3) follows from $\hat{A} \simeq R[[x_1,\dots,x_n]]/(F - t) \simeq \Lambda[[t,x_1,\dots,x_n]]/(F - t) \simeq \Lambda[[x_1,\dots,x_n]]$   as $\Lambda$-algebras.

\underline{Corollary} 6.3.  \underline{Let}  $X_0$  \underline{be a k-scheme of finite type, and let}  $x$  \underline{in}  $X_0$  \underline{be a non-degenerate quadratic singularity rational over}  $k$  .

(1)  \underline{Let}  $(R,\ \mathfrak{X})$ ,  $(R,\ \mathfrak{Y})$  \underline{be any two deformations of}  $X_0$  \underline{where} $R \in \mathrm{ob}(\hat{\underline{C}}_{\Lambda})$  . \underline{Assume that}  $k = k^2$  . \underline{Then}  $\mathfrak{X}_{(\widehat{x})} \simeq \mathfrak{Y}_{(\widehat{x})}$  \underline{as} $R$-\underline{adic formal schemes if and only if}  $I_R(\mathfrak{X}_{(\mathrm{x})}|R) = I_R(\mathfrak{Y}_{(\mathrm{x})}|R)$  .

(2)  \underline{Let}  $R \in \mathrm{ob}(\hat{\underline{C}}_{\Lambda})$  \underline{be a regular local ring, and let}  $(R,\ \mathfrak{X})$  \underline{be a deformation of}  $X_0$  . \underline{Then}  $O_{\mathfrak{X},x}$  \underline{is a regular local ring if and only if} $I_R(\mathfrak{X}_{(\mathrm{x})}|R) \not\subset \underline{m}_R^{\,2}$  i.e., \underline{if and only if}  $I_R(\mathfrak{X}_{(\mathrm{x})}|R)$  \underline{is a regular divisor in} $\mathrm{Spf}(R)$  .

\underline{Proof:}  Let  $(R_0,\ Z)$  be a formal versal deformation of  $\mathrm{Spec}(\hat{\underline{O}}_{X_0,x})$  . Since  $x$ in  $X_0$  is a non-degenerate quadratic singularity rational over  $k$  , we may assume that  $R_0 \simeq \Lambda[[t]]$  and  $Z \simeq \mathrm{Spf}(R_0[[x_1,\dots,x_n]]/(F - t))$  as in 6.2.

(1)  $(R,\ \mathfrak{X}_{(\widehat{x})})$ ,  $(R,\ \mathfrak{Y}_{(\widehat{x})})$  are deformations of  $\mathrm{Spec}(\hat{\underline{O}}_{X_0,x})$  , and therefore they are induced from  $(R_0,\ Z)$  by continuous local $\Lambda$-algebra maps $\varphi,\ \psi : R_0 \rightarrow R$  respectively, i.e., if we set  $a = \varphi(t)$  ,  $b = \psi(t)$  , then

\begin{equation*}
\mathfrak{X}_{(\widehat{x})} \simeq \mathrm{Spf}(R[[X_1,\dots,X_n]]/(F - a)) \quad ,
\end{equation*}
\begin{equation*}
\mathfrak{Y}_{(\widehat{x})} \simeq \mathrm{Spf}(R[[X_1,\dots,X_n]]/(F - b))
\end{equation*}
as $R$-adic formal schemes. Assume that  $I_R(\mathfrak{X}_{(\mathrm{x})}|R) = I_R(\mathfrak{Y}_{(\mathrm{x})}|R)$  i.e.,

$(a) = (b)$ in $R$ . Then $a = ub$ for some unit $u$ in $R$ . We construct a matrix $T\in\operatorname{GL}_n(R)$ such that $F(TX)=uF(X)$.\footnote{Editorial proof repair: the printed inference that every unit of $R$ has a square root need not hold in characteristic $2$. The following argument retains the original hypotheses.} Write $\mathfrak m=\mathfrak m_R$, and interpret polynomial congruences coefficientwise. Since $k=k^2$, choose $c\in R^\times$ whose residue satisfies $\bar c^2=\bar u$, and put $T_1=cI_n$. Then $F(T_1X)\equiv uF(X)\pmod{\mathfrak m}$. By the nondegeneracy condition in Lemma 6.2, the coefficient matrix of the linear forms $\partial F/\partial X_i$ is invertible modulo $\mathfrak m$, hence over $R$.  Suppose $T_\nu\in\operatorname{GL}_n(R)$ satisfies $F(T_\nu X)\equiv uF(X)\pmod{\mathfrak m^\nu}$, with $\nu\geq1$. The forms $(\partial F/\partial X_i)(T_\nu X)$ form an $R$-basis of the linear forms. Consequently, there are linear forms $L_i$ with coefficients in $\mathfrak m^\nu$ such that \[ E_\nu(X):=uF(X)-F(T_\nu X)  =\sum_i L_i(X)\frac{\partial F}{\partial X_i}(T_\nu X). \] Indeed, every quadratic monomial is a product of two linear forms, and expressing one factor in this basis preserves its coefficient ideal. Define $H_\nu$ by $H_\nu X=(L_i(X))_i$, and set $T_{\nu+1}=T_\nu+H_\nu$. The quadratic identity gives \[ F(T_{\nu+1}X)=F(T_\nu X)+E_\nu(X)+F(H_\nu X)  \equiv uF(X)\pmod{\mathfrak m^{\nu+1}}, \] since the coefficients of $F(H_\nu X)$ lie in $\mathfrak m^{2\nu}\subseteq\mathfrak m^{\nu+1}$. Moreover, $T_{\nu+1}\equiv T_\nu\pmod{\mathfrak m^\nu}$. Completeness and separatedness therefore give a limit $T\equiv cI_n\pmod{\mathfrak m}$ with $F(TX)=uF(X)$; in particular, $T$ is invertible. The substitution $X\mapsto TX$ sends $F-a$ to $u(F-b)$ and induces the required isomorphism \[ R[[X_1,\ldots,X_n]]/(F-a)  \xrightarrow{\ \sim\ } R[[X_1,\ldots,X_n]]/(F-b). \] The converse follows from invariance of $I_R$ under $R$-isomorphisms.

(2)  There exists a continuous local $\Lambda$-algebra map $\varphi : R_0 = \Lambda[[t]] \to R$ such that $\mathfrak{X}_{(\widehat{x})} \simeq \mathrm{Spf}(R[[X_1,\ldots,X_n]]/(F - \varphi(t)))$ . We note that $I_R(\mathfrak{X}_{(x)}|R) = I_R(\mathfrak{X}_{(\widehat{x})}|R) = (\varphi(t))$ , and that $R[[X_1,\ldots,X_n]]/(F - \varphi(t)) = \hat{\underline{O}}_{\mathfrak{X},x}$ is regular if and only if $\underline{O}_{\mathfrak{X},x}$ is regular. Now $R$ is regular and hence $R[[X_1,\ldots,X_n]]$ is also a regular local ring. Thus if we set $M$ to be the maximal ideal of $R[[X_1,\ldots,X_n]]$ , then $R[[X_1,\ldots,X_n]]/(F - \varphi(t))$ is regular if and only if $F - \varphi(t)$ is not in $M^2$ , i.e. if and only if $\varphi(t) \notin \underline{m}_R^{\,2}$ , i.e., if and only if $I_R(\mathfrak{X}_{(x)}|R) \not\subset \underline{m}_R^{\,2}$ .

\underline{Theorem} 6.4.  \underline{Let} $X_0$ \underline{be a} $k$-\underline{scheme of finite type with isolated non-smooth points only, and let} $(R, \mathfrak{X})$ \underline{be a formal versal deformation of} $X_0$ . \underline{Denote by} $\{z_1,\ldots,z_m\}$ \underline{the set of non-smooth points in} $X_0$ . \underline{Assume that} $H^2(X_0, \underline{D}^0_{X_0}) = 0$ , \underline{and all} $z_i$'s \underline{are non-degenerate quadratic singularity rational over} $k$ . \underline{Then}

(1)  $R$ \underline{is formally smooth over} $\Lambda$ i.e., $R$ \underline{is a formal power-series ring over} $\Lambda$ ;

(2)  $J_{\mathfrak{X}}(\mathfrak{X}|R) = \coprod_{1\leq i\leq m} J_{\mathfrak{X}_{(z_i)}}(\mathfrak{X}_{(z_i)}|R)$  \underline{(disjoint union), and}

$J_{\mathfrak{X}_{(z_i)}}(\mathfrak{X}_{(z_i)}|R) \;\overset{\sim}{\relbar\relbar\relbar}\; J_R(\mathfrak{X}_{(z_i)}|R)$  \underline{is an isomorphism};

(3)  $I_R(\mathfrak{X}_{(z_i)}|R)$ \underline{is a principal ideal and in turn so is}

$I_R(\mathfrak{X}|R) = \prod_{1\leq\ i\leq\ m} I_R(\mathfrak{X}_{(z_i)}|R)$ . \underline{Furthermore if we set} $I_R(\mathfrak{X}_{(z_i)}|R) = (t_i)$ , \underline{then} $t_1,\ldots,t_m$ \underline{can be extended to a system of free formal generators of} $R$ \underline{over} $\Lambda$ (\underline{as formal power-series ring over} $\Lambda$ ).

(4)  $\mathfrak{X} \to \mathrm{Spec}(\Lambda)$ \underline{is smooth}, i.e. $J_{\mathfrak{X}}(\mathfrak{X}|\Lambda) = \varphi$ .




(5)  \underline{If} $X_0$ \underline{is a complete irreducible curve, then} $\dim \underline{M}_{X_0} = 3g - 3 + a$ \underline{where} $g = \dim_k H^1(X_0, \underline{O}_{X_0})$ \underline{and} $a = \dim_k H^0(X_0, \underline{D}^0_{X_0})$ .

\underline{Proof:}  (1) follows from (2) and (3): The first statement of (2) follows from 5.7(2). Now let $(R_i, \mathfrak{Y}_i)$ be a formal versal deformation of $\mathrm{Spec}(\hat{\underline{O}}_{X_0,z_i})$ . Since $(R, \mathfrak{X}_{(\widehat{z}_i)})$ is a deformation of $\mathrm{Spec}(\hat{\underline{O}}_{X_0,z_i})$ , there exists a continuous local $\Lambda$-algebra maps $\varphi_i : R_i \to R$ with a cartesian diagram

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=huge]
\mathfrak{X}_{(\widehat{z}_i)} \arrow[r] \arrow[d] & \mathfrak{Y}_i \arrow[d] \\
\mathrm{Spf}(R) \arrow[r, "{\mathrm{Spf}(\varphi_i)}"'] & \mathrm{Spf}(R_i)
\end{tikzcd}
\end{center}













Therefore we have

\begin{equation*}
J_{\mathfrak{X}_{(z_i)}}(\mathfrak{X}_{(z_i)}|R) = J_{\mathfrak{X}_{(\widehat{z}_i)}}(\mathfrak{X}_{(\widehat{z}_i)}|R) \simeq J_{\mathfrak{Y}_i}(\mathfrak{Y}_i|R_i) \underset{\mathrm{Spf}(R_i)}{\times} \mathrm{Spf}(R)
\end{equation*}
\begin{equation*}
J_R(\mathfrak{X}_{(z_i)}|R) = J_R(\mathfrak{X}_{(\widehat{z}_i)}|R) \simeq J_{R_i}(\mathfrak{Y}_i|R_i) \underset{\mathrm{Spf}(R_i)}{\times} \mathrm{Spf}(R) \quad .
\end{equation*}
Since $J_{\mathfrak{Y}_i}(\mathfrak{Y}_i|R_i) \to J_{R_i}(\mathfrak{Y}_i|R_i)$ is an isomorphism by 6.2(1), we have that the canonical morphism $J_{\mathfrak{X}_{(z_i)}}(\mathfrak{X}_{(z_i)}|R) \to J_R(\mathfrak{X}_{(z_i)}|R)$ is an isomorphism. Now $I_{R_i}(\mathfrak{Y}_i|R_i) = (u_i) = (u_i)$ with $R_i = \Lambda[[u_i]]$ by 6.2(2), and therefore

\begin{equation*}
I_R(\mathfrak{X}_{(z_i)}|R) = I_R(\mathfrak{X}_{(\widehat{z}_i)}|R) = (t_i)
\end{equation*}
where $t_i = \varphi_i(u_i)$ , and therefore $I_R(\mathfrak{X}|R) = \prod_{1\leq\ i\leq\ m} I_R(\mathfrak{X}_{(z_i)}|R) = (\ \prod_{i=1}^{m} t_i\ )$ .

Now $\underline{M}_{X_0} \to \underline{M}_{X_0,(\widehat{z}_1)} \times \ldots \times \underline{M}_{X_0,(\widehat{z}_m)}$ is smooth by and therefore $R_1 \hat{\otimes}_{\Lambda} \ldots \hat{\otimes}_{\Lambda} R_m \to R$ is formally smooth by 4.13, which implies that $t_1,\ldots,t_m$ is extended to a system of free formal generators of $R$ over $\Lambda$ .




(4)  The projection morphism  $\mathfrak{X}_{(\widehat{z}_i)} \overset{\sim}{\rightarrow} \mathfrak{Y}_i \times_{\mathrm{Spf}(R_i)} \mathrm{Spf}(R) \rightarrow \mathfrak{Y}_i$  is formally smooth since  $\mathrm{Spf}(R) \xrightarrow{\ \mathrm{Spf}(\varphi_i)\ } \mathrm{Spf}(R_i)$  is formally smooth. On the other hand, $\mathfrak{Y}_i \rightarrow \mathrm{Spec}(\Lambda)$  is formally smooth by 6.2(3)  and therefore  $\mathfrak{X}_{(\widehat{z}_i)} \rightarrow \mathrm{Spec}(\Lambda)$  is formally smooth. Consequently  $\mathfrak{X} \rightarrow \mathrm{Spec}(\Lambda)$  is formally smooth since  $\{z_1,\dots,z_m\}$  is the set of non-smooth points of  $X_0$ .

(5)  Since  $R$  is formally smooth over  $\Lambda$  and

\begin{equation*}
0 \rightarrow H^1(X_0,\ \underline{D}^0_{X_0})\ \rightarrow [\underline{M}_{X_0}(k[\varepsilon])] \rightarrow H^0(X_0,\ \underline{D}^1_{X_0}) \rightarrow 0
\end{equation*}
is exact by 4.4 and 4.11, we have

\begin{equation*}
\begin{aligned}
\dim \underline{M}_{X_0} \ &= \ \dim k \otimes R \ = \ \dim_k H^1(X_0,\ \underline{D}^0_{X_0}) + \dim H^0(X_0,\ \underline{D}^1_{X_0})\\
&= \ \dim_k H^1(X_0,\ \underline{D}^0_{X_0}) + m \ .
\end{aligned}
\end{equation*}
Then it suffices to show that

\begin{equation*}
\dim_k H^1(X_0,\ \underline{D}^0_{X_0}) + m = 3g - 3 + \dim_k H^0(X_0,\ \underline{D}^0_{X_0})
\end{equation*}
i.e.,  $\chi(\underline{D}^0_{X_0}) = 3 - 3g + m$

where we set  $\chi(\underline{E}) = \dim_k H^0(X_0,\ \underline{E}) - \dim_k H^1(X_0,\ \underline{E})$  for any coherent  $X_0$-module  $\underline{E}$ . Since  $\chi(\underline{D}^0_{X_0})$  does not change when one replaces the base field  $k$  by its algebraic closure, we may assume that  $k$  is algebraically closed. Set  $A = \underline{O}_{X_0,z}$ , where  $z$  is a non-smooth point of  $X_0$ , and let  $A'$  be its normalization. By hypothesis, we have  $A \simeq k[[x,y]]/(f)$  where  $f$  is a non-degenerate quadratic form. Since  $k$  is algebraically closed, we may assume that  $f = xy$ , i.e., $A \simeq k[[x,y]]/(xy)$ . From this we conclude immediately that  $\ell(A'/A) = 1$  and  $\mathrm{Der}_k(A,\ \underline{m}_A) = \mathrm{Der}_k(A,\ A)$ . Let  $C$  be the conductor of  $A$  in  $A'$ . Since $A$ is a complete-intersection we must have that  $\ell(A/C) = \ell(A'/A) = 1$  so that  $C = \underline{m}_A$ . We thus obtain that  $A' = \{a' \in K |\ a'\underline{m}_A \subset \underline{m}_A\}$  where  $K$  is the fraction field of  $A$ . We now claim that  $\mathrm{Der}_k(A,\ A) \subset \mathrm{Der}_k(A',\ A')$  as $A$-modules contained in  $\mathrm{Der}_k(K,\ K)$ . Indeed, let  $X \in \mathrm{Der}_k(A,\ A)$ . Then for any  $a' \in A'$  and

$x \in \underline{m}_A$  we have  $xa' \in \underline{m}_A$  so that  $X(xa') \in \underline{m}_A$  and  $a'X(x) \in \underline{m}_A$  since  $\mathrm{Der}_k(A,\ \underline{m}_A) = \mathrm{Der}_k(A,\ A)$ . Consequently  $X(xa') = a'X(x) + xX(a')$  entails that  $xX(a') \in \underline{m}_A$  for all  $x \in \underline{m}_A$ , and therefore  $X(a') \in A'$ . Furthermore, the exact sequence

\begin{equation*}
0 \ \rightarrow\ \mathrm{Der}_k(A,\ A) \rightarrow \mathrm{Der}_k(A',\ A') \rightarrow A'/\underline{m}_A A' \rightarrow\ 0
\end{equation*}
entails the exact sequence

\begin{equation*}
0 \ \rightarrow\ \mathrm{Der}_k(A,\ A) \rightarrow \mathrm{Der}_k(A',\ A') \rightarrow A'/C \rightarrow 0
\end{equation*}
Therefore if we set  $X'_0$  to be the normalization of  $X_0$ , then

\begin{equation*}
0 \rightarrow \underline{D}^0_{X_0} \rightarrow \underline{D}^0_{X'_0}\ \rightarrow \underline{O}_{X'_0}/C \rightarrow 0
\end{equation*}
is exact. Since  $X_0$  is locally a complete-intersection, we have  $\ell(\underline{O}_{X'_0}/C) = 2\ell(\underline{O}_{X'_0}/\underline{O}_{X_0}) = 2m$ , whereas  $\chi(\underline{D}^0_{X'_0}) = 3 - 3(g-m)$  by Riemann-Roch theorem. Consequently

\begin{equation*}
\chi(\underline{D}^0_{X_0}) = \chi(\underline{D}^0_{X'_0}) - \ell(\underline{O}_{X'_0}/C) = 3 - 3(g-m) - 2m = 3 - 3g + m \ .
\end{equation*}
This completes our proof.

\underline{Remark} 6.5.  In the formula 6.4(5), the number  $a = H^0(X_0,\ \underline{D}^0_{X_0})$  can be easily computed in terms of Riemann-Roch theorem. Thus

\begin{equation*}
a = \left\{ \begin{array}{lll} 0 & \text{if} & g \geq 2 \\[4pt] 1 & \text{if} & g = 1 \\[4pt] 3 & \text{if} & g = 0 \end{array} \right.
\end{equation*}
Finally we add a remark on characteristic 2. If the characteristic of the base field  $k$  is  $2$ , there is no non-degenerate quadratic form on  $n$  variables if  $n$  is odd. In other words there does not exist a non-degenerate quadratic singularity of even dimension if  $\mathrm{char}\, k = 2$ . In this case one may consider a quadratic form of maximum non-degeneracy: 




\underline{Definition} 6.6.  \underline{Let}  $X$  \underline{be a} k-\underline{scheme of finite type.} \underline{A closed point}  $z \in X$  \underline{is called an ordinary quadratic singularity rational over}  $k$  \underline{if the following holds:}

(i)  \underline{If either}  $char k \neq 2$  \underline{or}  $char k = 2$  \underline{and}  $dim O_{X,z}$  \underline{is odd, then} $z$  \underline{is a non-degenerate quadratic singularity rational over}  $k$  .

(ii)  \underline{If}  $char k = 2$  \underline{and}  $dim O_{X,z}$  \underline{is even, then} $\bar{k} \underset{k}{\otimes} \hat{O}_{X,z} \simeq \bar{k}[[X_0, X_1, \ldots, X_{2n}]]/(f)$  \underline{with}

\begin{equation*}
f = X_0^2 + X_1X_2 + X_3X_4 + \ldots + X_{2n-1}X_{2n}
\end{equation*}
\underline{where}  $\bar{k}$  \underline{is the algebraic closure of}  $k$  .

\underline{Lemma} 6.7.  \underline{Let}  $k$  \underline{be a field of characteristic}  $2$  \underline{and}  \underline{set} $A_0 = k[[X_0, X_1, \ldots ,X_{2n}]]/(f)$  \underline{where}

\begin{equation*}
f = X_0^2 + X_1X_2 + X_3X_4 + \ldots + X_{2n-1}X_{2n} \quad ,
\end{equation*}
\underline{and let}  $(R, \mathfrak{X})$  \underline{be a formal versal deformation of}  $X_0 = \mathrm{Spec}(A_0)$  . \underline{Then} $R = \Lambda[[t, t_1]]$  , \underline{where}  $t, t_1$  \underline{are free formal generators of}  $R$  \underline{over}  $\Lambda$  , \underline{such} \underline{that}  $I_R(\mathfrak{X}|R) = (t^2)$  , \underline{and}  $\mathfrak{X} \to \mathrm{Spec}(\Lambda)$  \underline{is formally smooth.}

\underline{Proof:}  We set  $\mathfrak{X} = \mathrm{Spf}(A)$  . Since

\begin{equation*}
(f, \frac{\partial f}{\partial X_0} , \ldots , \frac{\partial f}{\partial X_{2n}} ) = (X_0^2, X_1, \ldots , X_{2n}) \quad ,
\end{equation*}
it follows that  $D^1(A_0|k, A_0) \simeq  k[X_0]/(X_0^2)$  and therefore  $[\underline{M}_{X_0}(k[\epsilon])]$  is 2-dimensional vector space over  $k$  . Furthermore, it follows from 4.14 that

\begin{equation*}
R \simeq \Lambda[[t, t_1]] \quad \text{and} \quad A \simeq R[[X_0, X_1, \ldots ,X_{2n}]]/(F)
\end{equation*}
where  $F = f + t_1 + tX_0$  . Now the exact sequence

\begin{center}
\begin{tikzcd}[column sep=large]
0 \arrow[r] & A \arrow[r, "dF"] & AdX_0 \oplus \ldots \oplus AdX_{2n} \arrow[r] & \hat{\Omega}_{A|R} \arrow[r] & 0
\end{tikzcd}
\end{center}

\begin{equation*}
dF = 1 \to \sum_{0 \leq i \leq 2n} \frac{\partial f}{\partial X_i} dX_i + t\,dX_0 \quad , 
\end{equation*}



 entails that

\begin{equation*}
I_A(A|R) = (t, x_1, x_2, \ldots, x_{2n}) = (x_0^2 + t_1, t, x_1, \ldots, x_{2n})
\end{equation*}
so that

\begin{equation*}
A/I_A(A|R) \simeq A/(X_0^2 + t_1, t, x_1, \ldots, x_{2n}) \simeq \Lambda[[t_1, X_0]]/(X_0^2 - t_1)  \ .
\end{equation*}
Since  $\Lambda[[t_1, X_0]]/(X_0^2 - t_1) \simeq R/(t) \oplus R/(t)$  as R-modules, it follows that $I_R(A|R) = (t^2)$  , which proves our first assertion. On the other hand,

\begin{equation*}
\begin{aligned} A &\simeq \Lambda[[t, t_1, x_o, x_1, \ldots, x_{2n}]]/(X_0^2 + X_1X_2 + \ldots + X_{2n-1}X_{2n} + tX_0 + t_1) \\ &\simeq \Lambda[[t, X_0, X_1,\ldots,X_{2n}]] \end{aligned}
\end{equation*}
and therefore  $A$  is formally smooth over  $\Lambda$  .

The above statement 6.7 yields a similar result as 6.4, proof of which we leave to the readers.

\underline{Corollary} 6.8.  \underline{Let}  $X_0$  \underline{be a} k-\underline{scheme of finite type with isolated non-smooth points only such that}  $H^2(X_0, \underline{D}^0_{X_0}) = 0$  , \underline{and let}  $(R, \mathfrak{X})$  \underline{be a formal versal deformation of}  $X_0$  . \underline{Denote by}  $\{z_1, \ldots, z_m\}$  \underline{the set of non-smooth points in} $X_0$  , \underline{and assume that}  $char k = 2$  , $dim X_0$  \underline{is even, and all}  $z_i$'s  \underline{are ordinary quadratic singularities. Then}

(1)  $R$  \underline{is formally smooth over}  $\Lambda$

(2)  $I_R(\mathfrak{X}_{(z_i)}|R)$  \underline{is a principal ideal and in turn so is}

$I_R(\mathfrak{X}|R) = \prod_{1 \leq i \leq m} I_R(\mathfrak{X}_{(z_i)}|R)$  . \underline{Furthermore,}  $I_R(\mathfrak{X}_{(z_i)}|R) = (t_i^2)$  \underline{and} $t_1, \ldots , t_m$  \underline{can be extended to a system of free formal generators of}  $R$  \underline{over} $\Lambda$  .

(3)  $\mathfrak{X} \to \mathrm{Spec}(\Lambda)$  \underline{is formally smooth}

(4)  \underline{If}  $k$  \underline{is algebraically closed and}  $X_0$  \underline{is a complete irreducible curve, then}  $dim \underline{M}_{X_0} = 3g - 3 + a$  \underline{where}  $g = dim_k H^1(X_0, \underline{O}_{X_0})$  \underline{and} $a = dim_k H^0(X_0, \underline{D}^0_{X_0})$  .
